/* 自动生成，请勿手工修改。来源：DSH physics/phy-magnet；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"phy-magnet-1","title":"磁现象与磁场","subtitle":"人教版九年级 · 第 20 章 电与磁 · 9a","grade":"9a","tags":["人教版九年级 · 第 20 章 电与磁"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 20 章 电与磁 · 9a"},{"type":"note","title":"问题切入","text":"两块磁体并不接触，为什么能互相推开、互相吸引？指南针为什么总是一头指南、一头指北？"},{"type":"note","title":"一句话抓住关键","text":"磁体周围存在磁场，磁极之间的相互作用是通过磁场发生的；磁场有方向，规定小磁针静止时 N 极所指的方向就是该点的磁场方向；磁感线是为了形象描述磁场而假想的曲线，磁体外部从 N 极出发回到 S 极。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"两块磁铁不用接触就能互相推拉，中间「空」的部分其实充满了看不见的磁场。","walk":["磁体两端磁性最强，叫磁极；同名磁极相斥，异名磁极相吸。磁体断开后，每一段仍有南北极。","磁场有方向：小磁针静止时 N 极所指的方向，就是该点的磁场方向。","磁感线是假想的曲线，磁体外部从 N 到 S，内部从 S 到 N，任何两条都不相交。"],"try":"把条形磁铁放在纸上，撒少量铁屑轻敲纸面，观察铁屑排成的曲线。","use":["判断磁极：用小磁针的 N 极指向判断。","地磁的南极在地理北极附近，所以小磁针 N 极指北。"]},{"type":"h","text":"先看现象：磁体能吸引什么，磁极之间怎样作用"},{"type":"p","text":"把条形磁体靠近铁钉、钴片、镍丝，会被吸住；靠近铜片、铝片、塑料、纸片，不会被吸住——磁体只能吸引铁、钴、镍这类物质。再把两个磁体互相靠近：N 极与 N 极相对，它们互相推开；N 极与 S 极相对，它们互相吸引。磁体上磁性最强的部分叫磁极，任何磁体都有两个磁极：指北的那端叫北极（N 极），指南的那端叫南极（S 极）。"},{"type":"figure","figure":{"id":"fig-magnet-pole-1","title":"磁极间的相互作用","caption":"同名磁极互相排斥，异名磁极互相吸引；两个磁体不接触也有力的作用","view":"wide","alt":"上半部分两个磁体相对的一端都是 N 极，左边的磁体被向左推、右边的磁体被向右推；下半部分左边磁体右端的 N 极对着右边磁体左端的 S 极，两个磁体互相吸引","prims":[{"t":"text","x":50,"y":5,"text":"同名磁极互相排斥","size":3.8,"tone":"muted"},{"t":"rect","x":14,"y":10,"w":20,"h":9,"tone":"danger","fill":true},{"t":"text","x":19,"y":14.5,"text":"S"},{"t":"text","x":29,"y":14.5,"text":"N"},{"t":"rect","x":66,"y":10,"w":20,"h":9,"tone":"danger","fill":true},{"t":"text","x":71,"y":14.5,"text":"N"},{"t":"text","x":81,"y":14.5,"text":"S"},{"t":"arrow","x1":34,"y1":26,"x2":16,"y2":26,"tone":"accent","label":"斥力"},{"t":"arrow","x1":66,"y1":26,"x2":84,"y2":26,"tone":"accent","label":"斥力"},{"t":"text","x":50,"y":35,"text":"异名磁极互相吸引","size":3.8,"tone":"muted"},{"t":"rect","x":14,"y":41,"w":20,"h":9,"tone":"danger","fill":true},{"t":"text","x":19,"y":45.5,"text":"S"},{"t":"text","x":29,"y":45.5,"text":"N"},{"t":"rect","x":66,"y":41,"w":20,"h":9,"tone":"danger","fill":true},{"t":"text","x":71,"y":45.5,"text":"S"},{"t":"text","x":81,"y":45.5,"text":"N"},{"t":"arrow","x1":34,"y1":56,"x2":48,"y2":56,"tone":"accent","label":"引力"},{"t":"arrow","x1":66,"y1":56,"x2":52,"y2":56,"tone":"accent","label":"引力"}]}},{"type":"note","title":"","text":"规范表述：磁极间的相互作用规律是「同名磁极互相排斥，异名磁极互相吸引」，不能只说「同性相斥」——磁、电、荷三者的说法要分清。"},{"type":"h","text":"抓住关键：磁场和磁场的方向"},{"type":"p","text":"两个磁体没有接触却有力的作用，说明磁体周围存在一种看不见、摸不着的物质——磁场。磁场的基本性质是对放入其中的磁体产生力的作用。磁场是有方向的：把小磁针放在磁场中的某一点，小磁针静止时 N 极所指的方向，就规定为这一点的磁场方向。要特别注意方向关系：小磁针 N 极所受磁场力的方向与该点的磁场方向相同，S 极所受磁场力的方向与该点的磁场方向相反。"},{"type":"figure","figure":{"id":"fig-magnet-field-1","title":"小磁针的 N 极指向就是该点的磁场方向","caption":"同一根小磁针放到磁场中不同的位置，N 极的指向不同——磁场各点的方向不同","view":"wide","alt":"一个条形磁体水平放置，左端是 N 极、右端是 S 极；磁体正上方的小磁针静止时 N 极指向右方，磁体左端外侧的小磁针静止时 N 极指向左方","prims":[{"t":"text","x":50,"y":8,"text":"磁场方向 = 小磁针静止时 N 极所指的方向","size":3.8,"tone":"muted"},{"t":"compass","x":50,"y":24,"deg":0,"label":"小磁针"},{"t":"text","x":50,"y":35,"text":"N 极指向右方","size":3.6,"tone":"muted"},{"t":"magnet","x":50,"y":50,"w":26,"h":9,"label":"条形磁体"},{"t":"compass","x":20,"y":50,"deg":180,"label":"小磁针"},{"t":"text","x":20,"y":59.5,"text":"N 极指向左方","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"不要把「小磁针 S 极的指向」当成磁场方向：S 极受力方向与磁场方向相反。"},{"type":"h","text":"建立联系：用磁感线把看不见的磁场画出来"},{"type":"p","text":"为了形象地描述磁场，我们假想出一系列曲线：让曲线上每一点的切线方向都跟该点的磁场方向一致，这样的曲线叫磁感线。规定磁体外部的磁感线从 N 极出发，回到 S 极；在磁体内部，磁感线从 S 极到 N 极，所以每一条磁感线都是闭合曲线。磁感线越密的地方磁场越强，越疏的地方磁场越弱；任何两条磁感线都不会相交，因为磁场中每一点的磁场方向只有一个。要记住：磁感线是为了研究方便假想出来的，实际上并不存在。"},{"type":"figure","figure":{"id":"fig-magnet-fieldline-1","title":"条形磁体周围的磁感线","caption":"磁感线从 N 极出发、绕到 S 极；磁极附近最密，磁场最强；正上方的小磁针 N 极与磁感线方向一致","view":"wide","alt":"条形磁体左端为 N 极、右端为 S 极，上下各画出两条从 N 极出发弯向 S 极的曲线，箭头由 N 极一侧指向 S 极一侧；磁体正上方的小磁针 N 极指向右方，与该处磁感线方向相同","prims":[{"t":"text","x":50,"y":4,"text":"磁感线从 N 极出发，回到 S 极","size":3.8,"tone":"muted"},{"t":"curve","points":[[37,34],[24,18],[50,10],[76,18],[63,34]],"tone":"accent","arrow":true},{"t":"curve","points":[[37,34],[33,24],[50,18],[67,24],[63,34]],"tone":"accent","arrow":true},{"t":"curve","points":[[37,38],[24,52],[50,58],[76,52],[63,38]],"tone":"accent","arrow":true},{"t":"curve","points":[[37,38],[33,46],[50,52],[67,46],[63,38]],"tone":"accent","arrow":true},{"t":"compass","x":50,"y":26,"deg":0,"label":"小磁针"},{"t":"magnet","x":50,"y":36,"w":26,"h":9,"label":"条形磁体"}]}},{"type":"h","text":"换一个情境：地球也是一个「大磁体」"},{"type":"p","text":"指南针能指示南北，说明地球周围存在磁场，这就是地磁场。地磁场的分布与一个条形磁体的磁场相似，但两极的位置要格外小心：地磁的南极（S 极）在地理北极附近，地磁的北极（N 极）在地理南极附近。所以小磁针的 N 极指向地理北方，是被地磁的 S 极吸引的结果。地磁的两极与地理的两极并不重合，小磁针所指的方向与地理南北方向之间有一个很小的角度，叫磁偏角；我国宋代学者沈括最早记述了这一现象。"},{"type":"figure","figure":{"id":"fig-magnet-earth-1","title":"地磁场与地理两极","caption":"地磁的 S 极在地理北极附近，地磁的 N 极在地理南极附近，所以小磁针的 N 极指向地理北方","view":"wide","alt":"一个代表地球的圆，圆内画着一根条形磁体：地球右侧（地理北极）附近是磁体的 S 极，地球左侧（地理南极）附近是磁体的 N 极；地球外的磁感线从左侧出发，绕过地球上方和下方回到右侧","prims":[{"t":"circle","cx":50,"cy":32,"r":16,"tone":"main","fill":true},{"t":"magnet","x":50,"y":32,"w":20,"h":7},{"t":"curve","points":[[36,20],[50,7],[64,20]],"tone":"accent","arrow":true},{"t":"curve","points":[[36,44],[50,57],[64,44]],"tone":"accent","arrow":true},{"t":"text","x":82,"y":24,"text":"地理北极","size":3.6},{"t":"text","x":82,"y":30,"text":"（地磁 S 极）","size":3.2,"tone":"muted"},{"t":"text","x":18,"y":24,"text":"地理南极","size":3.6},{"t":"text","x":18,"y":30,"text":"（地磁 N 极）","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"为便于画图，地轴画成水平方向","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"最常见的错误是写「地磁的北极在地理北极附近」，正好写反。"},{"type":"h","text":"再想一层：磁化与磁记录"},{"type":"p","text":"使原来没有磁性的物体获得磁性的过程叫磁化。把一根铁钉放在磁体附近（或用磁体沿同一方向摩擦几次），铁钉会被磁化，磁化后的铁钉相当于一个小磁体，能吸引其他铁制品，这就是磁体能吸起一串大头针的原因。铁被磁化后磁性容易消失，属于软磁性材料；钢被磁化后磁性能够长期保持，属于硬磁性材料，所以永磁体常用钢来制造。磁带、磁盘、银行卡的磁条都是利用磁性材料记录信息的：录音时把声音的变化转换成磁性的变化记录在磁带上，放音时再把磁信号转换成电信号还原成声音。"},{"type":"figure","figure":{"id":"fig-magnet-magnetize-1","title":"磁化现象","caption":"用磁体沿同一方向摩擦铁钉，铁钉获得磁性，可以把大头针吸成一串","view":"wide","alt":"左边是一根条形磁体，右边是一根铁钉，铁钉旁的双向箭头表示沿同一方向反复摩擦；铁钉的尖端吸着三枚大头针","prims":[{"t":"magnet","x":22,"y":20,"w":22,"h":8,"label":"条形磁体"},{"t":"poly","points":[[33,18],[54,18],[60,20],[54,22],[33,22]],"closed":true,"tone":"main","fill":true},{"t":"arrow","x1":36,"y1":11,"x2":56,"y2":11,"both":true,"tone":"accent","label":"沿同一方向摩擦"},{"t":"circle","cx":59,"cy":25,"r":1.4,"tone":"muted"},{"t":"circle","cx":61,"cy":28,"r":1.4,"tone":"muted"},{"t":"circle","cx":63,"cy":31,"r":1.4,"tone":"muted"},{"t":"text","x":50,"y":40,"text":"被磁化的铁钉相当于小磁体","size":3.6,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["磁场方向的规定","某点的磁场方向 = 放在该点的小磁针静止时 N 极所指的方向","方向用文字或箭头表示，没有单位 · 适用于一切磁场。用它判断磁体的磁极、判断磁感线的方向。注意三条方向必须一致：该点磁场方向、磁感线在该点的切线方向、小磁针 N 极的指向；小磁针 S 极的指向与磁场方向相反，不能拿来当磁场方向。"],["磁感线的方向与疏密","磁体外部：从 N 极出发回到 S 极；磁体内部：从 S 极到 N 极（磁感线是闭合曲线）；越密的地方磁场越强","没有单位，是描述磁场的模型 · 只用来描述磁场的方向和强弱。磁感线是假想的曲线，答题时不能写「磁感线真实存在」；任何两条磁感线不能相交，因为一点只有一个磁场方向。"]]},{"type":"h","text":"应用 · 磁体为什么能吸起一串大头针"},{"type":"note","title":"情境","text":"把条形磁体的一端靠近一枚大头针，大头针被吸住；再把第二枚大头针靠近第一枚的下端，第二枚也被吸住了，于是一枚接一枚地被吸成一串。"},{"type":"note","title":"模型与思路","text":"磁体周围有磁场，铁质大头针在磁场中被磁化；磁化后的大头针本身也成了小磁体，又能磁化并吸引下一枚大头针。"},{"type":"list","title":"解答步骤","items":["磁体周围存在磁场，磁场对放入其中的铁质大头针产生力的作用，第一枚大头针被吸住。","大头针是铁磁性物质，处在磁场中被磁化，成为一个小磁体：靠近磁体的一端出现与磁体相反的磁极，远离磁体的一端出现与磁体相同的磁极。","被磁化的大头针有了自己的磁场，于是又能把第二枚大头针磁化并吸住，如此一枚接一枚。","把磁体拿走，大头针的磁性很快消失（软磁性材料），成串的大头针就会掉下来。"]},{"type":"figure","figure":{"id":"fig-magnet-app-1","title":"一串被吸起的大头针","caption":"磁体先磁化第一枚大头针，第一枚再磁化并吸引第二枚","view":"wide","alt":"条形磁体的 N 极向下靠近一排竖直悬挂的大头针，大头针一枚接一枚地连成一条链","prims":[{"t":"magnet","x":50,"y":12,"w":30,"h":9,"label":"条形磁体"},{"t":"line","x1":40,"y1":17,"x2":40,"y2":28,"width":0.9},{"t":"line","x1":50,"y1":17,"x2":50,"y2":28,"width":0.9},{"t":"line","x1":60,"y1":17,"x2":60,"y2":28,"width":0.9},{"t":"line","x1":40,"y1":28,"x2":40,"y2":40,"width":0.9},{"t":"line","x1":50,"y1":28,"x2":50,"y2":40,"width":0.9},{"t":"line","x1":60,"y1":28,"x2":60,"y2":40,"width":0.9},{"t":"line","x1":40,"y1":40,"x2":40,"y2":52,"width":0.9},{"t":"line","x1":50,"y1":40,"x2":50,"y2":52,"width":0.9},{"t":"line","x1":60,"y1":40,"x2":60,"y2":52,"width":0.9},{"t":"text","x":24,"y":34,"text":"被磁化的大头针","size":3.6,"tone":"muted","anchor":"end"},{"t":"text","x":76,"y":34,"text":"下端成为新的磁极","size":3.6,"tone":"muted","anchor":"start"}]}},{"type":"note","title":"结论","text":"磁体可以磁化铁磁性物质，磁化后的物体又成为新的磁体，这是「磁体吸起一串大头针」的完整解释。"},{"type":"h","text":"应用 · 怎样用一枚小磁针判断一根钢棒有没有磁性"},{"type":"note","title":"情境","text":"桌面上有一根钢棒，不知道它是磁体还是普通的铁棒，手边只有一枚小磁针。"},{"type":"note","title":"模型与思路","text":"用磁极间的相互作用来判断：同名磁极互相排斥，异名磁极互相吸引；而没有磁性的铁磁性物质只会被吸引，绝不会排斥。"},{"type":"list","title":"解答步骤","items":["把小磁针放在水平桌面上，等它静止，看清它的 N 极。","把钢棒的一端靠近小磁针的 N 极：如果小磁针被吸过来，还不能下结论——钢棒可能是磁体，也可能是没有磁性但被磁化后吸引小磁针的铁棒。","换用钢棒的另一端再靠近小磁针的 N 极：如果这一次小磁针被明显排斥，那么钢棒一定有磁性，且这一端是 N 极。","如果两次靠近都只出现吸引，则钢棒没有磁性（或磁性很弱）。"]},{"type":"note","title":"结论","text":"判断物体有没有磁性，要靠「排斥」作证据；只有吸引不能说明对方是磁体。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["磁体周围真的存在一条一条的「磁感线」。","磁感线是为了形象描述磁场而假想的曲线，真实存在的是磁场。","画出磁感线，是为了把磁场的两个特征同时表示出来：曲线上的箭头表示方向，曲线的疏密表示强弱。它是模型，不是实物。"],["地磁的北极在地理北极附近。","地磁的 S 极在地理北极附近，地磁的 N 极在地理南极附近。","小磁针的 N 极指向地理北方，是「异名磁极互相吸引」的结果，所以地理北方附近必须是磁体的 S 极。"],["小磁针的 S 极指向就是该点的磁场方向。","规定小磁针静止时 N 极所指的方向为该点的磁场方向。","小磁针 N 极受到的磁场力方向与磁场方向相同，S 极受到的磁场力方向与磁场方向相反，两者正好相反。"],["把一根钢棒靠近小磁针，小磁针被吸引，说明钢棒一定是磁体。","被吸引只能说明钢棒可能是有磁性的磁体，也可能是没有磁性但被磁化了的铁磁性物质；只有出现排斥才能确定它是磁体。","无磁性的铁、钢在磁体附近会被磁化，磁化后同样能吸引小磁针，所以「吸引」不是磁性的判别依据。"]]},{"type":"table","title":"磁场与磁感线（一个是真实存在的物质，一个是为了描述它而假想的模型）","head":["比较项","磁场","磁感线"],"rows":[["是否真实存在","真实存在，看不见、摸不着，能对磁体产生力的作用","人为假想的曲线，实际上并不存在"],["方向","有方向，规定为小磁针静止时 N 极所指的方向","用曲线上的箭头表示该点的磁场方向"],["强弱","磁场越强，对放入其中的磁体作用越强","磁感线越密表示磁场越强，越疏表示越弱"],["主要用途","解释磁极间的相互作用、磁化等现象","把磁场的方向与强弱画成图，便于分析问题"]]},{"type":"table","title":"软磁性材料与硬磁性材料（磁化后磁性保持的能力不同，用途也不同）","head":["比较项","软磁性材料（如铁）","硬磁性材料（如钢）"],"rows":[["磁化难易","容易被磁化","较难被磁化"],["去磁难易","离开磁体后磁性很快消失，容易去磁","磁化后磁性可以长期保持"],["典型用途","电磁铁的铁芯、变压器铁芯","永磁体、指南针的磁针、扬声器的永磁体"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["磁感线作图与方向判断","给出磁体或磁场中的小磁针，要求画出磁感线并标出方向，或由小磁针的指向反过来判断磁体的磁极。要点：磁体外部磁感线从 N 极出发回到 S 极；小磁针 N 极的指向与磁感线方向一致；同名磁极之间磁感线互相「推开」，中间区域磁感线变疏。"],["实验探究：用铁屑显示磁场的分布","以「玻璃板上撒铁屑、轻敲后观察排列」为情境，考查轻敲的目的（减小摩擦，让铁屑能自由转动到磁场方向）、铁屑能显示磁场的原因（被磁化后相当于一个个小磁针），以及由排列得出的结论。答题一定要写出「铁屑被磁化」这一中间环节，否则不得分。"],["地磁场与磁偏角","常以史料加图示的方式考查：地磁两极与地理两极不重合、地磁 S 极在地理北极附近、沈括最早记述磁偏角、指南针能指南北的原因。答「地磁北极在地理北极附近」属于方向性错误。"]]},{"type":"quote","text":"【材料一】我国古代很早就利用磁现象制造了指向工具。战国时期的司南用天然磁石琢成，形状像一只汤勺，放在光滑的地盘上，静止时勺柄指向南方。北宋时人们已经会用人工磁化的方法制作指南针，并把它用于航海。\n【材料二】北宋学者沈括在《梦溪笔谈》中写道：「方家以磁石磨针锋，则能指南，然常微偏东，不全南也。」","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）材料二中「以磁石磨针锋，则能指南」描述的是什么物理过程？钢针为什么能指示南北？（4 分）","【设问】（2）「然常微偏东，不全南也」说的是什么现象？它说明了什么？（4 分）","【设问】（3）司南静止时勺柄指向南方，据此判断勺柄是磁体的哪一极？请说明理由。（3 分）"]}],"questions":[{"id":"phy-magnet-1-q1","type":"choice","stem":"关于磁现象，下列说法正确的是","answer":"B","explain":"B 正确：磁极是磁体上磁性最强的部分，磁体静止时指北的一端是北极（N 极）。A 错：磁体不仅能吸引铁，还能吸引钴、镍等物质。C 错：磁体的磁极总是成对出现的，断开后的每一段仍然是一个完整的小磁体，各有两个磁极。D 错：磁感线是为了描述磁场而假想的曲线，真实存在的是磁场。","options":["磁体只能吸引铁，不能吸引钴和镍","磁体上磁性最强的部分叫磁极，把磁体悬挂起来，静止时指北的那端是它的 N 极","把条形磁体从中间断开，就得到一个只有 N 极的磁体和一个只有 S 极的磁体","磁体周围的磁感线是真实存在的曲线"],"difficulty":1,"tags":["磁极","磁感线"]},{"id":"phy-magnet-1-q2","type":"choice","stem":"把小磁针放在磁场中的某一点，小磁针静止时 N 极所指的方向","answer":"A","explain":"A 正确：规定小磁针静止时 N 极所指的方向为该点的磁场方向。B 错：N 极与 S 极所指的方向恰好相反，S 极的指向绝不能当作磁场方向。C 错：只有 S 极所受磁场力的方向才与磁场方向相反。D 错：小磁针能指示方向，正是因为它受到了磁场的作用。","options":["就是该点的磁场方向","与小磁针 S 极所指的方向相同","与该点的磁场方向相反","与该点的磁场方向无关"],"difficulty":1,"tags":["磁场方向"]},{"id":"phy-magnet-1-q3","type":"choice","stem":"如图为一条形磁体周围的磁感线分布，磁体的 N 极在左端、S 极在右端，b 点在远离磁体的位置，c 点在靠近 N 极的位置。下列说法正确的是","answer":"D","explain":"D 正确：磁感线越密表示磁场越强，c 点靠近磁极，磁感线最密，磁场最强。A 错：磁体外部磁感线从 N 极出发回到 S 极，磁体正上方的磁场方向指向右方（由 N 侧指向 S 侧）。B 错：磁体内部也有磁场，磁感线在内部由 S 极到 N 极，整条磁感线是闭合曲线。C 错：远离磁体的 b 点磁感线较疏，磁场较弱，说反了。","options":["磁体正上方一点的磁场方向向左","磁体内部没有磁场","b 点处的磁感线比 c 点处更密，磁场更强","c 点处的磁场比 b 点处强"],"difficulty":2,"tags":["磁感线","磁场强弱"],"figure":{"id":"fig-magnet-q3-1","title":"条形磁体周围的磁感线与两点位置","caption":"b 点远离磁体，c 点靠近 N 极","view":"wide","alt":"条形磁体左端为 N 极、右端为 S 极，周围画出从 N 极出发弯向 S 极的磁感线；c 点紧靠 N 极，磁感线很密；b 点在磁体正上方较远的位置，磁感线很疏","prims":[{"t":"curve","points":[[33,34],[18,18],[50,8],[82,18],[67,34]],"tone":"accent","arrow":true},{"t":"curve","points":[[33,34],[30,22],[50,16],[70,22],[67,34]],"tone":"accent","arrow":true},{"t":"curve","points":[[33,38],[18,52],[50,60],[82,52],[67,38]],"tone":"accent","arrow":true},{"t":"curve","points":[[33,38],[30,48],[50,54],[70,48],[67,38]],"tone":"accent","arrow":true},{"t":"magnet","x":50,"y":36,"w":34,"h":9,"label":"条形磁体"},{"t":"circle","cx":27,"cy":36,"r":4.4,"dashed":true,"label":"c","labelDx":0,"labelDy":-7},{"t":"circle","cx":50,"cy":20,"r":4.4,"dashed":true,"label":"b","labelDx":0,"labelDy":-7},{"t":"text","x":50,"y":3,"text":"磁感线越密，磁场越强","size":3.4,"tone":"muted"}]}},{"id":"phy-magnet-1-q4","type":"choice","stem":"关于地磁场，下列说法正确的是","answer":"C","explain":"C 正确：地磁两极与地理两极不重合，这个偏角叫磁偏角，我国宋代学者沈括最早记述了它。A 错：地磁的 S 极在地理北极附近，地磁的 N 极在地理南极附近。B 错：指南针能指南北是因为地球周围存在磁场（地磁场），与「带电体」无关；磁性不是电荷的性质。D 错：地磁场存在于地球周围的空间里，并非只在地表附近。","options":["地磁的北极在地理北极附近","指南针能指南北，是因为地球是一个巨大的带电体","地磁的两极与地理的两极不重合，小磁针所指方向与地理南北方向之间有一个很小的偏角，叫磁偏角","只有在地球表面附近才存在地磁场"],"difficulty":2,"tags":["地磁场","磁偏角"]},{"id":"phy-magnet-1-q5","type":"choice","stem":"把一根钢棒的一端靠近小磁针的 N 极，发现它们互相排斥。由此可以判断","answer":"B","explain":"B 正确：只有同名磁极才会互相排斥，钢棒与小磁针的 N 极相斥，说明钢棒靠近小磁针的那一端也是 N 极，钢棒一定有磁性。A、D 错：没有磁性的铁磁性物质只会被吸引，不会排斥，出现排斥就一定说明它有磁性。C 错：如果是 S 极，两者应当互相吸引，而不是排斥。","options":["钢棒一定没有磁性","钢棒一定有磁性，且它靠近小磁针 N 极的那一端是 N 极","钢棒一定有磁性，且它靠近小磁针 N 极的那一端是 S 极","钢棒可能有磁性，也可能没有磁性，无法判断"],"difficulty":2,"tags":["磁极间作用","磁性判断"]},{"id":"phy-magnet-1-q6","type":"fill","stem":"我国宋代学者____最早记述了地磁的两极与地理的两极不重合，这一现象叫做磁偏角。","answer":"沈括","explain":"北宋学者沈括在《梦溪笔谈》中记载了「方家以磁石磨针锋，则能指南，然常微偏东，不全南也」，最早记述了磁偏角现象。","difficulty":1,"tags":["磁偏角"]},{"id":"phy-magnet-1-q7","type":"short","stem":"如图，一条形磁体水平放置，N 极在左端、S 极在右端，磁体正上方放着一枚小磁针（图中只画出它的外框）。请完成：① 在小磁针上标出它静止时 N 极的指向；② 画出磁体外部的一条磁感线，并用箭头标出它的方向。","answer":"① 小磁针静止时 N 极指向右方。因为磁体外部磁感线从 N 极出发回到 S 极，磁体正上方这一点的磁场方向指向右方（由 N 侧指向 S 侧），小磁针 N 极的指向就是该点的磁场方向。② 磁感线从磁体左端 N 极出发，向上绕到右端 S 极，箭头指向 S 极一侧（见答案图）。","explain":"作图题要先判断方向再落笔。① 磁场方向的规定是小磁针静止时 N 极的指向，所以必须先由磁感线的走向确定该点的磁场方向；② 磁体外部磁感线由 N 极出发回到 S 极，磁体正上方这一点位于 N 极一侧与 S 极一侧之间，磁场方向由 N 侧指向 S 侧，也就是向右；③ 画磁感线时箭头必须指向 S 极一侧，曲线要画成弯曲的、不能相交。常见错误有两个：把小磁针 N 极画成指向左方（把 S 极的指向误当成磁场方向），以及磁感线上的箭头画反。","difficulty":2,"tags":["磁感线作图","磁场方向"],"rubric":["小磁针 N 极标为指向右方","磁感线从 N 极一侧出发、在磁体外部弯向 S 极一侧","磁感线上的箭头方向与「从 N 到 S」一致","磁感线画成曲线而不是直线，且没有相交"],"steps":["第一步：判断该点的磁场方向。磁体外部磁感线由 N 极出发回到 S 极，磁体正上方一点的磁场方向指向右方。","第二步：画小磁针。小磁针静止时 N 极的指向与该点磁场方向一致，所以在小磁针上画一个指向右方的箭头，标上 N。","第三步：画磁感线。从 N 极（左端）出发画一条向上的曲线，绕过磁体上方弯向 S 极（右端）。","第四步：标方向。在曲线的中段或末端画箭头，箭头必须指向 S 极一侧，表示磁场方向由 N 极指向 S 极。"],"figure":{"id":"fig-magnet-q7-1","title":"待完成的图：标小磁针指向、画一条磁感线","caption":"磁体的 N 极在左端，小磁针放在磁体正上方","view":"wide","alt":"条形磁体水平放置，左端标 N、右端标 S；磁体正上方有一个虚线圆圈表示小磁针的外框，里面还没有画出指针；磁体外部还没有画出磁感线","prims":[{"t":"magnet","x":50,"y":36,"w":30,"h":9,"label":"条形磁体"},{"t":"circle","cx":50,"cy":18,"r":4.4,"dashed":true,"label":"小磁针（待画）","labelDy":-7},{"t":"text","x":50,"y":57,"text":"在虚线圆内画出小磁针的指向，并在磁体外部补画一条磁感线","size":3.2,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q7-2","title":"答案图：小磁针 N 极指向右方，磁感线由 N 极到 S 极","caption":"小磁针 N 极的指向与该点磁感线的方向一致","view":"wide","alt":"条形磁体左端为 N 极、右端为 S 极，磁体正上方的小磁针 N 极指向右方；一条磁感线从 N 极出发向上弯过磁体顶部，箭头指向右端 S 极","prims":[{"t":"magnet","x":50,"y":36,"w":30,"h":9,"label":"条形磁体"},{"t":"compass","x":50,"y":18,"deg":0,"label":"小磁针"},{"t":"curve","points":[[35,34],[22,18],[50,8],[78,18],[65,34]],"tone":"accent","arrow":true},{"t":"text","x":50,"y":57,"text":"磁感线由 N 极出发，回到 S 极","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-1-q8","type":"short","stem":"某小组用铁屑探究条形磁体周围的磁场分布：把条形磁体放在水平桌面上，盖上玻璃板，在玻璃板上均匀撒一层铁屑，然后轻敲玻璃板，观察到铁屑排列成一条条曲线。请回答：① 轻敲玻璃板的目的是什么？② 铁屑为什么能显示出磁场的分布？③ 如果把磁体换成两个 N 极相对的磁体，铁屑的排列会有什么变化？","answer":"① 轻敲玻璃板是为了减小铁屑与玻璃板之间的摩擦，让铁屑能够在磁场的作用下自由地转动、移动到各自的位置，从而排列出磁场的分布。② 铁屑是铁磁性物质，放入磁场后被磁化，磁化后的每一粒铁屑都相当于一个小磁针；小磁针会沿着该处磁场的方向排列，所以大量铁屑就排成一条条曲线，把磁场的方向和强弱显示出来。③ 两个 N 极相对时，两个磁极之间的磁场互相排斥，铁屑在中间区域排列得比单个磁体时更稀疏，中间的曲线明显向两侧外凸（互相推开）。","explain":"三个设问分别对应探究实验里固定的三步：操作目的、现象原理、条件改变后的结论。① 轻敲是为了减小铁屑与玻璃板之间的摩擦，让铁屑能自由转动到磁场方向——没有这一步，铁屑会被摩擦「卡」住，看不到规律排列；② 铁屑能显示磁场，关键中间环节是「铁屑被磁化」，磁化后相当于一个个小磁针，只说「铁屑排成曲线所以有磁场」就漏掉了原理；③ 改变条件再判断时，抓住「同名磁极互相排斥」，可知两极之间磁感线变疏并向两侧外凸，铁屑在中间区域变稀。","difficulty":3,"tags":["实验探究","磁场分布"],"rubric":["① 答出减小摩擦（或让铁屑能自由转动到磁场方向）","② 答出铁屑被磁化","② 答出磁化后的铁屑相当于小磁针，沿磁场方向排列","③ 答出中间区域铁屑变疏、曲线向外凸（同名磁极互相排斥）"],"steps":["① 摩擦太大铁屑会被「卡」在原处，轻敲使铁屑能在磁场力作用下重新排列。","② 先说铁屑被磁化，再说磁化后相当于小磁针，最后说小磁针沿磁场方向排列。","③ 由「同名磁极互相排斥」推断两极之间磁感线变疏、曲线外凸，铁屑在中间区域变稀。"]},{"id":"phy-magnet-1-q9","type":"short","stem":"把一根条形磁体从中间断开成两段，每一段有几个磁极？请说明理由。","answer":"每一段都有两个磁极。磁体的磁极总是成对出现的：把磁体断成两段，每一段都会重新形成一个完整的小磁体，各自有 N 极和 S 极；无论把磁体分割得多小，都得不到单独存在的 N 极或 S 极。","explain":"这类问题要从磁极的本质入手：磁极不能单独存在，任何一个磁体都有 N、S 两个磁极。把磁体断开后，每一段都会重新形成完整的小磁体，各有两个磁极，所以每一段都有两个磁极。常见错误是认为「一断就得到了单独的 N 极和单独的 S 极」，这等于把磁极看成了可以分离的「磁荷」；用指南针、铁屑做实验也从来没有找到过单独存在的磁极。","difficulty":2,"tags":["磁极","磁极成对"],"rubric":["答出每段仍有两个磁极","答出磁极总是成对出现、不能单独存在","能用「断成两段后每段都成为新的小磁体」说明理由"]},{"id":"phy-magnet-1-m1-q1","type":"short","stem":"（1）材料二中「以磁石磨针锋，则能指南」描述的是什么物理过程？钢针为什么能指示南北？（4 分）","answer":"描述的是磁化过程：钢针在磁石上沿同一方向摩擦后获得磁性，成为一个小磁体。地球周围存在地磁场，钢针（小磁针）放在地磁场中会受到磁场力的作用，静止时它的 N 极指向地理北方，所以能指示南北。","explain":"","tags":["磁化","地磁场"],"rubric":["答出「磁化」或「钢针获得磁性、成为小磁体」","答出地球周围存在地磁场","答出小磁针在磁场中受力（或受力转动）后静止时 N 极指向地理北方","语言完整，把「磁化」与「受地磁场作用」两个环节都说到"]},{"id":"phy-magnet-1-m1-q2","type":"short","stem":"（2）「然常微偏东，不全南也」说的是什么现象？它说明了什么？（4 分）","answer":"说的是磁偏角现象：小磁针所指的方向与地理南北方向并不重合，而是有一个很小的偏角。它说明地磁场的两极与地理的两极并不重合——地磁的 S 极在地理北极附近，地磁的 N 极在地理南极附近，沈括最早记述了这一现象。","explain":"","tags":["磁偏角","地磁场"],"rubric":["答出「磁偏角」","答出地磁两极与地理两极不重合","答出地磁 S 极在地理北极附近（或地磁 N 极在地理南极附近）","答出沈括最早记述这一现象（或这一记载比欧洲早）"]},{"id":"phy-magnet-1-m1-q3","type":"short","stem":"（3）司南静止时勺柄指向南方，据此判断勺柄是磁体的哪一极？请说明理由。（3 分）","answer":"勺柄是磁体的 S 极。因为地磁的 N 极在地理南极附近，勺柄指向南方时受到地磁 N 极的吸引；由「异名磁极互相吸引」可知，与地磁 N 极相吸的勺柄一定是 S 极。","explain":"","tags":["地磁场","磁极判断"],"rubric":["答出地磁的 N 极在地理南极附近","答出「异名磁极互相吸引」","结论正确：勺柄是 S 极（南极）"]}]},{"id":"phy-magnet-2","title":"电生磁·通电螺线管","subtitle":"人教版九年级 · 第 20 章 电与磁 · 9a","grade":"9a","tags":["人教版九年级 · 第 20 章 电与磁"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 20 章 电与磁 · 9a"},{"type":"note","title":"问题切入","text":"一根不通电的导线毫无动静，通电以后为什么能让旁边的小磁针偏转？通电的螺线管，怎样才能一眼看出它的 N 极在哪一端？"},{"type":"note","title":"一句话抓住关键","text":"奥斯特实验说明通电导线周围存在磁场，这就是电流的磁效应；通电螺线管外部的磁场与条形磁体的磁场相似，它的 N 极用安培定则（右手螺旋定则）判断：右手握住螺线管，让弯曲的四指指向螺线管中电流的方向，大拇指所指的那一端就是 N 极。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"1820 年奥斯特发现：通电导线旁边的小磁针会偏转——电可以产生磁，这一下打开了电磁学的大门。","walk":["通电导线周围存在磁场，电流方向决定磁场方向。","通电螺线管外部的磁场与条形磁体相似，一端相当于 N 极，一端相当于 S 极。","安培定则：右手握住螺线管，四指指向电流方向，拇指所指的一端就是 N 极。"],"try":"把导线绕在铁钉上接电池，靠近回形针看能否吸起（通电时间要短，防止短路）。","use":["判断 N 极：先用安培定则看电流方向。","增强磁性：增大电流、增加匝数、插入铁芯。"]},{"type":"h","text":"先看现象：奥斯特实验"},{"type":"p","text":"把一枚小磁针放在水平桌面上，等它静止（指向南北）；再把一根直导线沿南北方向平行地放在小磁针的正上方。接通电源，小磁针立刻偏转；断开电源，小磁针又回到原来的南北方向；只把电源的正负极对调，让导线中的电流方向反过来，小磁针的偏转方向也跟着反过来。这个实验最早由丹麦物理学家奥斯特做成，它说明通电导线周围存在磁场，而且磁场的方向与电流的方向有关——这种现象叫电流的磁效应。"},{"type":"figure","figure":{"id":"fig-magnet-oersted-1","title":"奥斯特实验（俯视图）","caption":"导线沿南北方向放在小磁针上方，通电后小磁针的 N 极向西（图中左方）偏转","view":"wide","alt":"俯视图：一根竖直的导线画在纸面上，箭头表示导线中的电流由南向北流动；导线正下方是一枚小磁针，虚线表示它原来指向南北的方向，通电后它的 N 极转向左方（西方）","prims":[{"t":"line","x1":50,"y1":10,"x2":50,"y2":34,"width":0.7},{"t":"arrow","x1":50,"y1":30,"x2":50,"y2":14,"tone":"accent","label":"I","labelDx":6},{"t":"text","x":58,"y":11,"text":"北","size":3.6,"tone":"muted"},{"t":"text","x":58,"y":33,"text":"南","size":3.6,"tone":"muted"},{"t":"line","x1":50,"y1":34,"x2":50,"y2":50,"dashed":true,"tone":"muted"},{"t":"compass","x":50,"y":42,"deg":180},{"t":"text","x":68,"y":42,"text":"小磁针","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"通电后小磁针的 N 极向西（左）偏转","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"导线在小磁针正上方，电流方向由南向北","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"记住这是「电生磁」：通电导线周围存在磁场，不是磁生电。"},{"type":"h","text":"把磁场画出来：直线电流周围的同心圆"},{"type":"p","text":"把一根直导线垂直穿过一块硬纸板，在纸板上撒铁屑或摆几个小磁针，可以看到磁感线是以导线为圆心的一圈圈同心圆：离导线越近越密，磁场越强。方向仍由安培定则判断——用右手握住导线，大拇指指向电流的方向，弯曲的四指所指的方向就是磁感线的环绕方向。因此，电流流入纸面（用 ⊗表示）时，纸面上的磁感线是顺时针的；电流流出纸面（用 ⊙表示）时，磁感线是逆时针的。"},{"type":"figure","figure":{"id":"fig-magnet-straightwire-1","title":"直线电流周围的磁场","caption":"磁感线是以导线为圆心的一圈圈同心圆，方向由安培定则判断","view":"wide","alt":"左边一条导线垂直穿过纸面、电流流入纸面（⊗），围绕它的同心圆箭头为顺时针方向；右边一条导线电流流出纸面（⊙），围绕它的同心圆箭头为逆时针方向","prims":[{"t":"circle","cx":26,"cy":28,"r":18,"tone":"muted","dashed":true},{"t":"circle","cx":26,"cy":28,"r":11,"tone":"muted","dashed":true},{"t":"curve","points":[[41,28],[36.6,38.6],[26,43],[15.4,38.6],[11,28],[15.4,17.4],[26,13],[36.6,17.4],[40.8,25.5]],"tone":"accent","arrow":true},{"t":"circle","cx":26,"cy":28,"r":6},{"t":"line","x1":21.8,"y1":23.8,"x2":30.2,"y2":32.2},{"t":"line","x1":21.8,"y1":32.2,"x2":30.2,"y2":23.8},{"t":"text","x":26,"y":54,"text":"电流流入纸面 ⊗：磁感线顺时针","size":3.4,"tone":"muted"},{"t":"circle","cx":74,"cy":28,"r":18,"tone":"muted","dashed":true},{"t":"circle","cx":74,"cy":28,"r":11,"tone":"muted","dashed":true},{"t":"curve","points":[[89,28],[84.6,17.4],[74,13],[63.4,17.4],[59,28],[63.4,38.6],[74,43],[84.6,38.6],[88.8,30.5]],"tone":"accent","arrow":true},{"t":"circle","cx":74,"cy":28,"r":6},{"t":"junction","x":74,"y":28},{"t":"text","x":74,"y":54,"text":"电流流出纸面 ⊙：磁感线逆时针","size":3.4,"tone":"muted"}]}},{"type":"h","text":"建立联系：通电螺线管的磁场与条形磁体相似"},{"type":"p","text":"把导线绕成螺线管，通电后它周围也有磁场。在螺线管周围撒铁屑或摆几个小磁针，可以看到：磁感线从螺线管的一端出来，绕过外部回到另一端进去。磁感线出来的一端是 N 极，进去的一端是 S 极；螺线管内部的磁感线由 S 极到 N 极。因此通电螺线管外部的磁场与条形磁体的磁场十分相似，它相当于一个条形磁体，两端也分 N、S 极。"},{"type":"figure","figure":{"id":"fig-magnet-solenoid-1","title":"通电螺线管外部的磁场","caption":"磁感线从左端（N 极）出来，绕到右端（S 极）进去","view":"wide","alt":"一个水平放置的通电螺线管，左端标 N、右端标 S；螺线管上下各画出两条从 N 极一端出发、弯向 S 极一端的磁感线，箭头指向 S 极；N 极外侧的小磁针 N 极指向左方，螺线管正上方的小磁针 N 极指向右方","prims":[{"t":"text","x":50,"y":4,"text":"通电螺线管外部的磁场与条形磁体的相似","size":3.6,"tone":"muted"},{"t":"curve","points":[[35,32],[22,20],[50,12],[78,20],[65,32]],"tone":"accent","arrow":true},{"t":"curve","points":[[35,32],[32,25],[50,20],[68,25],[65,32]],"tone":"accent","arrow":true},{"t":"curve","points":[[35,40],[22,52],[50,58],[78,52],[65,40]],"tone":"accent","arrow":true},{"t":"curve","points":[[35,40],[32,47],[50,52],[68,47],[65,40]],"tone":"accent","arrow":true},{"t":"coil","x":50,"y":36,"turns":5,"w":30},{"t":"compass","x":16,"y":36,"deg":180},{"t":"text","x":16,"y":27,"text":"小磁针","size":3.2,"tone":"muted"},{"t":"compass","x":50,"y":25,"deg":0},{"t":"text","x":63,"y":25,"text":"小磁针","size":3.2,"tone":"muted"}]}},{"type":"h","text":"抓住方法：安培定则（右手螺旋定则）"},{"type":"p","text":"通电螺线管的极性用安培定则判断：用右手握住螺线管，让弯曲的四指指向螺线管中电流的方向，那么大拇指所指的那一端就是螺线管的 N 极。判断时分两步：先看清电流在螺线管正面（靠近自己的一侧）是向上还是向下，再用右手比一比。这条定则反过来也成立：已知 N 极，同样可以用它判断出电流的方向。"},{"type":"figure","figure":{"id":"fig-magnet-righthand-1","title":"用安培定则判断通电螺线管的 N 极","caption":"四指弯向螺线管正面导线中的电流方向（图中向上），大拇指指向左端，所以 N 极在左端","view":"wide","alt":"一个水平放置的通电螺线管，左端标 N、右端标 S；螺线管正面（下方）画有两个向上的电流箭头，表示螺线管正面上导线中的电流由下向上流动","prims":[{"t":"line","x1":14,"y1":34,"x2":35,"y2":34},{"t":"line","x1":65,"y1":34,"x2":86,"y2":34},{"t":"coil","x":50,"y":34,"turns":5,"w":30},{"t":"arrow","x1":42,"y1":45,"x2":42,"y2":36,"tone":"accent","label":"I","labelDx":5},{"t":"arrow","x1":58,"y1":45,"x2":58,"y2":36,"tone":"accent"},{"t":"text","x":50,"y":10,"text":"右手握螺线管：四指弯向电流方向，大拇指所指为 N 极","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"箭头表示螺线管正面（靠近观察者一侧）导线中的电流方向","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"电流方向向上，所以 N 极在左端","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"必须用右手；四指方向对应电流方向，大拇指方向对应 N 极，两者不能互换。"},{"type":"h","text":"换一个情境：电流方向反过来，南北极互换"},{"type":"p","text":"如果把电源的正负极对调，螺线管中的电流方向就反过来了。这时用手一比就会发现：大拇指指向了另一端，也就是说 N 极和 S 极互相交换了位置。可见通电螺线管的极性由电流方向和绕线方式共同决定，改变其中任何一个，极性都会改变；而改变电流的大小、线圈的匝数，改变的是磁性的强弱，不会改变它的极性。"},{"type":"figure","figure":{"id":"fig-magnet-reverse-1","title":"电流方向反过来，南北极互换","caption":"绕线不变、只把电流方向反过来，N 极从一端跑到另一端","view":"wide","alt":"左图螺线管正面导线中的电流方向向上，左端是 N 极、右端是 S 极；右图螺线管正面导线中的电流方向向下，左端是 S 极、右端是 N 极","prims":[{"t":"text","x":50,"y":8,"text":"把电流方向反过来，N、S 极互换","size":3.8,"tone":"muted"},{"t":"circle","cx":18,"cy":22,"r":5},{"t":"circle","cx":22.5,"cy":22,"r":5},{"t":"circle","cx":27,"cy":22,"r":5},{"t":"circle","cx":31.5,"cy":22,"r":5},{"t":"circle","cx":36,"cy":22,"r":5},{"t":"text","x":10,"y":22,"text":"N","size":4.4},{"t":"text","x":44,"y":22,"text":"S","size":4.4},{"t":"arrow","x1":21,"y1":33,"x2":21,"y2":25,"tone":"accent"},{"t":"arrow","x1":33,"y1":33,"x2":33,"y2":25,"tone":"accent"},{"t":"text","x":27,"y":42,"text":"正面电流向上，N 极在左端","size":3.2,"tone":"muted"},{"t":"circle","cx":62,"cy":22,"r":5},{"t":"circle","cx":66.5,"cy":22,"r":5},{"t":"circle","cx":71,"cy":22,"r":5},{"t":"circle","cx":75.5,"cy":22,"r":5},{"t":"circle","cx":80,"cy":22,"r":5},{"t":"text","x":54,"y":22,"text":"S","size":4.4},{"t":"text","x":88,"y":22,"text":"N","size":4.4},{"t":"arrow","x1":65,"y1":25,"x2":65,"y2":33,"tone":"accent"},{"t":"arrow","x1":77,"y1":25,"x2":77,"y2":33,"tone":"accent"},{"t":"text","x":71,"y":42,"text":"正面电流向下，N 极在右端","size":3.2,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["安培定则（右手螺旋定则）","右手握螺线管，四指弯向螺线管中电流的方向，大拇指所指的那一端就是螺线管的 N 极","用来判断方向，没有单位 · 有两种用法。① 判断通电螺线管的极性：右手握螺线管，让弯曲的四指指向电流方向，大拇指所指为 N 极；已知 N 极也可以反过来判断电流方向。② 判断直线电流的磁场方向：右手握导线，大拇指指向电流方向，弯曲的四指所指就是磁感线的环绕方向。判断螺线管时一定要先看清电流在螺线管正面（靠近自己的那一侧）朝上还是朝下。"],["电流的磁效应","通电导线周围存在磁场，磁场的方向与电流的方向有关","定性结论，没有单位 · 这是奥斯特实验的结论，用来解释「通电导线能使小磁针偏转」「通电螺线管有磁性」。注意它说的是「电生磁」；电磁感应说的是「磁生电」（闭合电路的一部分导体做切割磁感线运动时产生感应电流），两者条件不同、方向相反，不能混为一谈。"]]},{"type":"h","text":"应用 · 由小磁针的偏转判断螺线管的磁极"},{"type":"note","title":"情境","text":"如图，把一个通电螺线管水平放置，在它左端外侧放一枚小磁针。闭合开关后，小磁针静止时 N 极指向左方（背离螺线管）。"},{"type":"note","title":"模型与思路","text":"小磁针静止时 N 极的指向就是该点的磁场方向；磁感线在螺线管外部由 N 极出发、回到 S 极，所以磁场「出来」的那一端是 N 极。"},{"type":"list","title":"解答步骤","items":["小磁针 N 极指向左方，说明该点的磁场方向向左，也就是指向螺线管外侧。","磁体（包括通电螺线管）外部的磁感线由 N 极出发回到 S 极，磁场从哪一端向外「出来」，哪一端就是 N 极。","此处磁场由螺线管向左发出，所以螺线管的左端是 N 极，右端是 S 极。","再用小磁针的受力复核：左端是 N 极，与小磁针的 N 极互相排斥，小磁针的 N 极被推开，正好指向左方，与现象一致。"]},{"type":"figure","figure":{"id":"fig-magnet-app-2","title":"小磁针 N 极背离的一端是 N 极","caption":"小磁针 N 极指向左方，说明螺线管左端向外发出磁场，左端是 N 极","view":"wide","alt":"水平放置的通电螺线管，左端标 N、右端标 S；左端外侧的小磁针静止时 N 极指向左方，背离螺线管","prims":[{"t":"curve","points":[[35,32],[20,22],[50,12],[80,22],[65,32]],"tone":"accent","arrow":true},{"t":"coil","x":50,"y":36,"turns":5,"w":30},{"t":"compass","x":18,"y":36,"deg":180},{"t":"text","x":18,"y":26,"text":"小磁针","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"磁场由左端向外发出，所以左端是 N 极","size":3.4,"tone":"muted"}]}},{"type":"note","title":"结论","text":"螺线管左端是 N 极、右端是 S 极；小磁针的指向与「同名磁极互相排斥」的结论互相印证。"},{"type":"h","text":"应用 · 设计实验：探究螺线管外部磁场方向与电流方向的关系"},{"type":"note","title":"情境","text":"手边有通电螺线管、电源、开关、滑动变阻器、小磁针和导线，想探究通电螺线管外部磁场的方向是否与电流方向有关。"},{"type":"note","title":"模型与思路","text":"用控制变量法：只改变电流的方向，其他条件（螺线管、小磁针的位置）都不变，比较小磁针 N 极的指向。"},{"type":"list","title":"解答步骤","items":["按电路图连接器材，把小磁针放在螺线管左端外侧的 A 点。","闭合开关，等小磁针静止后记录它的 N 极指向。","断开开关，把电源的正负极对调，重新闭合开关，把小磁针放回 A 点，再记录 N 极的指向。","比较两次记录：如果两次 N 极的指向相反，说明磁场方向随电流方向的改变而改变。"]},{"type":"figure","figure":{"id":"fig-magnet-app-3","title":"探究磁场方向与电流方向关系的装置","caption":"小磁针固定在 A 点不动，只改变电流方向，比较两次 N 极的指向","view":"wide","alt":"螺线管与电源、开关串联成回路，小磁针放在螺线管左端外侧的 A 点；改变电源正负极的接法即可改变电流方向","prims":[{"t":"poly","points":[[35,30],[33,30],[33,50]],"tone":"main"},{"t":"poly","points":[[65,30],[72,30],[72,50]],"tone":"main"},{"t":"line","x1":33,"y1":50,"x2":72,"y2":50},{"t":"circle","cx":40,"cy":30,"r":5},{"t":"circle","cx":44.5,"cy":30,"r":5},{"t":"circle","cx":49,"cy":30,"r":5},{"t":"circle","cx":53.5,"cy":30,"r":5},{"t":"circle","cx":58,"cy":30,"r":5},{"t":"circle","cx":62.5,"cy":30,"r":5},{"t":"battery","x":44,"y":50,"label":"电源"},{"t":"switch","x":62,"y":50,"closed":true,"label":"S"},{"t":"circle","cx":20,"cy":30,"r":4.5,"dashed":true,"label":"A 点"},{"t":"text","x":50,"y":12,"text":"把小磁针放在 A 点，只改变电流方向，比较两次 N 极的指向","size":3.2,"tone":"muted"}]}},{"type":"note","title":"结论","text":"两次小磁针 N 极的指向相反，说明通电螺线管外部磁场的方向与电流的方向有关；电流方向改变时，螺线管的南北极互换。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["把奥斯特实验的结论说成「发现了电磁感应现象」。","奥斯特实验说明通电导线周围存在磁场，这是电流的磁效应。","奥斯特实验是「电生磁」：先有电流，才有磁场。电磁感应是「磁生电」：导体在磁场中做切割磁感线运动，电路中才产生电流。两者的条件与因果关系正好相反。"],["认为通电螺线管的极性由电流的大小决定，电流越大 N 极越「强」。","极性由电流的方向和绕线方式共同决定，与电流大小无关；电流大小只影响磁性的强弱。","安培定则里用到的只有电流的方向，根本没有涉及电流的大小。改变电流大小只改变磁性强弱，不会让南北极互换。"],["用安培定则时把四指的指向与大拇指的指向弄反，或者顺手用左手去握。","右手握螺线管：弯曲的四指指向电流方向，大拇指所指为 N 极。","四指表示电流的环绕方向，大拇指表示 N 极的方向，两者一一对应；换成左手或把两者互换，得到的极性正好相反。"]]},{"type":"table","title":"通电螺线管与条形磁体（外部磁场相似，但磁性能否人为控制完全不同）","head":["比较项","通电螺线管","条形磁体（永磁体）"],"rows":[["外部磁场","与条形磁体相似：磁感线从 N 极出来，绕到 S 极进去","磁感线从 N 极出来，绕到 S 极进去"],["磁性有无","通电才有磁性，断电后磁性立即消失","磁性长期保持，不需要通电"],["极性","由电流方向和绕线方式决定，可以改变","出厂就固定，不能改变"],["磁性强弱","由电流大小、线圈匝数等决定，可以调节","由材料本身决定，不能调节"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["通电螺线管极性与电流方向的相互判断","给出螺线管、电源、开关和电流方向（或小磁针的指向），要求标出 N、S 极或判断电源的正负极。解题顺序固定：先由电流方向确定螺线管正面电流的上下方向，再用安培定则判断极性，最后由磁感线方向判断小磁针的指向。三个方向必须自洽，画错一个整图都错。"],["实验探究：磁场方向与电流方向的关系","以「改变电流方向，观察小磁针 N 极指向是否改变」为情境，考查控制变量（小磁针放在同一位置）、观察记录（记录 N 极的指向）、结论表述（通电螺线管外部磁场的方向与电流方向有关）。设问常追问「为什么要放在同一位置」，答「控制该点磁场不变，才能确定变化是由电流方向引起的」。"],["电与磁的综合题","把螺线管、滑动变阻器、开关、小磁针放在一个电路里：移动滑片改变电流大小，磁性变强变弱但极性不变；改变接线（对调电源）极性互换。答题要分开回答「强弱」与「极性」这两类不同的问题，不能混为一谈。"]]},{"type":"quote","text":"【探究】小明把通电螺线管水平放置，用一枚小磁针探究它外部磁场的方向，记录如下。\n步骤一：把小磁针放在螺线管左端外侧的 A 点，闭合开关，小磁针静止时 N 极指向左方（背离螺线管）。\n步骤二：断开开关，把小磁针移到螺线管正上方的 B 点（螺线管中点上方），再闭合开关，小磁针静止时 N 极指向右方。\n步骤三：断开开关，把电源的正负极对调后闭合开关，把小磁针重新放回 A 点，发现小磁针静止时 N 极指向右方（指向螺线管）。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）由步骤一和步骤二，判断这个螺线管的哪一端是 N 极，并说明判断依据。（4 分）","【设问】（2）比较步骤一和步骤三，可以得出什么结论？（3 分）","【设问】（3）若把小磁针放在螺线管内部的轴线上，它的 N 极会指向哪一端？请说明理由。（3 分）"]}],"questions":[{"id":"phy-magnet-2-q1","type":"choice","stem":"奥斯特实验表明","answer":"A","explain":"A 正确：把小磁针放在通电导线附近，小磁针发生偏转，说明通电导线周围存在磁场，这就是电流的磁效应。B 错：那是磁场对通电导线的作用，是电动机的原理。C 错：那是电磁感应现象，是发电机的原理。D 错：磁体周围确实存在磁场，但奥斯特实验研究的是电流的磁场，不是磁体的磁场。","options":["通电导线周围存在磁场","磁场对通电导线有力的作用","闭合电路的一部分导体做切割磁感线运动时会产生感应电流","磁体周围存在磁场"],"difficulty":1,"tags":["奥斯特实验","电流的磁效应"]},{"id":"phy-magnet-2-q2","type":"choice","stem":"在奥斯特实验中，导线沿南北方向放在静止的小磁针上方。接通电源后小磁针发生偏转；若只把电源的正负极对调，则","answer":"B","explain":"B 正确：通电导线周围的磁场方向与电流方向有关，电流方向反过来，磁场方向也反过来，所以小磁针的偏转方向相反。A 错：只要通电就有磁场，小磁针一定偏转。C 错：正负极对调改变的是电流方向而不是电流大小，方向必然改变，不是「方向不变」。D 错：奥斯特实验正是说明了磁场方向与电流方向有关。","options":["小磁针不再偏转","小磁针偏转的方向相反","小磁针偏转的方向不变，只是偏角变大","小磁针的偏转方向与电流方向无关"],"difficulty":2,"tags":["奥斯特实验","电流方向"]},{"id":"phy-magnet-2-q3","type":"choice","stem":"如图，一个通电螺线管的左端为 N 极、右端为 S 极，a 点在螺线管左端外侧，b 点在螺线管正上方。关于 a、b 两点的磁场方向，下列说法正确的是","answer":"A","explain":"A 正确：螺线管外部的磁感线由 N 极出发、回到 S 极。a 点在 N 极外侧，磁场方向背离 N 极，即向左；b 点在螺线管正上方，磁场方向由 N 极一侧指向 S 极一侧，即向右。B、C、D 都把某一处的方向判断反了：远离 N 极外侧的磁场一定背离 N 极，而两极之间的外部磁场一定由 N 极一侧指向 S 极一侧。","options":["a 点向左，b 点向右","a、b 两点都向左","a 点向右，b 点向左","a、b 两点都向右"],"difficulty":2,"tags":["通电螺线管","磁场方向"],"figure":{"id":"fig-magnet-q3-2","title":"a、b 两点与通电螺线管的位置关系","caption":"a 点在左端外侧，b 点在螺线管正上方","view":"wide","alt":"水平放置的通电螺线管，左端标 N、右端标 S；a 点用虚线圆圈标在螺线管左端外侧，b 点用虚线圆圈标在螺线管正上方","prims":[{"t":"curve","points":[[35,32],[22,18],[50,10],[78,18],[65,32]],"tone":"accent","arrow":true},{"t":"coil","x":50,"y":36,"turns":5,"w":30},{"t":"circle","cx":18,"cy":36,"r":4.4,"dashed":true,"label":"a","labelDy":-7},{"t":"circle","cx":50,"cy":24,"r":4.4,"dashed":true,"label":"b","labelDy":-7},{"t":"text","x":50,"y":56,"text":"磁感线在螺线管外部由 N 极出发，回到 S 极","size":3.4,"tone":"muted"}]}},{"id":"phy-magnet-2-q4","type":"choice","stem":"用安培定则判断通电螺线管的极性时，正确的做法是","answer":"C","explain":"C 正确：安培定则又叫右手螺旋定则，右手握螺线管，弯曲的四指指向螺线管中电流的方向，大拇指所指的那一端就是 N 极。A 错：必须用右手，用左手得到的结果正好相反。B 错：四指对应电流方向，大拇指对应 N 极，两者不能互换。D 错：四指对应的是电流方向，而磁感线方向正是要用这条定则去求的，不能用它当已知条件。","options":["用左手握住螺线管，让四指指向电流方向，大拇指所指的一端为 N 极","用右手握住螺线管，让大拇指指向电流方向，四指所指的一端为 N 极","用右手握住螺线管，让弯曲的四指指向电流方向，大拇指所指的一端为 N 极","用右手握住螺线管，让弯曲的四指指向磁感线方向，大拇指所指的一端为 N 极"],"difficulty":1,"tags":["安培定则"]},{"id":"phy-magnet-2-q5","type":"choice","stem":"关于通电螺线管，下列说法正确的是","answer":"D","explain":"D 正确：安培定则里只用到了电流的方向，所以极性由电流方向和绕线方式共同决定；电流方向反过来，N 极就跑到另一端。A 错：电流大小只影响磁性强弱，不影响极性。B 错：只能说通电螺线管外部的磁场与条形磁体的磁场相似，不能说处处完全相同。C 错：通电螺线管的磁性由电流产生，断电后磁性立即消失，这正是它与永磁体的重要区别。","options":["它的极性由电流的大小决定","它外部的磁场与条形磁体的磁场处处完全相同","断电以后它仍能长期保持磁性","它的极性由电流方向和线圈的绕法共同决定，改变电流方向，它的南北极互换"],"difficulty":2,"tags":["通电螺线管","极性"]},{"id":"phy-magnet-2-q6","type":"fill","stem":"用右手握住通电螺线管，让弯曲的四指指向螺线管中____的方向，大拇指所指的那一端就是螺线管的 N 极。","answer":"电流|电流方向","explain":"这就是安培定则（右手螺旋定则）。四指方向对应螺线管中电流的方向，大拇指方向对应 N 极的方向；判断时要先看清电流在螺线管正面是向上还是向下。","difficulty":1,"tags":["安培定则"]},{"id":"phy-magnet-2-q7","type":"fill","stem":"丹麦物理学家____首先通过实验发现通电导线周围存在磁场，这一现象叫做电流的磁效应。","answer":"奥斯特","explain":"奥斯特把小磁针放在通电直导线下方，发现小磁针发生了偏转，从而发现了电流的磁效应，第一次把电现象和磁现象联系起来。","difficulty":1,"tags":["奥斯特实验"]},{"id":"phy-magnet-2-q8","type":"short","stem":"如图，螺线管与电源、开关连成电路。闭合开关后，从螺线管的正面（靠近观察者的一侧）看，导线中的电流方向向上（图中已用箭头标出）。请完成：① 在图中标出这个螺线管的 N 极和 S 极；② 在图中标出小磁针静止时 N 极的指向。","answer":"① 螺线管的左端是 N 极，右端是 S 极。② 小磁针的 N 极指向左方（背离螺线管）。理由：用右手握螺线管，让弯曲的四指指向正面向上的电流方向，大拇指指向左端，所以左端是 N 极；磁感线在螺线管外部由 N 极出发回到 S 极，小磁针所在位置在左端外侧，该点磁场方向向左（背离 N 极），小磁针 N 极的指向与该点磁场方向一致，因此指向左方。","explain":"本题要连做三步判断，一步错就全错。第一步确定电流方向：题干已给出螺线管正面（靠近观察者一侧）的电流方向向上。第二步用安培定则：右手握螺线管，四指弯向上，大拇指指向左端，所以左端是 N 极、右端是 S 极。第三步由磁场方向判断小磁针的指向：螺线管外部磁感线由 N 极出发回到 S 极，小磁针位于左端外侧，该点磁场向左，小磁针 N 极便指向左方。常见错误有两个：用左手去握（极性正好相反），以及把小磁针 N 极画成指向右方（误以为磁场总是从 S 极出发）。","difficulty":3,"tags":["作图题","安培定则"],"rubric":["用安培定则判断出左端为 N 极、右端为 S 极（字母位置写对）","小磁针的 N 极标为指向左方（背离螺线管）","说明理由时写出「四指弯向电流方向、大拇指所指为 N 极」","说明小磁针 N 极的指向与该点磁场方向一致"],"steps":["第一步：找到螺线管正面导线中的电流方向（题中已给出：向上）。","第二步：用安培定则判断极性——右手握螺线管，四指弯向电流方向，大拇指指向左端，故左端为 N 极、右端为 S 极。","第三步：判断小磁针所在处的磁场方向——磁感线在外部由 N 极出发回到 S 极，小磁针在左端外侧，该点磁场向左。","第四步：小磁针 N 极的指向与该点磁场方向一致，故 N 极指向左方，在图中画出向左的箭头并标 N。"],"figure":{"id":"fig-magnet-q8-1","title":"待完成的图：标出螺线管的磁极和小磁针的指向","caption":"螺线管正面导线中的电流方向已用箭头标出，小磁针（虚线圆）需要补画指针","view":"wide","alt":"螺线管与电源、开关组成回路，螺线管上画有两个向上的箭头表示正面导线中的电流方向；螺线管左端外侧有一个虚线圆表示小磁针，里面还没有画出指针，螺线管两端也没有标出 N、S 极","prims":[{"t":"poly","points":[[35,30],[33,30],[33,50]],"tone":"main"},{"t":"poly","points":[[65,30],[72,30],[72,50]],"tone":"main"},{"t":"line","x1":33,"y1":50,"x2":72,"y2":50},{"t":"circle","cx":40,"cy":30,"r":5},{"t":"circle","cx":44.5,"cy":30,"r":5},{"t":"circle","cx":49,"cy":30,"r":5},{"t":"circle","cx":53.5,"cy":30,"r":5},{"t":"circle","cx":58,"cy":30,"r":5},{"t":"circle","cx":62.5,"cy":30,"r":5},{"t":"arrow","x1":44,"y1":34,"x2":44,"y2":26,"tone":"accent","label":"I","labelDx":5},{"t":"arrow","x1":58,"y1":34,"x2":58,"y2":26,"tone":"accent"},{"t":"battery","x":44,"y":50,"label":"电源"},{"t":"switch","x":62,"y":50,"closed":true,"label":"S"},{"t":"circle","cx":20,"cy":30,"r":4.5,"dashed":true,"label":"小磁针"},{"t":"text","x":50,"y":10,"text":"从螺线管正面看，电流方向向上（箭头）","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"在图中标出 N、S 极与小磁针 N 极的指向","size":3.4,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q8-2","title":"答案图：左端为 N 极，小磁针 N 极指向左方","caption":"正面电流向上，用安培定则判断出 N 极在左端；小磁针在左端外侧，N 极指向左方","view":"wide","alt":"螺线管左端标 N、右端标 S；外部一条磁感线由左端 N 极出发绕到右端 S 极，箭头指向 S 极；左端外侧的小磁针 N 极指向左方","prims":[{"t":"curve","points":[[35,32],[20,16],[50,8],[80,16],[65,32]],"tone":"accent","arrow":true},{"t":"coil","x":50,"y":36,"turns":5,"w":30},{"t":"compass","x":18,"y":36,"deg":180},{"t":"text","x":50,"y":50,"text":"外部磁感线由 N 极出来，小磁针 N 极背离 N 极","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-2-q9","type":"short","stem":"小明想探究通电螺线管外部磁场的方向是否与电流方向有关。他把小磁针放在螺线管左端外侧的 A 点。请回答：① 写出他的操作步骤（包括需要记录什么）；② 为什么每次都要把小磁针放在同一个位置 A 点？③ 若把电源正负极对调后，小磁针的指向与原来完全相同，可能是什么原因？","answer":"① 用控制变量法，只改变电流方向，其他条件都不变。步骤：闭合开关，等小磁针静止后记下它 N 极的指向；断开开关，把电源的正负极对调，再闭合开关，把小磁针放回 A 点，记下此时 N 极的指向；比较两次记录。② 放在同一位置是为了控制小磁针所在处的磁场方向（位置）不变，这样如果 N 极的指向变了，才能确定是由电流方向改变引起的。③ 可能是因为电路中实际上没有电流：开关没有闭合、接线处接触不良、电源没电等；也可能是小磁针没有放回 A 点。没有电流时小磁针只受地磁场作用，两次都会指向南北，看起来「完全相同」。","explain":"探究题要写清「改什么、控什么、记什么」。① 本实验的自变量是电流方向，做法是对调电源正负极；因变量是小磁针 N 极的指向；控制量是螺线管、小磁针的位置。② 如果把小磁针换了位置，指向的变化可能来自位置不同（各点磁场方向本来就不同），实验就无法说明问题，这就是要放回 A 点的原因。③ 电流方向改变后磁场方向必然改变，指向却完全不变，最可能的解释是没有电流（小磁针只受地磁场作用），所以要从「电路是否真的通了」去找原因，而不是怀疑结论。","difficulty":3,"tags":["实验探究","控制变量法"],"rubric":["① 答出只改变电流方向、其他条件不变（控制变量）","① 答出记录两次小磁针 N 极的指向并加以比较","② 答出控制小磁针所在位置（该点磁场）不变","③ 答出电路中没有电流（开关未闭合、接触不良、电源没电等）"],"steps":["① 写明器材连接与两次操作：闭合开关记录 N 极指向 → 对调电源正负极后重新闭合开关、把小磁针放回 A 点再记录 → 比较。","② 说明控制变量的理由：位置不变，该点磁场方向才不变，指向的变化才能归因于电流方向。","③ 从「有没有电流」入手排查：开关、接线、电源，或小磁针未放回 A 点。"]},{"id":"phy-magnet-2-q10","type":"short","stem":"一个通电螺线管的右端是 N 极。小明说：只要把它两端接在电源上的导线对调，右端就会变成 S 极。他的说法对吗？请说明理由。","answer":"他的说法对。把两端接在电源上的导线对调，就是改变了螺线管中电流的方向。由安培定则可知，电流方向反过来，四指弯向的方向反过来，大拇指所指的方向也反过来，所以原来的 N 极（右端）变成 S 极，原来的 S 极（左端）变成 N 极，而绕线方式并没有改变。","explain":"本题考的是「极性由什么决定」。极性由电流方向和绕线方式共同决定，对调电源接线只改变了电流方向，绕线没变，所以极性必然反转。常见的错误答法是「磁性变强或变弱」，那是电流大小改变的结果，与本题无关。","difficulty":2,"tags":["安培定则","极性变化"],"rubric":["判断正确（说法正确）","指出对调导线就是改变螺线管中电流的方向","用安培定则说明电流方向改变时 N 极的位置随之改变","结论明确：右端由 N 极变成 S 极"]},{"id":"phy-magnet-2-m1-q1","type":"short","stem":"（1）由步骤一和步骤二，判断这个螺线管的哪一端是 N 极，并说明判断依据。（4 分）","answer":"左端是 N 极。小磁针静止时 N 极的指向就是该点的磁场方向：A 点在螺线管左端外侧，小磁针 N 极指向左方，说明该点的磁场由螺线管向外发出，而磁感线在螺线管外部由 N 极出发、回到 S 极，所以磁场「出来」的左端是 N 极、右端是 S 极。步骤二中 B 点在螺线管正上方，磁场方向由 N 极一侧指向 S 极一侧，即指向右方，与「左端是 N 极」的结论一致。","explain":"","tags":["通电螺线管","磁场方向"],"rubric":["答出「小磁针静止时 N 极的指向就是该点的磁场方向」","由 A 点现象判断出左端是 N 极","说明磁体外部磁感线由 N 极出发、回到 S 极","用 B 点现象验证（磁场由左端一侧指向右端一侧）"]},{"id":"phy-magnet-2-m1-q2","type":"short","stem":"（2）比较步骤一和步骤三，可以得出什么结论？（3 分）","answer":"把电源的正负极对调，改变了螺线管中电流的方向；小磁针在同一个位置 A 点的 N 极指向变得相反，说明该点的磁场方向相反。结论是：通电螺线管外部磁场的方向与电流的方向有关，电流方向改变时，螺线管的南北极互换。","explain":"","tags":["实验探究","安培定则"],"rubric":["答出正负极对调就是改变电流方向","答出同一位置小磁针 N 极指向相反，说明磁场方向相反","答出结论：通电螺线管外部磁场的方向与电流方向有关（或改变电流方向南北极互换）"]},{"id":"phy-magnet-2-m1-q3","type":"short","stem":"（3）若把小磁针放在螺线管内部的轴线上，它的 N 极会指向哪一端？请说明理由。（3 分）","answer":"N 极指向左端。螺线管内部的磁感线由 S 极到 N 极，即由右端指向左端；小磁针 N 极的指向与该点的磁场方向一致，所以放在内部轴线上时 N 极指向左端（N 极）。","explain":"","tags":["通电螺线管","内部磁场"],"rubric":["答出螺线管内部的磁感线由 S 极到 N 极","推出内部轴线上的磁场方向由右端指向左端","结论正确：小磁针 N 极指向左端"]}]},{"id":"phy-magnet-3","title":"电磁铁与电磁继电器","subtitle":"人教版九年级 · 第 20 章 电与磁 · 9a","grade":"9a","tags":["人教版九年级 · 第 20 章 电与磁"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 20 章 电与磁 · 9a"},{"type":"note","title":"问题切入","text":"电磁起重机为什么能一次吸起成吨的废钢铁，断电以后又能一下子把它们全部放下？电磁铁的磁性强弱到底跟什么有关？"},{"type":"note","title":"一句话抓住关键","text":"电磁铁就是插入铁芯的通电螺线管：通电时才有磁性、断电后磁性立即消失，极性由电流方向决定，磁性强弱由电流大小和线圈匝数决定（电流越大、匝数越多磁性越强，插入软铁芯也会明显增强）。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"电磁铁像一个「能开关的磁铁」：通电有磁、断电没磁，所以能做自动控制。","walk":["电磁铁就是插入铁芯的通电螺线管，磁性强弱由电流大小和线圈匝数决定。","极性由电流方向决定，改变电流方向，N、S 极就互换。","电磁继电器用低电压、弱电流控制高电压、强电流，既方便又安全。"],"try":"找一个旧继电器或电铃，观察它的线圈、衔铁和触点是怎样配合工作的。","use":["磁性变化题：滑片移动→电流变化→磁性变化。","继电器应用：温控、光控、防盗报警。"]},{"type":"h","text":"先看现象：能「开关」的磁铁"},{"type":"p","text":"把一根软铁棒插入螺线管中，就做成了一个电磁铁。闭合开关，它能吸起大头针、铁钉；断开开关，吸起来的铁钉立刻掉下去。与永磁体相比，电磁铁最大的特点是磁性可以随时「开」和「关」。要比较电磁铁的磁性强弱，可以看它吸起的大头针（或铁屑）有多少：吸得越多，说明磁性越强。"},{"type":"figure","figure":{"id":"fig-magnet-electromagnet-1","title":"电磁铁的基本装置","caption":"通电时铁芯下方吸起大头针，断电后大头针全部落下","view":"wide","alt":"一个插有铁芯的螺线管接在电源与开关组成的回路中，螺线管下方吸着一排大头针","prims":[{"t":"rect","x":32,"y":16.5,"w":36,"h":7,"tone":"muted","fill":true},{"t":"coil","x":50,"y":20,"turns":5,"w":28},{"t":"line","x1":36,"y1":20,"x2":22,"y2":20},{"t":"line","x1":64,"y1":20,"x2":78,"y2":20},{"t":"line","x1":22,"y1":20,"x2":22,"y2":44},{"t":"line","x1":78,"y1":20,"x2":78,"y2":44},{"t":"line","x1":22,"y1":44,"x2":78,"y2":44},{"t":"battery","x":38,"y":44,"label":"电源"},{"t":"switch","x":62,"y":44,"closed":true,"label":"S"},{"t":"line","x1":38,"y1":23.5,"x2":38,"y2":30,"width":0.8},{"t":"line","x1":44,"y1":23.5,"x2":44,"y2":30,"width":0.8},{"t":"line","x1":50,"y1":23.5,"x2":50,"y2":30,"width":0.8},{"t":"line","x1":56,"y1":23.5,"x2":56,"y2":30,"width":0.8},{"t":"line","x1":62,"y1":23.5,"x2":62,"y2":30,"width":0.8},{"t":"text","x":50,"y":11,"text":"铁芯","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":36,"text":"吸起的大头针越多，磁性越强","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":55,"text":"通电有磁性，断电磁性立即消失","size":3.4,"tone":"muted"}]}},{"type":"h","text":"抓住变量：磁性强弱跟电流、匝数有关"},{"type":"p","text":"研究电磁铁的磁性强弱跟哪些因素有关，要用控制变量法。保持线圈匝数不变，用滑动变阻器改变电路中的电流：电流越大，吸起的大头针越多，磁性越强；保持电流不变，换用匝数不同的电磁铁：匝数越多，吸起的大头针越多，磁性越强。所以增大电流或增加匝数都能增强电磁铁的磁性。"},{"type":"figure","figure":{"id":"fig-magnet-turns-1","title":"电流相同时，匝数越多磁性越强","caption":"通过两个电磁铁的电流相同（串联在同一电路中），匝数多的吸起的大头针多","view":"wide","alt":"左边一个匝数较少的螺线管下端吸着两枚大头针，右边一个匝数较多的螺线管下端吸着五枚大头针，两个螺线管串联在同一电路中，电流相同","prims":[{"t":"line","x1":10,"y1":24,"x2":6,"y2":24},{"t":"line","x1":6,"y1":24,"x2":6,"y2":44},{"t":"line","x1":42,"y1":24,"x2":58,"y2":24},{"t":"line","x1":94,"y1":24,"x2":94,"y2":44},{"t":"line","x1":6,"y1":44,"x2":94,"y2":44},{"t":"battery","x":44,"y":44,"label":"电源","cells":2},{"t":"switch","x":72,"y":44,"closed":true,"label":"S"},{"t":"coil","x":26,"y":24,"turns":3,"w":20},{"t":"coil","x":76,"y":24,"turns":8,"w":22},{"t":"line","x1":22,"y1":28,"x2":22,"y2":34,"width":0.8},{"t":"line","x1":30,"y1":28,"x2":30,"y2":34,"width":0.8},{"t":"line","x1":68,"y1":28,"x2":68,"y2":34,"width":0.8},{"t":"line","x1":72,"y1":28,"x2":72,"y2":34,"width":0.8},{"t":"line","x1":76,"y1":28,"x2":76,"y2":34,"width":0.8},{"t":"line","x1":80,"y1":28,"x2":80,"y2":34,"width":0.8},{"t":"line","x1":84,"y1":28,"x2":84,"y2":34,"width":0.8},{"t":"text","x":26,"y":14,"text":"匝数少","size":3.4,"tone":"muted"},{"t":"text","x":76,"y":14,"text":"匝数多","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"电流相同：匝数越多，吸起的大头针越多","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"（两个电磁铁串联，通过它们的电流相同）","size":3.2,"tone":"muted"}]}},{"type":"h","text":"再想一层：插入铁芯为什么能增强磁性"},{"type":"p","text":"把一个螺线管分成「插铁芯」和「不插铁芯」两种情况，通以相同的电流，会发现插铁芯后吸引的大头针明显增多。原因有两个：一是软铁芯被螺线管的磁场磁化，自己变成了一个磁体，它的磁场与螺线管的磁场互相叠加，总磁场增强了；二是铁芯能把磁感线「聚」在它附近，使磁场更集中。铁芯必须用软磁性材料（如软铁），这样断电后铁芯的磁性才能立即消失，电磁铁才真正「关得掉」。"},{"type":"figure","figure":{"id":"fig-magnet-core-1","title":"插入铁芯后磁性明显增强","caption":"相同的电流、相同的匝数，插铁芯的吸引的大头针多得多","view":"wide","alt":"左边螺线管内没有铁芯，下端只吸住一枚大头针；右边螺线管内插有铁芯，下端吸住五枚大头针","prims":[{"t":"coil","x":26,"y":24,"turns":5,"w":22},{"t":"rect","x":60,"y":20.5,"w":28,"h":7,"tone":"muted","fill":true},{"t":"coil","x":74,"y":24,"turns":5,"w":22},{"t":"line","x1":26,"y1":28,"x2":26,"y2":33,"width":0.8},{"t":"line","x1":68,"y1":28,"x2":68,"y2":33,"width":0.8},{"t":"line","x1":72,"y1":28,"x2":72,"y2":33,"width":0.8},{"t":"line","x1":76,"y1":28,"x2":76,"y2":33,"width":0.8},{"t":"line","x1":80,"y1":28,"x2":80,"y2":33,"width":0.8},{"t":"line","x1":84,"y1":28,"x2":84,"y2":33,"width":0.8},{"t":"text","x":26,"y":12,"text":"无铁芯","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":12,"text":"有铁芯","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"铁芯被磁化后，它的磁场与螺线管的磁场叠加","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"铁芯要用软铁：断电后磁性立即消失","size":3.4,"tone":"muted"}]}},{"type":"h","text":"学会应用：电磁继电器的工作过程"},{"type":"p","text":"电磁继电器是用电磁铁控制的开关，由电磁铁、衔铁、弹簧、触点等组成。它把电路分成两部分：低压电源、开关和电磁铁的线圈组成控制电路；高压电源、用电器（电动机、电灯等）和继电器的触点组成工作电路。闭合控制电路的开关，电磁铁有了磁性，把衔铁吸下来，衔铁带动触点接通工作电路，电动机开始工作；断开控制电路的开关，电磁铁失去磁性，弹簧把衔铁拉回原处，触点断开，电动机停止工作。这样用低电压、弱电流就能控制高电压、强电流，既安全，又便于远距离控制和自动控制。"},{"type":"figure","figure":{"id":"fig-magnet-relay-1","title":"电磁继电器控制电动机","caption":"闭合控制电路的开关，电磁铁吸引衔铁，触点接通，工作电路中的电动机工作","view":"wide","alt":"左下方是控制电路：低压电源、开关与电磁铁的线圈串联；电磁铁上方是带弹簧的衔铁，衔铁的右端与触点相对；右侧是工作电路：高压电源、电动机与触点串联。衔铁被吸下时触点接通，电动机工作","prims":[{"t":"text","x":50,"y":5,"text":"电磁继电器：用低电压的控制电路控制高电压的工作电路","size":3.2,"tone":"muted"},{"t":"line","x1":8,"y1":16,"x2":40,"y2":16},{"t":"line","x1":8,"y1":16,"x2":8,"y2":44},{"t":"line","x1":40,"y1":16,"x2":40,"y2":44},{"t":"battery","x":18,"y":16,"label":"低压电源"},{"t":"switch","x":33,"y":16,"closed":true,"label":"S"},{"t":"coil","x":24,"y":44,"turns":4,"w":18},{"t":"line","x1":8,"y1":44,"x2":15,"y2":44},{"t":"line","x1":33,"y1":44,"x2":40,"y2":44},{"t":"spring","x1":12,"y1":21,"x2":12,"y2":30,"coils":4},{"t":"lever","x1":12,"y1":32,"x2":36,"y2":32,"pivot":0},{"t":"text","x":24,"y":27,"text":"衔铁","size":3.4,"tone":"muted"},{"t":"junction","x":36,"y":32},{"t":"junction","x":36,"y":37},{"t":"line","x1":36,"y1":32,"x2":56,"y2":32},{"t":"line","x1":56,"y1":32,"x2":56,"y2":16},{"t":"line","x1":56,"y1":16,"x2":64,"y2":16},{"t":"rect","x":64,"y":11,"w":16,"h":10,"tone":"main","label":"电动机"},{"t":"line","x1":80,"y1":16,"x2":92,"y2":16},{"t":"line","x1":92,"y1":16,"x2":92,"y2":52},{"t":"line","x1":92,"y1":52,"x2":48,"y2":52},{"t":"battery","x":68,"y":52,"label":"高压电源","cells":2},{"t":"line","x1":48,"y1":52,"x2":48,"y2":37},{"t":"line","x1":36,"y1":37,"x2":48,"y2":37},{"t":"text","x":24,"y":58,"text":"控制电路（低压、弱电流）","size":3.2,"tone":"muted"},{"t":"text","x":70,"y":60,"text":"工作电路（高压、强电流）","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"衔铁被吸引使触点接通，是「电磁铁把电信号变成了机械动作」，继电器本质是一个开关。"},{"type":"h","text":"换一个情境：生活中还有哪些地方用到电磁铁"},{"type":"p","text":"电磁铁的磁性可以人为控制，所以应用非常广泛：电磁起重机通电吸起废钢铁、断电放下；电铃靠电磁铁断续吸引小锤敲击铃碗而发声；电话听筒、扬声器用电磁铁带动膜片振动发声；电磁门锁、磁悬浮列车、录音机的磁头里也都有电磁铁。选用电磁铁时，需要吸力大就增大电流或增加匝数；想省电则可以在增加匝数上想办法。"},{"type":"figure","figure":{"id":"fig-magnet-crane-1","title":"电磁起重机","caption":"圆盘形电磁铁通电吸起废钢铁，断电后废钢铁全部落下","view":"wide","alt":"一根钢丝绳吊着一个圆盘形电磁铁，电磁铁下方吸着一堆形状不规则废钢铁","prims":[{"t":"line","x1":50,"y1":4,"x2":50,"y2":14,"width":0.7},{"t":"circle","cx":50,"cy":17,"r":3,"tone":"main"},{"t":"rect","x":34,"y":21,"w":32,"h":8,"tone":"danger","fill":true,"label":"电磁铁"},{"t":"rect","x":37,"y":31,"w":9,"h":6,"tone":"main"},{"t":"rect","x":48,"y":30,"w":10,"h":8,"tone":"main"},{"t":"rect","x":60,"y":32,"w":8,"h":6,"tone":"main"},{"t":"poly","points":[[40,40],[52,40],[58,48],[36,48]],"closed":true,"tone":"main"},{"t":"rect","x":58,"y":41,"w":9,"h":5,"tone":"main"},{"t":"text","x":50,"y":56,"text":"通电吸起废钢铁，断电立刻放下","size":3.4,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["电磁铁磁性强弱的影响因素","电流越大、线圈匝数越多，电磁铁的磁性越强；插入软铁芯后磁性明显增强","定性结论；比较磁性强弱时用「吸起大头针（铁屑）的多少」来反映 · 研究时必须用控制变量法：研究电流的影响就保持匝数、铁芯不变；研究匝数的影响就保持电流、铁芯不变。注意这些因素只影响磁性的强弱，不影响极性——极性由电流方向和绕线方式决定。"],["欧姆定律（用于电磁铁的控制电路）","I = (U)/(R)","I：安培（A）；U：伏特（V）；R：欧姆（Ω） · 用于纯电阻的控制电路：把线圈电阻、滑动变阻器接入的电阻、导线电阻（一般忽略）都算进 R。移动滑动变阻器的滑片就是在改变 R，从而改变电流、改变电磁铁的磁性强弱。变形用法：U = IR 求电源电压，R = U/I 求电路总电阻。"]]},{"type":"h","text":"应用 · 用电磁继电器控制电动机"},{"type":"note","title":"情境","text":"一台电动机由高电压电路供电，直接用手去扳开关很不安全。要求用一个低电压的控制电路，通过电磁继电器来控制这台电动机。"},{"type":"note","title":"模型与思路","text":"电磁继电器是用电磁铁控制的开关：控制电路的电流决定电磁铁有没有磁性，电磁铁再决定衔铁和触点的位置，触点又控制工作电路的通断。"},{"type":"list","title":"解答步骤","items":["把低压电源、开关和电磁铁的线圈串联起来，组成控制电路。","把高压电源、电动机和继电器的触点串联起来，组成工作电路。","闭合控制电路的开关，电磁铁有磁性吸引衔铁，衔铁带动触点接通，工作电路接通，电动机工作。","断开控制电路的开关，电磁铁失去磁性，弹簧把衔铁拉回，触点断开，电动机停止工作。"]},{"type":"figure","figure":{"id":"fig-magnet-app-4","title":"继电器把控制电路与工作电路分开","caption":"控制电路里的电流只是「下命令」，真正做功的电流在工作电路里","view":"wide","alt":"左侧控制电路由低压电源、开关、电磁铁线圈组成，右侧工作电路由高压电源、电动机和继电器的触点组成，两者通过衔铁与触点联系起来","prims":[{"t":"rect","x":4,"y":10,"w":44,"h":44,"tone":"accent","dashed":true,"label":"控制电路"},{"t":"rect","x":54,"y":10,"w":42,"h":44,"tone":"danger","dashed":true,"label":"工作电路"},{"t":"coil","x":26,"y":42,"turns":4,"w":18},{"t":"line","x1":10,"y1":24,"x2":42,"y2":24},{"t":"battery","x":18,"y":24,"label":"低压电源"},{"t":"switch","x":35,"y":24,"closed":true,"label":"S"},{"t":"line","x1":10,"y1":24,"x2":10,"y2":42},{"t":"line","x1":42,"y1":24,"x2":42,"y2":42},{"t":"line","x1":10,"y1":42,"x2":17,"y2":42},{"t":"line","x1":35,"y1":42,"x2":42,"y2":42},{"t":"arrow","x1":26,"y1":36,"x2":26,"y2":30,"tone":"ok"},{"t":"text","x":26,"y":20,"text":"吸引衔铁","size":3.2,"tone":"muted"},{"t":"line","x1":58,"y1":46,"x2":92,"y2":46},{"t":"battery","x":66,"y":46,"label":"高压电源"},{"t":"line","x1":58,"y1":46,"x2":58,"y2":20},{"t":"line","x1":58,"y1":20,"x2":66,"y2":20},{"t":"rect","x":66,"y":15,"w":16,"h":10,"tone":"main","label":"电动机"},{"t":"line","x1":82,"y1":20,"x2":92,"y2":20},{"t":"line","x1":92,"y1":20,"x2":92,"y2":46},{"t":"junction","x":58,"y":33},{"t":"text","x":74,"y":33,"text":"触点","size":3.2,"tone":"muted"}]}},{"type":"note","title":"结论","text":"用低电压、弱电流的控制电路就能控制高电压、强电流的工作电路，操作安全，还可以实现远距离控制和自动控制。"},{"type":"h","text":"应用 · 计算控制电路中的电流"},{"type":"note","title":"情境","text":"某电磁铁线圈的电阻是 20 Ω，把它接在 6 V 的电源上，控制电路中还有一个开关，其余电阻忽略不计。"},{"type":"note","title":"模型与思路","text":"控制电路可以看成纯电阻电路，用欧姆定律 I = U/R 求电流；线圈匝数不变时，电流的变化直接反映磁性强弱的变化。"},{"type":"list","title":"解答步骤","items":["已知电源电压 U = 6 V，线圈电阻 R = 20 Ω。","由欧姆定律 I = U/R 得 I = 6 V ÷ 20 Ω = 0.3 A。","若再串联一个 10 Ω 的滑动变阻器，电路总电阻 R总 = 20 Ω + 10 Ω = 30 Ω，电流 I′ = 6 V ÷ 30 Ω = 0.2 A。","电流由 0.3 A 减小到 0.2 A，线圈匝数没有改变，所以电磁铁的磁性减弱。"]},{"type":"note","title":"结论","text":"线圈中的电流是 0.3 A；串联 10 Ω 的滑动变阻器后电流变为 0.2 A，电磁铁的磁性减弱。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为电磁铁的磁性强弱与电流方向有关。","磁性强弱只与电流大小、线圈匝数、有无铁芯有关；电流方向只决定电磁铁的极性。","把电源正负极对调，可以吸起的大头针数目几乎不变，只是南北极互换了位置。「强弱」与「极性」是两个不同的问题，答题时要分开说。"],["电磁铁的铁芯用钢来做更好，因为钢的磁性更强。","铁芯应该用软磁性材料（如软铁）：它容易被磁化，断电后磁性又很快消失。","钢属于硬磁性材料，被磁化后磁性会长期保留，断电后电磁铁仍有磁性，就失去了「磁性可以随时控制」这一最大优点。"],["把电磁继电器当成一种电源或者一种电动机。","电磁继电器是用电磁铁控制的开关，它既不产生电流，也不对外输出机械能。","它由电磁铁、衔铁、弹簧和触点组成，作用是「用小电流、低电压去控制大电流、高电压」，本质是一个可以自动动作的开关。"]]},{"type":"table","title":"电磁铁与永磁体（磁性是否可以人为控制）","head":["比较项","电磁铁","永磁体"],"rows":[["磁性来源","通电螺线管的磁场，加上被磁化的软铁芯的磁场","材料本身具有磁性"],["磁性有无","通电才有磁性，断电后磁性立即消失","长期保持，无法消除"],["磁性强弱","可以由电流大小、线圈匝数调节","固定不变"],["极性","可以由电流方向改变","固定不变"],["常见应用","电磁起重机、电铃、电磁继电器、磁悬浮列车","指南针、扬声器、冰箱门密封条"]]},{"type":"table","title":"控制电路与工作电路（电磁继电器）（用低电压、弱电流去控制高电压、强电流）","head":["比较项","控制电路","工作电路"],"rows":[["组成","低压电源、开关、电磁铁的线圈","高压电源、用电器、继电器的触点"],["电流特点","电压低、电流小","电压高、电流大"],["如何被控制","由人操作开关，决定电磁铁有没有磁性","由衔铁带动触点，间接决定通断"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["探究电磁铁磁性强弱的影响因素","经典探究题。三个要点必须写全：一是转换法——用吸引大头针（或铁屑）的多少来反映磁性强弱；二是控制变量法——研究电流时保持匝数不变，研究匝数时保持电流不变；三是结论表述要带条件，如「在其他条件相同时，电流越大，电磁铁的磁性越强」。"],["电磁继电器的工作过程与作用","给出继电器控制的电路图，要求说明闭合（或断开）开关时各部分的动作顺序：电磁铁有无磁性 → 衔铁被吸引或弹回 → 触点接通或断开 → 工作电路用电器工作或停止。常追问「继电器的作用」，答「用低电压、弱电流控制高电压、强电流，安全且便于远距离、自动控制」。"],["电磁铁的作图与电流方向判断","给出电源、开关与电磁铁的绕线，要求标出 N、S 极或判断电流方向。与通电螺线管一样要用安培定则，区别在于答题时还要点明「线圈正面导线中的电流方向」，这是判断的第一步。"]]},{"type":"quote","text":"【探究】小明用两个外形相同、匝数不同的螺线管甲（匝数少）和乙（匝数多）做实验，把它们的下端分别靠近同一堆大头针，用吸引大头针的多少来比较磁性强弱。\n① 把甲、乙分别接入同一电路，保持通过它们的电流相同，发现乙吸起的大头针明显比甲多。\n② 换用甲，闭合开关后移动滑动变阻器的滑片，使通过线圈的电流变大，发现甲吸起的大头针变多了。\n③ 把一根软铁棒插入甲的螺线管中，其他条件不变，发现甲吸起的大头针更多了。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）实验中用「吸引大头针的多少」来比较电磁铁磁性的强弱，这种方法叫什么？为什么可以这样比较？（3 分）","【设问】（2）由现象①和②，分别可以得出什么结论？（4 分）","【设问】（3）现象③说明了什么？电磁铁的铁芯为什么必须用软铁而不能用钢？（3 分）"]}],"questions":[{"id":"phy-magnet-3-q1","type":"choice","stem":"关于电磁铁的磁性强弱，下列说法正确的是","answer":"C","explain":"C 正确：电磁铁的磁性强弱由电流大小、线圈匝数、有无铁芯共同决定，电流越大、匝数越多、插入铁芯都会使磁性增强。A、B 都只说了一个因素，不全面。D 错：电流方向决定的是电磁铁的极性，与磁性强弱无关——把电源正负极对调，能吸起的大头针数目几乎不变，但南北极互换。","options":["只与通过线圈的电流大小有关","只与线圈的匝数有关","与电流的大小、线圈的匝数、有无铁芯都有关","与电流的方向有关"],"difficulty":1,"tags":["磁性强弱"]},{"id":"phy-magnet-3-q2","type":"choice","stem":"把一个电磁铁接在电源上，闭合开关后把电源的正负极对调，其他条件都不变。此时电磁铁","answer":"D","explain":"D 正确：对调电源正负极只改变了线圈中电流的方向。电流方向决定极性，所以它的 N、S 极互换；而磁性强弱由电流大小、匝数、有无铁芯决定，这些都没有改变，所以强弱基本不变。A、B 错：正负极对调并没有改变电流的大小。C 错：电路仍然接通，电磁铁当然有磁性。","options":["磁性增强","磁性减弱","磁性消失","磁性强弱基本不变，但南北极互换"],"difficulty":2,"tags":["极性","磁性强弱"]},{"id":"phy-magnet-3-q3","type":"choice","stem":"如图，甲、乙两个电磁铁串联在同一电路中（通过它们的电流相同），甲线圈的匝数比乙少。闭合开关后，比较它们吸引大头针的多少，正确的是","answer":"B","explain":"B 正确：在电流相同、都没有插铁芯（条件相同）的情况下，匝数越多磁性越强，所以匝数多的乙吸起的大头针多。A 错：线圈电阻的大小只影响电流大小，不是磁性强弱的直接原因，而且串联时通过两者的电流本来就相同。C 错：电流相同只说明「电流这个因素相同」，匝数不同仍会造成磁性不同。D 错：题目已说明两个电磁铁的其他条件相同，只有匝数不同，可以比较。","options":["甲吸起的大头针多，因为甲的线圈电阻小","乙吸起的大头针多，因为电流相同时线圈匝数越多磁性越强","两个吸起的大头针一样多，因为通过它们的电流相同","无法判断，因为没有说明是否插入铁芯"],"difficulty":2,"tags":["控制变量法","磁性强弱"],"figure":{"id":"fig-magnet-q3-3","title":"匝数不同的两个电磁铁串联","caption":"甲匝数少、乙匝数多，串联时通过它们的电流相同","view":"wide","alt":"两个电磁铁甲、乙串联在同一电路中，甲线圈匝数少，乙线圈匝数多；两个电磁铁下方都还没有画出被吸起的大头针","prims":[{"t":"line","x1":10,"y1":24,"x2":4,"y2":24},{"t":"line","x1":4,"y1":24,"x2":4,"y2":44},{"t":"line","x1":42,"y1":24,"x2":58,"y2":24},{"t":"line","x1":96,"y1":24,"x2":96,"y2":44},{"t":"line","x1":4,"y1":44,"x2":96,"y2":44},{"t":"battery","x":44,"y":44,"label":"电源","cells":2},{"t":"switch","x":74,"y":44,"closed":true,"label":"S"},{"t":"coil","x":26,"y":24,"turns":3,"w":20},{"t":"coil","x":76,"y":24,"turns":8,"w":22},{"t":"text","x":26,"y":38,"text":"甲（匝数少）","size":3.4,"tone":"muted"},{"t":"text","x":78,"y":38,"text":"乙（匝数多）","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"两个电磁铁串联，通过它们的电流相同","size":3.4,"tone":"muted"}]}},{"id":"phy-magnet-3-q4","type":"choice","stem":"关于电磁继电器，下列说法正确的是","answer":"A","explain":"A 正确：电磁继电器由电磁铁、衔铁、弹簧、触点组成，用电磁铁控制触点的通断，从而用小电流控制大电流。B 错：它不产生电流，只是控制工作电路的通断，不是电源。C 错：控制电路断开后电磁铁失去磁性，弹簧把衔铁拉回，触点断开，工作电路也就断开了。D 错：正因为可以用小电流自动控制，继电器广泛应用于自动控制和远距离控制。","options":["它是用电磁铁控制的开关，可以用低电压、弱电流的控制电路去控制高电压、强电流的工作电路","它是一种电源，能向外输出电流","断开控制电路的开关后，工作电路仍然接通","它只能靠人手直接操作，不能实现自动控制"],"difficulty":2,"tags":["电磁继电器"]},{"id":"phy-magnet-3-q5","type":"choice","stem":"电磁铁的铁芯要用软铁这类软磁性材料来做，主要原因是","answer":"B","explain":"B 正确：铁芯在螺线管的磁场中被磁化，使磁性明显增强；而软铁在离开磁场后磁性很快消失，所以断电后电磁铁能真正失去磁性。A 错：铁芯并不用来导电，导电性能与铁芯的作用无关。C、D 错：密度和防锈都不是选择铁芯材料的主要原因。","options":["软铁的导电性能好，可以减小线圈的电阻","软铁容易被磁化，断电后磁性又很快消失，便于控制","软铁的密度小，可以减轻电磁铁的质量","软铁不容易生锈，使用寿命长"],"difficulty":1,"tags":["铁芯","软磁性材料"]},{"id":"phy-magnet-3-q6","type":"fill","stem":"电磁铁通电时有磁性，断开开关后它的磁性____（选填「立即消失」或「长期保持」）。","answer":"立即消失","explain":"电磁铁的磁性由通电螺线管的磁场产生，铁芯又是软磁性材料，所以断电后磁性立即消失。能够长期保持磁性的是永磁体（如用钢制成的磁体）。","difficulty":1,"tags":["电磁铁","磁性有无"]},{"id":"phy-magnet-3-q7","type":"short","stem":"如图，一个电磁铁接在电源和开关组成的电路中。闭合开关后，从螺线管的正面（靠近观察者的一侧）看，导线中的电流方向向下（图中已用箭头标出）。请完成：① 在螺线管两端标出 N、S 极；② 在图中画出它外部的一条磁感线，并标出磁感线的方向。","answer":"① 螺线管的右端是 N 极，左端是 S 极。② 磁感线从右端（N 极）出发，绕过螺线管的外部回到左端（S 极），箭头指向左端（见答案图）。理由：用右手握螺线管，让弯曲的四指指向正面向下的电流方向，大拇指指向右端，所以右端是 N 极；磁体外部磁感线由 N 极出发回到 S 极。","explain":"本题的电流方向与常见情形相反（正面电流向下），所以极性也相反：右手握螺线管，四指弯向下方，大拇指指向右端，右端是 N 极。画磁感线时有两条规矩：一是只能画在磁体外部（磁体内部的磁感线方向相反，本题不要求画），二是箭头必须由 N 极一侧指向 S 极一侧，因此箭头应指向左端。常见的错误是把极性判断成「左端 N」，或者把箭头画成由 S 指向 N。","difficulty":3,"tags":["作图题","安培定则","磁感线"],"rubric":["用安培定则判断出右端为 N 极、左端为 S 极，字母位置正确","磁感线画在螺线管外部，从 N 极一侧出发弯向 S 极一侧","磁感线上的箭头指向 S 极一侧（与电流方向对应正确）","曲线不相交，且理由中写出了安培定则的使用方法"],"steps":["第一步：看清电流方向——正面导线中的电流向下。","第二步：用安培定则——右手握螺线管，四指弯向下方，大拇指指向右端，故右端为 N 极、左端为 S 极。","第三步：画磁感线——从右端 N 极出发，绕到螺线管外部再回到左端 S 极。","第四步：标方向——在磁感线中段画出指向左端（S 极）的箭头，并与电流方向相互印证。"],"figure":{"id":"fig-magnet-q7-3","title":"待完成的图：标出磁极并画一条磁感线","caption":"螺线管正面导线中的电流方向向下，两端还没有标出 N、S 极","view":"wide","alt":"一个螺线管与电源、开关连成回路，螺线管上画有两个向下的箭头表示正面导线中的电流方向；螺线管两端没有标 N、S 极，外部也没有画磁感线","prims":[{"t":"poly","points":[[35,30],[30,30],[30,50]],"tone":"main"},{"t":"poly","points":[[65,30],[72,30],[72,50]],"tone":"main"},{"t":"line","x1":30,"y1":50,"x2":72,"y2":50},{"t":"circle","cx":40,"cy":30,"r":5},{"t":"circle","cx":44.5,"cy":30,"r":5},{"t":"circle","cx":49,"cy":30,"r":5},{"t":"circle","cx":53.5,"cy":30,"r":5},{"t":"circle","cx":58,"cy":30,"r":5},{"t":"circle","cx":62.5,"cy":30,"r":5},{"t":"arrow","x1":44,"y1":26,"x2":44,"y2":34,"tone":"accent","label":"I","labelDx":5},{"t":"arrow","x1":58,"y1":26,"x2":58,"y2":34,"tone":"accent"},{"t":"battery","x":42,"y":50,"label":"电源"},{"t":"switch","x":62,"y":50,"closed":true,"label":"S"},{"t":"text","x":50,"y":12,"text":"从螺线管正面看，导线中电流方向向下（箭头）","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"在图中标出 N、S 极，并画出一条外部磁感线标出方向","size":3.2,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q7-4","title":"答案图：右端为 N 极，磁感线由右端绕向左端","caption":"正面电流向下，用安培定则判断出 N 极在右端","view":"wide","alt":"螺线管左端标 S、右端标 N；一条磁感线从右端 N 极出发，绕过螺线管上方弯向左端 S 极，箭头指向左端","prims":[{"t":"curve","points":[[78,30],[90,16],[60,8],[30,16],[22,30]],"tone":"accent","arrow":true},{"t":"circle","cx":40,"cy":30,"r":5},{"t":"circle","cx":44.5,"cy":30,"r":5},{"t":"circle","cx":49,"cy":30,"r":5},{"t":"circle","cx":53.5,"cy":30,"r":5},{"t":"circle","cx":58,"cy":30,"r":5},{"t":"circle","cx":62.5,"cy":30,"r":5},{"t":"text","x":32,"y":30,"text":"S","size":4.4},{"t":"text","x":70,"y":30,"text":"N","size":4.4},{"t":"arrow","x1":44,"y1":26,"x2":44,"y2":34,"tone":"accent"},{"t":"arrow","x1":58,"y1":26,"x2":58,"y2":34,"tone":"accent"},{"t":"text","x":50,"y":48,"text":"四指弯向电流方向，大拇指指向右端，故右端是 N 极","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"外部磁感线由 N 极出发，回到 S 极","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-3-q8","type":"short","stem":"小明用如图装置探究「电磁铁磁性强弱与哪些因素有关」：把电磁铁的下端靠近一堆大头针，用吸起大头针的多少来判断磁性的强弱。请回答：① 为什么可以用吸起大头针的多少来判断磁性强弱？② 要探究磁性强弱与电流大小的关系，他应该怎样操作？实验中要控制哪些量不变？③ 要探究磁性强弱与线圈匝数的关系，请写出主要做法和判断依据。","answer":"① 电磁铁的磁性越强，对铁质大头针的吸引力越大，能吸起的大头针越多；所以用吸起大头针的数目可以间接反映磁性的强弱，这种方法叫转换法。② 把滑动变阻器与电磁铁串联在电路中，闭合开关后保持电磁铁不变（线圈匝数、铁芯都不变），移动滑片改变电路中的电流，每次读下电流表的示数并数出吸起的大头针数目，比较不同电流时的结果；要控制线圈匝数、有无铁芯（以及大头针本身）等因素不变。③ 取两个匝数不同、其他条件都相同的电磁铁，把它们分别接入同一电路，控制通过它们的电流相同（可以串联），比较各自吸起大头针的数目；若匝数多的吸起的多，说明在其他条件相同时，线圈匝数越多，电磁铁的磁性越强。","explain":"探究题要看三件事：怎么把看不见的量变成看得见的量（转换法）、改变什么（自变量）、保持什么不变（控制变量）。① 磁性强弱看不见，但吸引大头针的数目看得见，这是转换法的典型用法。② 要研究电流的影响，就必须让电流成为唯一的变量：用滑动变阻器改变电流，同时把匝数、铁芯固定下来。③ 要研究匝数的影响，就要反过来让匝数成为唯一变量，并保持电流相同——两个线圈串联就能保证电流相同。缺少「其他条件相同」这半句话，结论就不成立，这是最常见的失分点。","difficulty":3,"tags":["实验探究","控制变量法","转换法"],"rubric":["① 答出磁性越强对大头针的吸引力越大（或答出「转换法」）","② 答出用滑动变阻器改变电流，并保持匝数、铁芯不变","② 答出要记录电流大小与吸起大头针的数目进行比较","③ 答出用匝数不同、其他条件相同的电磁铁，保持电流相同","③ 结论表述完整：其他条件相同时，匝数越多磁性越强"],"steps":["① 说明「磁性越强 → 吸引力越大 → 吸起的大头针越多」，指出这是转换法。","② 写出操作：滑动变阻器串联、改变滑片位置、记录电流与大头针数目；点明控制线圈匝数与铁芯不变。","③ 写出做法：两个匝数不同的电磁铁串联（电流相同）、比较吸起的大头针数目；写出带条件的结论。"],"figure":{"id":"fig-magnet-q8-3","title":"探究电磁铁磁性强弱的装置","caption":"用滑动变阻器改变电流，用吸起大头针的多少比较磁性强弱","view":"wide","alt":"电磁铁与滑动变阻器、电源、开关串联成回路，电磁铁下端靠近一堆大头针，还没有画出被吸起的大头针","prims":[{"t":"rect","x":32,"y":16.5,"w":36,"h":7,"tone":"muted","fill":true},{"t":"coil","x":50,"y":20,"turns":5,"w":28},{"t":"line","x1":36,"y1":20,"x2":20,"y2":20},{"t":"line","x1":64,"y1":20,"x2":80,"y2":20},{"t":"line","x1":20,"y1":20,"x2":20,"y2":46},{"t":"line","x1":80,"y1":20,"x2":80,"y2":46},{"t":"line","x1":20,"y1":46,"x2":80,"y2":46},{"t":"battery","x":32,"y":46,"label":"电源","cells":2},{"t":"rheostat","x":60,"y":46,"label":"滑动变阻器"},{"t":"line","x1":44,"y1":23.5,"x2":44,"y2":29,"width":0.8},{"t":"line","x1":50,"y1":23.5,"x2":50,"y2":29,"width":0.8},{"t":"line","x1":56,"y1":23.5,"x2":56,"y2":29,"width":0.8},{"t":"line","x1":44,"y1":33,"x2":44,"y2":37,"width":0.8},{"t":"line","x1":50,"y1":33,"x2":50,"y2":37,"width":0.8},{"t":"line","x1":56,"y1":33,"x2":56,"y2":37,"width":0.8},{"t":"text","x":50,"y":11,"text":"铁芯","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"用吸起大头针的多少比较磁性强弱（转换法）","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-3-q9","type":"short","stem":"某电磁铁线圈的电阻是 20 Ω，把它接在 6 V 的电源上，控制电路中还串联着一个开关，其余部分的电阻忽略不计。求：① 线圈中的电流；② 若在这个控制电路中再串联一个接入电阻为 10 Ω 的滑动变阻器，线圈中的电流是多少？③ 与①相比，电磁铁的磁性怎样变化？","answer":"① I = U/R = 6 V ÷ 20 Ω = 0.3 A。② 串联后总电阻 R总 = 20 Ω + 10 Ω = 30 Ω，I′ = U/R总 = 6 V ÷ 30 Ω = 0.2 A。③ 通过线圈的电流由 0.3 A 减小到 0.2 A，而线圈的匝数、铁芯都没有改变，所以电磁铁的磁性减弱，能吸起的大头针数目减少。","explain":"这是一道电磁学与电学结合的计算题，关键是分清「哪些量变了、哪些量没变」。① 直接用电欧姆定律。② 串联电路的总电阻等于各电阻之和，所以要把 20 Ω 和 10 Ω 相加后再算电流，直接用 6 V ÷ 10 Ω 是错的。③ 磁性强弱由电流大小等因素决定，匝数没变而电流变小，磁性必然减弱——注意不能说「磁性消失」，因为电路仍然接通，只是变弱。","difficulty":2,"tags":["欧姆定律","磁性强弱"],"rubric":["① 写出公式 I = U/R 并代入数据，算出 0.3 A（带单位）","② 先求出总电阻 30 Ω，再算出 0.2 A","③ 说明电流变小、匝数不变，故磁性减弱"],"steps":["① 明确已知量：U = 6 V，R = 20 Ω；由 I = U/R 得 I = 6 V ÷ 20 Ω = 0.3 A。","② 串联电路 R总 = R₁ + R₂ = 20 Ω + 10 Ω = 30 Ω；I′ = U/R总 = 6 V ÷ 30 Ω = 0.2 A。","③ 比较 0.3 A 与 0.2 A：电流变小；线圈匝数与铁芯未变；结论是电磁铁磁性减弱。"]},{"id":"phy-magnet-3-m1-q1","type":"short","stem":"（1）实验中用「吸引大头针的多少」来比较电磁铁磁性的强弱，这种方法叫什么？为什么可以这样比较？（3 分）","answer":"这种方法叫转换法：把不容易直接观察的磁性强弱，转换成容易观察和比较的大头针数目。电磁铁的磁性越强，对铁质大头针的吸引力越大，能够吸起的大头针就越多，所以大头针的数目可以间接反映磁性的强弱。","explain":"","tags":["转换法","实验探究"],"rubric":["答出「转换法」","答出磁性越强对大头针的吸引力越大","答出用大头针数目间接比较磁性强弱"]},{"id":"phy-magnet-3-m1-q2","type":"short","stem":"（2）由现象①和②，分别可以得出什么结论？（4 分）","answer":"由现象①：在其他条件相同时，线圈的匝数越多，电磁铁的磁性越强。由现象②：在其他条件相同时，通过线圈的电流越大，电磁铁的磁性越强。","explain":"","tags":["控制变量法","磁性强弱"],"rubric":["① 答出「其他条件相同（电流相同）时，匝数越多磁性越强」","① 结论中带有「其他条件相同」这一前提","② 答出「其他条件相同（匝数相同）时，电流越大磁性越强」","② 结论表述完整，指出了自变量与因变量的关系"]},{"id":"phy-magnet-3-m1-q3","type":"short","stem":"（3）现象③说明了什么？电磁铁的铁芯为什么必须用软铁而不能用钢？（3 分）","answer":"现象③说明插入铁芯后电磁铁的磁性明显增强：软铁棒被螺线管的磁场磁化，成了一个磁体，它的磁场与螺线管的磁场方向相同、互相叠加，使总磁场增强。铁芯要用软铁，是因为软铁容易被磁化、离开磁场（断电）后磁性又很快消失；如果用钢，被磁化后磁性会长期保留，断电后电磁铁仍有磁性，就失去了磁性可以随时控制的优点。","explain":"","tags":["铁芯","软磁性材料"],"rubric":["答出铁芯被磁化（成为磁体）","答出铁芯的磁场与螺线管的磁场叠加，使磁性增强","答出软铁断电后磁性迅速消失，便于控制（用钢会保留磁性）"]}]},{"id":"phy-magnet-4","title":"磁场对通电导线的作用·电动机","subtitle":"人教版九年级 · 第 20 章 电与磁 · 9a","grade":"9a","tags":["人教版九年级 · 第 20 章 电与磁"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 20 章 电与磁 · 9a"},{"type":"note","title":"问题切入","text":"把通电的线圈放进磁场里，它为什么会自己转起来？线圈为什么不会一直转下去，还要靠换向器？电动机把什么能变成了什么能？"},{"type":"note","title":"一句话抓住关键","text":"磁场对通电导线有力的作用，力的方向与电流方向、磁场方向都有关（只改变其中一个，受力方向相反；两个同时改变，受力方向不变）；通电线圈在磁场中受力转动，换向器每半周自动改变一次线圈中的电流方向，线圈才能连续转动；电动机把电能转化为机械能，与发电机正好相反。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"电动机一通電就转，是因为磁场对通电线圈有力的作用，这个力推着线圈转起来。","walk":["通电导线在磁场中受力，力的方向与电流方向、磁场方向都有关。","线圈转过平衡位置后，靠换向器改变电流方向，才能持续转动。","电动机把电能转化为机械能。"],"try":"把小磁铁靠近通电的细漆包线，观察导线跳动（电流要大、时间要短）。","use":["改变转向：改变电流方向或磁场方向，只改其中一个。","分清电机：电动机用电生磁受力，发电机用磁生电。"]},{"type":"h","text":"先看现象：磁场对通电导线有力的作用"},{"type":"p","text":"把一段导线垂直放在磁体的两极之间（导线垂直于纸面），接通电源，导线立刻向某个方向运动；断开电源，导线就停下来。这个现象说明：磁场对通电导线有力的作用。力有多大、方向如何，取决于电流和磁场这两件事——这正是电动机能够转动的原因，也是它与电磁感应（磁生电）最根本的区别：这里必须通上电，导线才受力。"},{"type":"figure","figure":{"id":"fig-magnet-force-1","title":"磁场对通电导线的作用","caption":"导线垂直于纸面、电流流入纸面（⊗）时，导线受到的力竖直向下","view":"wide","alt":"左右分别是磁体的 N 极和 S 极，两极之间画有向右的磁场箭头；中间一条导线垂直于纸面、电流流入纸面（⊗），导线受到竖直向下的力，用向下的箭头 F 表示","prims":[{"t":"text","x":50,"y":6,"text":"磁场对通电导线有力的作用","size":3.6,"tone":"muted"},{"t":"rect","x":2,"y":22,"w":12,"h":16,"tone":"danger","fill":true},{"t":"text","x":8,"y":30,"text":"N"},{"t":"rect","x":86,"y":22,"w":12,"h":16,"tone":"accent","fill":true},{"t":"text","x":92,"y":30,"text":"S"},{"t":"arrow","x1":16,"y1":14,"x2":84,"y2":14,"tone":"muted","label":"B"},{"t":"arrow","x1":16,"y1":30,"x2":43,"y2":30,"tone":"muted"},{"t":"arrow","x1":57,"y1":30,"x2":84,"y2":30,"tone":"muted"},{"t":"arrow","x1":16,"y1":46,"x2":84,"y2":46,"tone":"muted"},{"t":"circle","cx":50,"cy":30,"r":6},{"t":"line","x1":45.8,"y1":25.8,"x2":54.2,"y2":34.2},{"t":"line","x1":45.8,"y1":34.2,"x2":54.2,"y2":25.8},{"t":"arrow","x1":50,"y1":38,"x2":50,"y2":54,"tone":"accent","label":"F","labelDx":5},{"t":"text","x":50,"y":59,"text":"⊗ 表示电流流入纸面，磁场由 N 极指向 S 极","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"与电磁感应分清楚：这里是「通电导体在磁场中受力」，前提是导体中有电流。"},{"type":"h","text":"抓住方向关系：只改一个，受力反向"},{"type":"p","text":"把电流方向反过来（导线中的电流流出纸面），其他条件不变，导线就向上运动——受力方向与原来相反。把磁体的两极对调、只改变磁场方向，导线受力的方向也相反。而如果同时把电流方向和磁场方向都反过来，导线受力的方向反而与原来相同。所以判断受力方向必须同时看电流方向和磁场方向：只改一个，受力反向；两个同时改，受力方向不变。"},{"type":"figure","figure":{"id":"fig-magnet-force-2","title":"电流方向反过来，受力方向也反过来","caption":"与上一张图相比，只把电流方向从流入纸面改为流出纸面（⊙），导线受到的力就变成竖直向上","view":"wide","alt":"左右分别是磁体的 N 极和 S 极，磁场方向水平向右；中间的导线垂直于纸面、电流流出纸面（⊙），导线受到竖直向上的力，用向上的箭头 F 表示","prims":[{"t":"text","x":50,"y":6,"text":"只改变电流方向，受力方向相反","size":3.6,"tone":"muted"},{"t":"rect","x":2,"y":22,"w":12,"h":16,"tone":"danger","fill":true},{"t":"text","x":8,"y":30,"text":"N"},{"t":"rect","x":86,"y":22,"w":12,"h":16,"tone":"accent","fill":true},{"t":"text","x":92,"y":30,"text":"S"},{"t":"arrow","x1":16,"y1":30,"x2":43,"y2":30,"tone":"muted","label":"B"},{"t":"arrow","x1":57,"y1":30,"x2":84,"y2":30,"tone":"muted"},{"t":"arrow","x1":16,"y1":46,"x2":84,"y2":46,"tone":"muted"},{"t":"circle","cx":50,"cy":30,"r":6},{"t":"junction","x":50,"y":30},{"t":"arrow","x1":50,"y1":22,"x2":50,"y2":10,"tone":"accent","label":"F","labelDx":5},{"t":"text","x":50,"y":56,"text":"⊙ 表示电流流出纸面","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":59.5,"text":"磁场方向不变，只有电流方向反过来，所以受力方向相反","size":3.2,"tone":"muted"}]}},{"type":"h","text":"建立联系：通电线圈为什么能转起来"},{"type":"p","text":"把线圈放进磁场里，线圈的两条边中电流的方向相反（一条边的电流流入纸面，另一条边的电流流出纸面），它们受到的磁场力的方向也就相反：一条边被向下推，另一条边被向上推。这两个力不在同一直线上，于是线圈就绕轴转动起来。所以通电线圈在磁场中转动，靠的是两条边受力方向相反这一对「力偶」的作用。"},{"type":"figure","figure":{"id":"fig-magnet-coilrotate-1","title":"通电线圈在磁场中受力转动","caption":"线圈左边受力向下、右边受力向上，两个力不在同一直线上，线圈绕轴逆时针转动","view":"wide","alt":"磁体的 N 极在左、S 极在右，磁场水平向右；中间是一个矩形线圈，左边的边电流流入纸面（⊗）受力向下，右边的边电流流出纸面（⊙）受力向上，线圈绕垂直于纸面的轴逆时针转动","prims":[{"t":"rect","x":2,"y":18,"w":11,"h":14,"tone":"danger","fill":true},{"t":"text","x":7.5,"y":25,"text":"N"},{"t":"rect","x":87,"y":18,"w":11,"h":14,"tone":"accent","fill":true},{"t":"text","x":92.5,"y":25,"text":"S"},{"t":"arrow","x1":14,"y1":25,"x2":30,"y2":25,"tone":"muted","label":"B"},{"t":"arrow","x1":70,"y1":25,"x2":86,"y2":25,"tone":"muted"},{"t":"rect","x":34,"y":12,"w":32,"h":26},{"t":"circle","cx":34,"cy":25,"r":4},{"t":"line","x1":31.2,"y1":22.2,"x2":36.8,"y2":27.8},{"t":"line","x1":31.2,"y1":27.8,"x2":36.8,"y2":22.2},{"t":"circle","cx":66,"cy":25,"r":4},{"t":"junction","x":66,"y":25},{"t":"arrow","x1":34,"y1":40,"x2":34,"y2":52,"tone":"accent","label":"F","labelDx":5},{"t":"arrow","x1":66,"y1":10,"x2":66,"y2":2,"tone":"accent","label":"F","labelDx":5},{"t":"text","x":50,"y":45,"text":"两条边受力方向相反，线圈绕轴转动","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"左边受力向下、右边受力向上，线圈沿逆时针方向转动","size":3.2,"tone":"muted"}]}},{"type":"h","text":"抓住关键：线圈为什么不能一直转，换向器起什么作用"},{"type":"p","text":"线圈转到与磁场方向垂直的平衡位置时，两条边受到的力方向相反而且作用在同一条直线上，线圈受到的是一对平衡力，不能再继续转动。由于惯性，线圈会冲过这个位置，但如果电流方向不变，力马上又会把它拉回来，线圈只能在平衡位置附近来回摆动。直流电动机用换向器解决这个难题：换向器由两个彼此绝缘的半圆铜环组成，通过电刷与外电路相连。线圈每转过平衡位置，换向器就自动改变线圈中电流的方向，使线圈受到的力始终朝着同一个方向推，线圈于是能连续转动。"},{"type":"figure","figure":{"id":"fig-magnet-commutator-1","title":"直流电动机的换向器","caption":"换向器每半周改变一次线圈中电流的方向，线圈才能持续转动","view":"wide","alt":"磁体的 N 极在左、S 极在右；中间矩形线圈两边的电流方向分别用 ⊗和 ⊙表示，两边受到方向相反的力；线圈下方经导线接到由两个半圆铜环组成的换向器上，两个电刷分别与铜环接触并接到电源","prims":[{"t":"text","x":50,"y":4,"text":"换向器每半周改变一次线圈中电流的方向","size":3.2,"tone":"muted"},{"t":"rect","x":2,"y":18,"w":11,"h":14,"tone":"danger","fill":true},{"t":"text","x":7.5,"y":25,"text":"N"},{"t":"rect","x":87,"y":18,"w":11,"h":14,"tone":"accent","fill":true},{"t":"text","x":92.5,"y":25,"text":"S"},{"t":"arrow","x1":14,"y1":25,"x2":30,"y2":25,"tone":"muted","label":"B"},{"t":"arrow","x1":70,"y1":25,"x2":86,"y2":25,"tone":"muted"},{"t":"rect","x":34,"y":12,"w":32,"h":26},{"t":"circle","cx":34,"cy":25,"r":4},{"t":"line","x1":31.2,"y1":22.2,"x2":36.8,"y2":27.8},{"t":"line","x1":31.2,"y1":27.8,"x2":36.8,"y2":22.2},{"t":"circle","cx":66,"cy":25,"r":4},{"t":"junction","x":66,"y":25},{"t":"line","x1":40,"y1":38,"x2":45,"y2":44},{"t":"line","x1":60,"y1":38,"x2":55,"y2":44},{"t":"rect","x":41,"y":44,"w":7,"h":5},{"t":"rect","x":52,"y":44,"w":7,"h":5},{"t":"line","x1":44.5,"y1":49,"x2":44.5,"y2":54,"width":1.2},{"t":"line","x1":55.5,"y1":49,"x2":55.5,"y2":54,"width":1.2},{"t":"line","x1":44.5,"y1":54,"x2":20,"y2":54},{"t":"line","x1":55.5,"y1":54,"x2":80,"y2":54},{"t":"line","x1":20,"y1":54,"x2":20,"y2":60},{"t":"line","x1":80,"y1":54,"x2":80,"y2":60},{"t":"line","x1":20,"y1":60,"x2":80,"y2":60},{"t":"battery","x":50,"y":60,"label":"电源"},{"t":"text","x":30,"y":41,"text":"换向器","size":3.2,"tone":"muted","anchor":"end"},{"t":"text","x":74,"y":50,"text":"电刷","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"换向器的作用是「改变线圈中电流的方向」，不是改变电流的大小，也不是把机械能变成电能。"},{"type":"h","text":"换个角度：电动机里的能量转化"},{"type":"p","text":"电动机工作时，通电线圈在磁场中受力转动，把电能转化为机械能。但电能并没有全部变成机械能：电流通过线圈时线圈会发热，一部分电能转化为内能，所以电动机的效率不可能达到 100%。要改变电动机的转动方向，可以改变通过线圈的电流方向，也可以改变磁场的方向；要改变转速，则要改变电流的大小。"},{"type":"figure","figure":{"id":"fig-magnet-energy-1","title":"电动机工作时的能量转化","caption":"电能大部分转化为机械能，还有一小部分转化为内能","view":"wide","alt":"方框图中电能输入电动机，电动机输出机械能，同时有一小部分能量以热的形式输出为内能","prims":[{"t":"text","x":50,"y":10,"text":"电动机把电能转化为机械能，同时有一小部分电能转化为内能","size":3.2,"tone":"muted"},{"t":"rect","x":4,"y":22,"w":22,"h":12,"tone":"main","fill":true,"label":"电能"},{"t":"arrow","x1":26,"y1":28,"x2":42,"y2":28,"tone":"accent","label":"输入"},{"t":"rect","x":42,"y":22,"w":22,"h":12,"tone":"accent","label":"电动机"},{"t":"arrow","x1":64,"y1":28,"x2":80,"y2":28,"tone":"ok","label":"输出"},{"t":"rect","x":80,"y":22,"w":18,"h":12,"tone":"ok","fill":true,"label":"机械能"},{"t":"arrow","x1":53,"y1":34,"x2":53,"y2":44,"tone":"danger","label":"少量","labelDx":8},{"t":"rect","x":42,"y":44,"w":22,"h":11,"tone":"danger","fill":true,"label":"内能"},{"t":"text","x":50,"y":59,"text":"线圈发热是电动机能量损失的主要来源之一","size":3.2,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["磁场对通电导线的作用（受力方向）","通电导线在磁场中受到力的作用；力的方向与电流方向、磁场方向都有关：只改变其中一个，受力方向相反；两个同时改变，受力方向不变","定性结论，没有单位 · 初中只作定性判断，不用左手定则做定量计算。用它解释电动机为什么会转动、转动方向如何改变。注意与电磁感应区分：这里是「电生力」，必须有电流；电磁感应是「磁生电」，必须有切割磁感线的相对运动。"],["电动机消耗的电能","W = UIt","W：焦耳（J）；U：伏特（V）；I：安培（A）；t：秒（s） · 计算电动机消耗的总电能。电动机不是纯电阻用电器，消耗的电能只有一部分转化为机械能，其余转化为内能，因此不能把 W = UIt 得到的值直接当作输出的机械功。"],["电动机的效率","η = W_(有用)W_(总) × 100%","η 用百分数表示；W有用 是输出的机械功，W总 是消耗的电能 · W有用 用 W = Fs 计算（匀速提升重物时 W有用 = Gh），W总 用 W = UIt 计算。算出的结果一定小于 100%，差的那部分主要转化为内能使线圈发热。"]]},{"type":"h","text":"应用 · 改变电动机的转动方向与转速"},{"type":"note","title":"情境","text":"一辆玩具电动车前进时，若想让车轮反转（小车后退），或者想让小车跑得更快，应该怎样操作？"},{"type":"note","title":"模型与思路","text":"线圈的受力方向由电流方向和磁场方向决定；线圈转动的快慢由受力的大小（电流大小）决定。"},{"type":"list","title":"解答步骤","items":["要让车轮反转，可以改变通过电动机线圈的电流方向（把接在电动机上的两根导线对调），线圈受力方向相反，转动方向随之相反。","也可以把电动机里的磁体两极对调，改变磁场方向，同样能使转动方向相反。","如果同时改变电流方向和磁场方向，两次「反向」互相抵消，转动方向不变。","要让小车跑得更快，应当增大通过电动机的电流（如提高电源电压），线圈受力变大，转速变快。"]},{"type":"note","title":"结论","text":"转动方向由电流方向和磁场方向共同决定，转速由电流大小决定——这也是电动机可以方便地调速、换向的原因。"},{"type":"h","text":"应用 · 计算机械效率：电动机提升重物"},{"type":"note","title":"情境","text":"一台直流电动机接在 3 V 的电源上，通过线圈的电流是 0.5 A。它在 2 s 内把 5 N 的重物匀速提升了 0.4 m。"},{"type":"note","title":"模型与思路","text":"电动机消耗的电能用 W = UIt 计算；输出的机械功是克服重力做的功，用 W = Gh 计算；两者之比就是电动机的效率。"},{"type":"list","title":"解答步骤","items":["消耗的电能：W总 = UIt = 3 V × 0.5 A × 2 s = 3 J。","匀速提升重物，电动机对重物的拉力 F = G = 5 N，提升距离 s = h = 0.4 m。","输出的机械功：W有用 = Fs = 5 N × 0.4 m = 2 J。","效率：η = W有用/W总 × 100% = 2 J ÷ 3 J × 100% ≈ 66.7%。"]},{"type":"note","title":"结论","text":"这台电动机 2 s 内消耗电能 3 J，输出机械功 2 J，效率约为 66.7%；剩下的 1 J 电能主要转化为内能，使线圈发热。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["把「磁场对通电导线有力的作用」与「电磁感应」混为一谈。","「磁场对通电导线有力的作用」是通电导体在磁场中受力（电生力，电动机的原理）；「电磁感应」是闭合电路的一部分导体做切割磁感线运动时产生电流（磁生电，发电机的原理）。","两件事的条件与结果正好相反：前者必须通上电，结果是导体受力运动；后者必须有相对运动，结果是电路中产生电流。答电动机原理时写「电磁感应」是最典型的失分。"],["认为通电线圈放在磁场里就一定能不停地转下去。","线圈转到与磁场方向垂直的平衡位置时受到平衡力，不能继续转动，必须靠换向器每半周改变一次电流方向才能持续转动。","在平衡位置，两条边受到的力方向相反且在同一直线上，效果互相抵消，线圈只会在附近摆动。换向器的存在正是为了让线圈「转过这个位置后继续被推向同一个方向」。"],["认为电动机把电能全部转化为机械能。","电动机把大部分电能转化为机械能，还有一部分电能转化为内能（线圈发热）。","线圈有电阻，电流通过时会产生热量，所以电动机的效率总小于 100%。计算效率时必须用 W有用/W总，不能直接把消耗的电能都算作机械功。"]]},{"type":"table","title":"电动机与发电机（原理与能量转化方向正好相反，是电与磁这一章最容易混的一对）","head":["比较项","电动机","发电机"],"rows":[["原理","磁场对通电导线有力的作用，通电线圈在磁场中受力转动","电磁感应：闭合电路的一部分导体做切割磁感线运动产生感应电流"],["能量转化","电能 → 机械能","机械能 → 电能"],["外部条件","必须接通电源，线圈中有电流","必须有机械动力使线圈（导体）运动"],["关键部件","换向器：每半周改变线圈中电流的方向","滑环与电刷：把产生的电流输送给外电路"],["典型应用","电风扇、洗衣机、电动车、电梯、扬声器","水电站的发电机、风力发电机、手摇发电机"]]},{"type":"table","title":"通电线圈在磁场中的两个位置（受力情况不同，转动状态也不同）","head":["比较项","线圈平面与磁场方向平行时","线圈平面转到与磁场方向垂直（平衡位置）时"],"rows":[["受力方向","两条边受力方向相反，且不在同一直线上","两条边受力方向相反，且在同一直线上"],["转动情况","受到使线圈转动的力，线圈转动","受到一对平衡力，不能继续转动，只在附近摆动"],["怎样才能继续转","—","靠换向器改变线圈中电流的方向，让它继续向同一方向转动"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["受力方向变化的判断与作图","给出磁场方向、电流方向和导线受力的方向，要求判断「只改变电流方向」「只改变磁场方向」「同时改变两者」时受力方向怎样变化，或用箭头画出受力方向。答题口诀：只改一个，受力反向；两个同时改，受力方向不变。"],["电动机的原理与换向器的作用","常以电动机模型图为情境，考查换向器的作用（每半周改变线圈中电流的方向，使线圈能持续转动）、平衡位置时线圈的受力情况（平衡力，只摆动）。答「换向器改变电流大小」或「换向器把机械能转化为电能」都是错的。"],["电动机的效率与能量转化计算","结合 W = UIt（消耗的电能）与 W = Fs（输出的机械功）求效率，或反过来由效率求电流、求提升高度。要看清「消耗的电能」和「有用的机械能」分别对应哪个公式，不能混用。"]]},{"type":"quote","text":"【材料】某玩具电动车使用直流电动机。工作时，线圈在磁场中受力转动，通过齿轮带动车轮前进；把接在电动机上的两根导线对调，车轮就会反转，小车后退；提高电源电压、增大通过电动机的电流，小车就跑得更快。\n【数据】某次实验中，电动机两端的电压为 3 V，通过电动机的电流为 0.5 A，通电时间为 2 s；小车在这段时间内沿水平方向匀速前进 0.4 m，前进过程中受到的阻力为 5 N。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）材料中说「把接在电动机上的两根导线对调，小车就会后退」，请说明其中的道理。（3 分）","【设问】（2）求这台电动机在 2 s 内消耗的电能。（2 分）","【设问】（3）求这台电动机把电能转化为机械能的效率（结果保留到 0.1%）。（3 分）"]}],"questions":[{"id":"phy-magnet-4-q1","type":"choice","stem":"通电导线在磁场中受到力的作用，这个力的方向","answer":"C","explain":"C 正确：磁场对通电导线的作用力方向由电流方向和磁场方向共同决定——只改变其中一个，受力方向相反；两个同时改变，受力方向不变。A、B 都只说了一个因素，不完整：只改变电流方向受力会相反，只改变磁场方向受力也会相反，说明两者都起作用。D 错：如果受力方向与两者都无关，实验中改变电流或磁场方向时导线运动方向就不会改变，与事实不符。","options":["只与电流方向有关","只与磁场方向有关","与电流方向和磁场方向都有关，只改变其中一个，受力方向就相反","与电流方向、磁场方向都无关"],"difficulty":1,"tags":["受力方向"]},{"id":"phy-magnet-4-q2","type":"choice","stem":"把通电的矩形线圈放在磁场中，线圈会转动起来，这是因为","answer":"A","explain":"A 正确：线圈的两条边电流方向相反，受到的磁场力方向也相反，这两个力不在同一直线上，于是使线圈绕轴转动。B 错：线圈转动是「通电导体在磁场中受力」的结果，不是电磁感应；电磁感应是「磁生电」。C 错：线圈转动与磁化无关，它本来就是通电导体。D 错：重力方向竖直向下，与线圈的转动没有这种平衡关系。","options":["线圈两条边中电流的方向相反，它们受到的磁场力方向也相反，形成使线圈转动的力","线圈中产生了感应电流","线圈在磁场中被磁化了，被磁体吸引而转动","线圈受到的重力与磁场力平衡，被推动着转动"],"difficulty":2,"tags":["线圈转动"]},{"id":"phy-magnet-4-q3","type":"choice","stem":"如图，一条导线垂直于纸面，电流流入纸面（用 ⊗表示），磁体两极之间的磁场方向水平向右（由 N 极指向 S 极）。这条导线受到的磁场力方向是","answer":"D","explain":"D 正确：磁场对通电导线的作用力方向同时垂直于电流方向和磁场方向。磁场水平向右、电流流入纸面时，由实验规律可知导线受力竖直向下（详见本知识点的讲解图）。A 错：力的方向与磁场方向垂直，不可能沿磁场方向。B 错：把电流方向与受力方向弄反了——电流方向反过来，受力方向才变成向上。C 错：力的方向必须与电流方向垂直，不可能沿电流方向。","options":["水平向右","竖直向上","沿导线的方向，流入纸面","竖直向下"],"difficulty":2,"tags":["受力方向","磁场对通电导线"],"figure":{"id":"fig-magnet-q3-4","title":"导线垂直于纸面时的受力判断","caption":"磁场水平向右，电流流入纸面（⊗）","view":"wide","alt":"磁体 N 极在左、S 极在右，两极之间画有水平向右的磁场箭头；中间一条导线垂直于纸面，用 ⊗表示电流流入纸面，导线受到的力方向没有画出","prims":[{"t":"rect","x":2,"y":22,"w":12,"h":16,"tone":"danger","fill":true},{"t":"text","x":8,"y":30,"text":"N"},{"t":"rect","x":86,"y":22,"w":12,"h":16,"tone":"accent","fill":true},{"t":"text","x":92,"y":30,"text":"S"},{"t":"arrow","x1":16,"y1":14,"x2":84,"y2":14,"tone":"muted","label":"B"},{"t":"arrow","x1":16,"y1":30,"x2":43,"y2":30,"tone":"muted"},{"t":"arrow","x1":57,"y1":30,"x2":84,"y2":30,"tone":"muted"},{"t":"arrow","x1":16,"y1":46,"x2":84,"y2":46,"tone":"muted"},{"t":"circle","cx":50,"cy":30,"r":6},{"t":"line","x1":45.8,"y1":25.8,"x2":54.2,"y2":34.2},{"t":"line","x1":45.8,"y1":34.2,"x2":54.2,"y2":25.8},{"t":"text","x":50,"y":59,"text":"⊗ 表示电流流入纸面","size":3.4,"tone":"muted"}]}},{"id":"phy-magnet-4-q4","type":"choice","stem":"直流电动机中换向器的作用是","answer":"B","explain":"B 正确：线圈转到平衡位置时受到平衡力，不能再继续转动；换向器由两个彼此绝缘的半圆铜环组成，线圈每转过平衡位置就自动改变线圈中电流的方向，使线圈始终受到同方向的推力，从而持续转动。A 错：换向器改变的是电流的方向，不是大小；改变转速要靠改变电流大小。C 错：把机械能转化为电能是发电机的工作，电动机正好相反。D 错：换向器不改变线圈的电阻。","options":["改变线圈中电流的大小，从而改变电动机的转速","在线圈每转过平衡位置时改变线圈中电流的方向，使线圈能够持续转动","把线圈的机械能转化为电能","减小线圈的电阻，使通过线圈的电流变大"],"difficulty":2,"tags":["换向器","电动机"]},{"id":"phy-magnet-4-q5","type":"choice","stem":"关于电动机工作时的能量转化，下列说法正确的是","answer":"A","explain":"A 正确：电动机的主要作用是把电能转化为机械能，但线圈有电阻，电流通过时会发热，所以还有一小部分电能转化为内能，它的效率总小于 100%。B 错：把机械能转化为电能的是发电机。C 错：如果电能全部转化为机械能，效率就是 100%，这与「线圈发热」的事实不符。D 错：电动机工作时一定消耗电能，也一定产生内能。","options":["电动机把电能转化为机械能，同时有一小部分电能转化为内能","电动机把机械能转化为电能","电动机把电能全部转化为机械能","电动机工作时既不消耗电能，也不产生其他形式的能"],"difficulty":1,"tags":["能量转化","效率"]},{"id":"phy-magnet-4-q6","type":"fill","stem":"要改变直流电动机的转动方向，可以改变通过线圈的____方向，也可以改变磁场的方向。","answer":"电流","explain":"磁场对通电导线的作用力方向与电流方向、磁场方向都有关：改变其中一个，受力方向就相反，转动方向随之相反；两个同时改变，转动方向不变。","difficulty":1,"tags":["转动方向"]},{"id":"phy-magnet-4-q7","type":"short","stem":"如图，一段导线垂直于纸面放在磁体两极之间，磁体的磁场方向水平向右，导线中电流流入纸面（⊗），此时导线受到的磁场力方向竖直向下。请回答：① 若只把电流方向反过来（电流流出纸面），导线受到的力方向怎样？② 若只把磁体的两极对调（磁场方向水平向左），导线受到的力方向怎样？③ 若把电流方向和磁场方向同时反过来，导线受到的力方向又怎样？请把②③两种情况下导线受力的方向画在答案图中。","answer":"① 只改变电流方向，受力方向相反，变为竖直向上。② 只改变磁场方向，受力方向也相反，变为竖直向上。③ 电流方向和磁场方向同时改变，两个「反向」互相抵消，受力方向与原来相同，仍是竖直向下。答案图：②中磁场向左、电流流入纸面，导线受力竖直向上；③中磁场向左、电流流出纸面，导线受力竖直向下。","explain":"本题只考一条规律：磁场对通电导线的作用力方向由电流方向和磁场方向共同决定，只改变其中一个受力方向就相反，两个同时改变受力方向不变。① 只反电流 → 反向 → 向上。② 只反磁场 → 反向 → 向上（与①结果相同，但原因不同，答题时要写清是哪一个因素变了）。③ 两个都反 → 不变 → 仍向下。常见的错误是③答成「向上」，那是把两次反向当成了「反向两次等于同向一次」之外的情况；也有的同学②答成向下，说明把「磁场方向反过来」漏掉了。","difficulty":3,"tags":["作图题","受力方向"],"rubric":["① 答出受力方向变为竖直向上","② 答出受力方向变为竖直向上，并在图中画出向上的箭头","③ 答出受力方向不变（仍竖直向下），并在图中画出向下的箭头","三次判断都能说明依据：力的方向与电流方向、磁场方向都有关"],"steps":["第一步：明确原来的情况——磁场向右、电流流入纸面，导线受力向下。","第二步：① 只反电流 → 受力反向 → 向上。","第三步：② 只反磁场 → 受力反向 → 向上；在图中画出磁场向左、电流 ⊗的图，并画竖直向上的力箭头。","第四步：③ 电流与磁场同时反向 → 受力方向与原来相同 → 仍向下；在图中画出磁场向左、电流 ⊙的图，并画竖直向下的力箭头。"],"figure":{"id":"fig-magnet-q7-5","title":"原来的情况：受力竖直向下","caption":"磁场水平向右，导线中电流流入纸面（⊗）","view":"wide","alt":"磁体 N 极在左、S 极在右，磁场箭头水平向右；中间导线垂直于纸面、电流流入纸面（⊗），导线受到的力竖直向下，用向下的箭头表示","prims":[{"t":"rect","x":2,"y":22,"w":12,"h":16,"tone":"danger","fill":true},{"t":"text","x":8,"y":30,"text":"N"},{"t":"rect","x":86,"y":22,"w":12,"h":16,"tone":"accent","fill":true},{"t":"text","x":92,"y":30,"text":"S"},{"t":"arrow","x1":16,"y1":14,"x2":84,"y2":14,"tone":"muted","label":"B"},{"t":"arrow","x1":16,"y1":30,"x2":43,"y2":30,"tone":"muted"},{"t":"arrow","x1":57,"y1":30,"x2":84,"y2":30,"tone":"muted"},{"t":"circle","cx":50,"cy":30,"r":6},{"t":"line","x1":45.8,"y1":25.8,"x2":54.2,"y2":34.2},{"t":"line","x1":45.8,"y1":34.2,"x2":54.2,"y2":25.8},{"t":"arrow","x1":50,"y1":38,"x2":50,"y2":54,"tone":"accent","label":"F","labelDx":5},{"t":"text","x":50,"y":59,"text":"电流流入纸面，受力竖直向下","size":3.4,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q7-6","title":"答案图：②只反磁场受力向上，③同时反向受力仍向下","caption":"左图为②（磁场向左、电流 ⊗，受力向上），右图为③（磁场向左、电流 ⊙，受力向下）","view":"wide","alt":"左图：S 极在左、N 极在右，磁场水平向左，导线电流流入纸面（⊗），受力竖直向上；右图：S 极在左、N 极在右，磁场水平向左，导线电流流出纸面（⊙），受力竖直向下","prims":[{"t":"rect","x":2,"y":22,"w":10,"h":14,"tone":"accent","fill":true},{"t":"text","x":7,"y":29,"text":"S","size":3.6},{"t":"rect","x":36,"y":22,"w":10,"h":14,"tone":"danger","fill":true},{"t":"text","x":41,"y":29,"text":"N","size":3.6},{"t":"arrow","x1":34,"y1":16,"x2":14,"y2":16,"tone":"muted","label":"B"},{"t":"circle","cx":24,"cy":29,"r":4.5},{"t":"line","x1":20.8,"y1":25.8,"x2":27.2,"y2":32.2},{"t":"line","x1":20.8,"y1":32.2,"x2":27.2,"y2":25.8},{"t":"arrow","x1":24,"y1":22,"x2":24,"y2":8,"tone":"accent","label":"F","labelDx":5},{"t":"text","x":24,"y":44,"text":"② 受力向上","size":3.4,"tone":"muted"},{"t":"rect","x":52,"y":22,"w":10,"h":14,"tone":"accent","fill":true},{"t":"text","x":57,"y":29,"text":"S","size":3.6},{"t":"rect","x":86,"y":22,"w":10,"h":14,"tone":"danger","fill":true},{"t":"text","x":91,"y":29,"text":"N","size":3.6},{"t":"arrow","x1":84,"y1":16,"x2":64,"y2":16,"tone":"muted","label":"B"},{"t":"circle","cx":74,"cy":29,"r":4.5},{"t":"junction","x":74,"y":29},{"t":"arrow","x1":74,"y1":36,"x2":74,"y2":50,"tone":"accent","label":"F","labelDx":5},{"t":"text","x":74,"y":56,"text":"③ 受力仍向下","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":59.5,"text":"只改一个，受力反向；两个同时改，受力不变","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-4-q8","type":"short","stem":"某小组用如图装置探究「磁场对通电导线的作用力方向与哪些因素有关」：把一段导线垂直放在磁体的两极之间（磁场方向水平向右），接通电源后导线会向上（或向下）运动。请回答：① 要探究力的方向与电流方向是否有关，应该怎样操作、观察什么现象？② 若把磁体的两极对调，导线的受力方向反过来，可以得出什么结论？③ 若同时改变电流方向和磁场方向，导线的受力方向会怎样？为什么？","answer":"① 保持磁体的位置（磁场方向）和其他条件不变，只把电源的正负极对调，改变导线中的电流方向，闭合开关后观察导线运动的方向；如果运动方向与原来相反，说明力的方向与电流方向有关。② 说明磁场对通电导线的作用力方向与磁场方向有关：在其他条件相同时，磁场方向反过来，受力方向也反过来。③ 受力方向与原来相同。因为电流方向和磁场方向同时改变时，两次「受力方向反向」互相抵消，受力方向不变。","explain":"探究题的核心是控制变量：要研究电流方向的作用，就只能让电流方向这一个因素变化，磁场方向、磁场强弱、电流大小都要保持不变，否则无法判断结果是由哪个因素造成的。②的结论表述要带条件——「在其他条件相同时」。③考的是「两个因素同时改变」的结果：受力方向由这两个因素共同决定，两次反向叠加正好抵消，所以与原来相同。这也是判断这类问题时最容易被忽略的一条。","difficulty":3,"tags":["实验探究","控制变量法"],"rubric":["① 答出保持磁场方向等其他条件不变，只对调电源正负极改变电流方向","① 答出观察导线运动方向是否相反","② 答出结论：受力方向与磁场方向有关（磁场方向改变，受力方向相反）","③ 答出受力方向不变，并说明两次反向互相抵消"],"steps":["① 写明操作：保持磁体（磁场方向）不变 → 对调电源正负极 → 闭合开关 → 观察并比较导线运动方向。","② 写出带条件的结论：其他条件相同时，磁场方向反过来，受力方向也反过来。","③ 先说明两个因素同时改变，再说明两次反向互相抵消，结论是受力方向不变。"],"figure":{"id":"fig-magnet-q8-4","title":"探究受力方向与哪些因素有关的装置","caption":"磁场方向水平向右，导线垂直于纸面放在两极之间","view":"wide","alt":"磁体 N 极在左、S 极在右，磁场箭头水平向右；中间一条导线垂直于纸面（未标出电流方向），导线与电源、开关串联成回路","prims":[{"t":"rect","x":2,"y":20,"w":12,"h":16,"tone":"danger","fill":true},{"t":"text","x":8,"y":28,"text":"N"},{"t":"rect","x":86,"y":20,"w":12,"h":16,"tone":"accent","fill":true},{"t":"text","x":92,"y":28,"text":"S"},{"t":"arrow","x1":16,"y1":12,"x2":84,"y2":12,"tone":"muted","label":"B"},{"t":"arrow","x1":16,"y1":28,"x2":43,"y2":28,"tone":"muted"},{"t":"arrow","x1":57,"y1":28,"x2":84,"y2":28,"tone":"muted"},{"t":"circle","cx":50,"cy":28,"r":6},{"t":"line","x1":50,"y1":34,"x2":50,"y2":46},{"t":"line","x1":50,"y1":22,"x2":50,"y2":12},{"t":"line","x1":50,"y1":46,"x2":20,"y2":46},{"t":"line","x1":20,"y1":46,"x2":20,"y2":56},{"t":"line","x1":20,"y1":56,"x2":80,"y2":56},{"t":"battery","x":34,"y":56,"label":"电源"},{"t":"switch","x":66,"y":56,"closed":true,"label":"S"},{"t":"line","x1":80,"y1":56,"x2":80,"y2":34},{"t":"line","x1":80,"y1":34,"x2":56,"y2":34},{"t":"text","x":50,"y":59.5,"text":"导线垂直于纸面，接在电源与开关的回路中","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-4-q9","type":"short","stem":"一台直流电动机接在 3 V 的电源上，通过线圈的电流是 0.5 A。求：① 通电 2 s 内电动机消耗的电能；② 若这台电动机在这 2 s 内把 5 N 的重物匀速提升 0.4 m，它输出的机械功是多少？③ 这台电动机的效率（结果保留到 0.1%）。","answer":"① W总 = UIt = 3 V × 0.5 A × 2 s = 3 J。② 匀速提升重物时，电动机对重物的拉力 F = G = 5 N，重物升高的距离 s = h = 0.4 m，所以 W有用 = Fs = Gh = 5 N × 0.4 m = 2 J。③ η = W有用/W总 × 100% = 2 J ÷ 3 J × 100% ≈ 66.7%。","explain":"这类题的关键是分清「消耗的电能」和「有用的机械能」。① 电动机消耗的电能用电学公式 W = UIt 算。② 电动机输出的机械功是克服重力做的功，因为重物匀速上升，拉力与重力平衡，所以 F = G，用 W = Fs 计算。③ 效率是有用功与总功之比，结果是百分数，永远小于 100%——剩下的 1 J 主要使线圈发热，转化为内能。常见错误是把 3 J 直接当成机械功，或者把效率算成 3 J ÷ 2 J（把分子分母写反）。","difficulty":2,"tags":["电能计算","效率"],"rubric":["① 写出公式 W = UIt 并算出 3 J","② 由匀速提升得出拉力等于重力，用 W = Fs 算出 2 J","③ 写出效率公式 η = W有用/W总 × 100%，算出约 66.7%"],"steps":["① 已知 U = 3 V、I = 0.5 A、t = 2 s；W总 = UIt = 3 V × 0.5 A × 2 s = 3 J。","② 匀速提升 → F = G = 5 N；s = h = 0.4 m；W有用 = Fs = 5 N × 0.4 m = 2 J。","③ η = W有用/W总 × 100% = 2 J ÷ 3 J × 100% ≈ 66.7%。"]},{"id":"phy-magnet-4-m1-q1","type":"short","stem":"（1）材料中说「把接在电动机上的两根导线对调，小车就会后退」，请说明其中的道理。（3 分）","answer":"把两根导线对调，就是改变了通过电动机线圈的电流方向。磁场对通电导线的作用力的方向与电流方向有关：电流方向反过来，线圈受到的作用力方向也反过来，线圈的转动方向随之相反，车轮的转动方向相反，小车就由前进变为后退。","explain":"","tags":["电动机","受力方向"],"rubric":["答出对调导线就是改变线圈中的电流方向","答出受力方向与电流方向有关（电流方向改变，受力方向相反）","答出转动方向相反，所以小车后退"]},{"id":"phy-magnet-4-m1-q2","type":"short","stem":"（2）求这台电动机在 2 s 内消耗的电能。（2 分）","answer":"W总 = UIt = 3 V × 0.5 A × 2 s = 3 J。","explain":"","tags":["电能计算"],"rubric":["写出公式 W = UIt","代入数据并算出 3 J（带单位）"]},{"id":"phy-magnet-4-m1-q3","type":"short","stem":"（3）求这台电动机把电能转化为机械能的效率（结果保留到 0.1%）。（3 分）","answer":"小车匀速前进，电动机提供的牵引力与阻力平衡，F = f = 5 N；输出的机械功 W有用 = Fs = 5 N × 0.4 m = 2 J；效率 η = W有用/W总 × 100% = 2 J ÷ 3 J × 100% ≈ 66.7%。","explain":"","tags":["效率","功"],"rubric":["由匀速前进判断牵引力与阻力平衡，得出 F = 5 N","用 W = Fs 算出机械功 2 J","用 η = W有用/W总 算出效率约为 66.7%"]}]},{"id":"phy-magnet-5","title":"电磁感应·发电机","subtitle":"人教版九年级 · 第 20 章 电与磁 · 9a","grade":"9a","tags":["人教版九年级 · 第 20 章 电与磁"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 20 章 电与磁 · 9a"},{"type":"note","title":"问题切入","text":"不用干电池，怎样才能让小灯泡亮起来？发电机里的电流究竟是从哪里来的？"},{"type":"note","title":"一句话抓住关键","text":"闭合电路的一部分导体在磁场中做切割磁感线运动时，导体中就会产生感应电流，这种现象叫电磁感应，这样产生的电流叫感应电流；感应电流的方向与导体运动方向、磁场方向都有关，大小与运动快慢、磁场强弱、线圈匝数有关；发电机根据电磁感应制成，把机械能转化为电能，产生的是交流电。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"发电机不用电池也能发电，靠的是「导体在磁场中切割磁感线」。","walk":["闭合电路的一部分导体做切割磁感线运动，导体中就会产生感应电流，这叫电磁感应。","感应电流的方向与导体运动方向、磁场方向有关。","感应电流的大小与切割速度、磁场强弱、线圈匝数有关。"],"try":"用导线接一个小灯泡，在强磁铁两极间快速摆动导线，观察灯泡微微发亮。","use":["判断有无感应电流：电路是否闭合、是否做切割磁感线运动。","发电机：机械能转化为电能。"]},{"type":"h","text":"先看现象：导体一动，电流计的指针就偏转"},{"type":"p","text":"把一段导体 AB 用导线和一个灵敏电流计连成闭合回路，让导体处在磁场中（磁场垂直于纸面向里）。让导体上下运动，电流计的指针发生偏转，说明电路中产生了电流；把导体停下来，指针又回到零刻度；让导体反向运动，指针向另一侧偏转。这一现象由英国物理学家法拉第最早发现，叫电磁感应现象，这样产生的电流叫感应电流。注意它和前面学过的「磁场对通电导线的作用」正好相反：这里电路中本来没有电源，电流是「动出来」的。"},{"type":"figure","figure":{"id":"fig-magnet-induction-1","title":"电磁感应现象","caption":"闭合电路的一部分导体在磁场中做切割磁感线运动，电路中产生感应电流","view":"wide","alt":"一段导体 AB 用导线与灵敏电流计连成闭合回路，磁场垂直于纸面向里（用 ⊗表示）；导体受到竖直向上的运动方向箭头，电路中产生感应电流","prims":[{"t":"text","x":50,"y":4,"text":"闭合电路的一部分导体做切割磁感线运动，产生感应电流","size":3.2,"tone":"muted"},{"t":"circle","cx":20,"cy":13,"r":3},{"t":"line","x1":17.9,"y1":10.9,"x2":22.1,"y2":15.1},{"t":"line","x1":17.9,"y1":15.1,"x2":22.1,"y2":10.9},{"t":"circle","cx":44,"cy":10,"r":3},{"t":"line","x1":41.9,"y1":7.9,"x2":46.1,"y2":12.1},{"t":"line","x1":41.9,"y1":12.1,"x2":46.1,"y2":7.9},{"t":"circle","cx":70,"cy":12,"r":3},{"t":"line","x1":67.9,"y1":9.9,"x2":72.1,"y2":14.1},{"t":"line","x1":67.9,"y1":14.1,"x2":72.1,"y2":9.9},{"t":"circle","cx":20,"cy":38,"r":3},{"t":"line","x1":17.9,"y1":35.9,"x2":22.1,"y2":40.1},{"t":"line","x1":17.9,"y1":40.1,"x2":22.1,"y2":35.9},{"t":"circle","cx":44,"cy":40,"r":3},{"t":"line","x1":41.9,"y1":37.9,"x2":46.1,"y2":42.1},{"t":"line","x1":41.9,"y1":42.1,"x2":46.1,"y2":37.9},{"t":"circle","cx":70,"cy":38,"r":3},{"t":"line","x1":67.9,"y1":35.9,"x2":72.1,"y2":40.1},{"t":"line","x1":67.9,"y1":40.1,"x2":72.1,"y2":35.9},{"t":"line","x1":30,"y1":26,"x2":70,"y2":26,"width":0.9},{"t":"text","x":27,"y":23,"text":"A","size":3.6,"tone":"muted"},{"t":"text","x":73,"y":23,"text":"B","size":3.6,"tone":"muted"},{"t":"arrow","x1":78,"y1":36,"x2":78,"y2":18,"tone":"accent","label":"v","labelDx":5},{"t":"line","x1":30,"y1":26,"x2":14,"y2":26},{"t":"line","x1":14,"y1":26,"x2":14,"y2":48},{"t":"line","x1":70,"y1":26,"x2":86,"y2":26},{"t":"line","x1":86,"y1":26,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":86,"y2":48},{"t":"meter","x":50,"y":48,"kind":"A","label":"灵敏电流计"},{"t":"text","x":50,"y":58,"text":"⊗ 表示磁场垂直于纸面向里","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"这一节是「磁生电」：电路中不要电源，靠导体的相对运动产生电流。"},{"type":"h","text":"抓条件：怎样运动才有感应电流"},{"type":"p","text":"把实验的各种情况摆在一起比较：导体静止不动，指针不偏转；导体沿着它自己的长度方向（水平方向）运动，指针也不偏转；只有导体做切割磁感线运动（运动方向与磁感线方向不平行）时，指针才偏转；如果电路断开，即使导体做切割磁感线运动，也没有电流。所以产生感应电流必须同时满足三个条件：电路要闭合、导体要在磁场中、导体要做切割磁感线运动。"},{"type":"figure","figure":{"id":"fig-magnet-condition-1","title":"两种运动方式的对比","caption":"垂直于磁感线方向运动（竖直方向）才切割磁感线，沿导体自身长度方向运动不切割磁感线","view":"wide","alt":"磁场垂直于纸面向里（⊗）；导体 AB 上方画着竖直的双向箭头，标注「切割磁感线，有感应电流」；导体一端画着水平方向的双向箭头，标注「沿导体方向运动，无感应电流」","prims":[{"t":"circle","cx":20,"cy":12,"r":3},{"t":"line","x1":17.9,"y1":9.9,"x2":22.1,"y2":14.1},{"t":"line","x1":17.9,"y1":14.1,"x2":22.1,"y2":9.9},{"t":"circle","cx":44,"cy":10,"r":3},{"t":"line","x1":41.9,"y1":7.9,"x2":46.1,"y2":12.1},{"t":"line","x1":41.9,"y1":12.1,"x2":46.1,"y2":7.9},{"t":"circle","cx":68,"cy":12,"r":3},{"t":"line","x1":65.9,"y1":9.9,"x2":70.1,"y2":14.1},{"t":"line","x1":65.9,"y1":14.1,"x2":70.1,"y2":9.9},{"t":"circle","cx":20,"cy":44,"r":3},{"t":"line","x1":17.9,"y1":41.9,"x2":22.1,"y2":46.1},{"t":"line","x1":17.9,"y1":46.1,"x2":22.1,"y2":41.9},{"t":"circle","cx":44,"cy":46,"r":3},{"t":"line","x1":41.9,"y1":43.9,"x2":46.1,"y2":48.1},{"t":"line","x1":41.9,"y1":48.1,"x2":46.1,"y2":43.9},{"t":"circle","cx":68,"cy":44,"r":3},{"t":"line","x1":65.9,"y1":41.9,"x2":70.1,"y2":46.1},{"t":"line","x1":65.9,"y1":46.1,"x2":70.1,"y2":41.9},{"t":"line","x1":22,"y1":30,"x2":66,"y2":30,"width":0.9},{"t":"text","x":19,"y":27,"text":"A","size":3.6,"tone":"muted"},{"t":"text","x":69,"y":27,"text":"B","size":3.6,"tone":"muted"},{"t":"arrow","x1":40,"y1":26,"x2":40,"y2":16,"tone":"ok","both":true,"label":"切割磁感线，有电流","labelDx":24},{"t":"arrow","x1":44,"y1":30,"x2":58,"y2":30,"tone":"danger","both":true,"label":"沿导体方向运动，无电流","labelDx":4,"labelDy":6},{"t":"text","x":50,"y":58,"text":"判定方法：看运动方向是否与磁感线方向平行","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"三个条件缺一不可：电路闭合、导体在磁场中、做切割磁感线运动。"},{"type":"h","text":"抓住方向：只改一个，电流方向反向"},{"type":"p","text":"感应电流的方向跟导体运动的方向、磁场的方向都有关。让导体竖直向上运动时，导体中的电流由 B 流向 A；只把运动方向改成竖直向下，电流就变成由 A 流向 B，方向与原来相反；只把磁体的两极对调、改变磁场方向，电流方向也相反；如果把运动方向和磁场方向同时反过来，感应电流的方向反而不变。这与磁场对通电导线的作用力方向遵循的是同一套「只改一个就反向，两个同时改就不变」的判断办法。"},{"type":"figure","figure":{"id":"fig-magnet-induction-dir-1","title":"只改变运动方向，感应电流方向相反","caption":"磁场方向不变（都是垂直于纸面向里），导体向上、向下运动时导体中的电流方向相反","view":"wide","alt":"左图：导体 AB 竖直向上运动，导体中的电流由右端 B 流向左端 A，用向左的箭头表示；右图：导体 AB 竖直向下运动，导体中的电流由 A 流向 B，用向右的箭头表示；两图的磁场都垂直于纸面向里","prims":[{"t":"circle","cx":14,"cy":8,"r":3},{"t":"line","x1":11.9,"y1":5.9,"x2":16.1,"y2":10.1},{"t":"line","x1":11.9,"y1":10.1,"x2":16.1,"y2":5.9},{"t":"circle","cx":34,"cy":8,"r":3},{"t":"line","x1":31.9,"y1":5.9,"x2":36.1,"y2":10.1},{"t":"line","x1":31.9,"y1":10.1,"x2":36.1,"y2":5.9},{"t":"circle","cx":14,"cy":30,"r":3},{"t":"line","x1":11.9,"y1":27.9,"x2":16.1,"y2":32.1},{"t":"line","x1":11.9,"y1":32.1,"x2":16.1,"y2":27.9},{"t":"circle","cx":34,"cy":30,"r":3},{"t":"line","x1":31.9,"y1":27.9,"x2":36.1,"y2":32.1},{"t":"line","x1":31.9,"y1":32.1,"x2":36.1,"y2":27.9},{"t":"line","x1":8,"y1":20,"x2":38,"y2":20,"width":0.9},{"t":"text","x":5,"y":16,"text":"A","size":3.4,"tone":"muted"},{"t":"text","x":41,"y":16,"text":"B","size":3.4,"tone":"muted"},{"t":"arrow","x1":24,"y1":14,"x2":24,"y2":4,"tone":"ok","label":"v"},{"t":"arrow","x1":34,"y1":20,"x2":14,"y2":20,"tone":"accent","label":"I"},{"t":"text","x":26,"y":40,"text":"向上运动：电流 B→A","size":3.2,"tone":"muted"},{"t":"circle","cx":64,"cy":8,"r":3},{"t":"line","x1":61.9,"y1":5.9,"x2":66.1,"y2":10.1},{"t":"line","x1":61.9,"y1":10.1,"x2":66.1,"y2":5.9},{"t":"circle","cx":84,"cy":8,"r":3},{"t":"line","x1":81.9,"y1":5.9,"x2":86.1,"y2":10.1},{"t":"line","x1":81.9,"y1":10.1,"x2":86.1,"y2":5.9},{"t":"circle","cx":64,"cy":30,"r":3},{"t":"line","x1":61.9,"y1":27.9,"x2":66.1,"y2":32.1},{"t":"line","x1":61.9,"y1":32.1,"x2":66.1,"y2":27.9},{"t":"circle","cx":84,"cy":30,"r":3},{"t":"line","x1":81.9,"y1":27.9,"x2":86.1,"y2":32.1},{"t":"line","x1":81.9,"y1":32.1,"x2":86.1,"y2":27.9},{"t":"line","x1":58,"y1":20,"x2":88,"y2":20,"width":0.9},{"t":"text","x":55,"y":16,"text":"A","size":3.4,"tone":"muted"},{"t":"text","x":91,"y":16,"text":"B","size":3.4,"tone":"muted"},{"t":"arrow","x1":74,"y1":4,"x2":74,"y2":14,"tone":"ok","label":"v"},{"t":"arrow","x1":64,"y1":20,"x2":84,"y2":20,"tone":"accent","label":"I"},{"t":"text","x":76,"y":40,"text":"向下运动：电流 A→B","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"两图中磁场方向相同，只有运动方向相反","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"所以导体中感应电流的方向相反","size":3.2,"tone":"muted"}]}},{"type":"h","text":"建立联系：发电机与交流电"},{"type":"p","text":"把线圈和电流计连成闭合回路，让线圈在磁场中转动（线圈的两条边不断做切割磁感线运动），电流计的指针就会不停地左右摆动，说明线圈中产生了电流，而且电流的方向在不断地改变。这种大小和方向都随时间做周期性变化的电流叫交流电。发电机就是根据电磁感应制成的，它把机械能转化为电能。线圈每转过一周，电流的方向改变两次。我国家庭电路使用的交流电频率是 50 Hz，也就是 1 s 内有 50 个周期，周期是 0.02 s，因此 1 s 内电流的方向改变 100 次。"},{"type":"figure","figure":{"id":"fig-magnet-ac-1","title":"交流电的波形","caption":"交流电的大小和方向都随时间做周期性变化，一个周期 0.02 s（频率 50 Hz）","view":"square","alt":"一个电流随时间变化的图像：曲线在时间轴上下周期性起伏，一个完整周期对应 0.02 s；曲线是正弦形状，说明电流方向每隔半个周期改变一次","prims":[{"t":"text","x":50,"y":8,"text":"交流电：大小和方向都随时间做周期性变化","size":3.2,"tone":"muted"},{"t":"axis","x":14,"y":70,"w":70,"h":56,"xLabel":"t/s","yLabel":"i/A","origin":true,"xTicks":[{"at":0.5,"label":"0.01"},{"at":1,"label":"0.02"}]},{"t":"line","x1":14,"y1":40,"x2":84,"y2":40,"dashed":true,"tone":"muted"},{"t":"curve","points":[[14,40],[22.75,23],[31.5,16],[40.25,23],[49,40],[57.75,57],[66.5,64],[75.25,57],[84,40]],"tone":"accent"},{"t":"text","x":50,"y":82,"text":"一个周期 T = 0.02 s，1 s 内电流方向改变 100 次","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"交流电的「交流」说的是方向在变，不只是大小在变。"},{"type":"h","text":"换个角度：发电机里的能量转化"},{"type":"p","text":"发电机把机械能转化为电能：水力发电用流水冲击水轮机带着发电机转动，风力发电用风推动叶片，火力发电用燃料燃烧产生的高温高压蒸汽推动汽轮机。不管哪一种，都是「先有机械运动，才有电」，这与电动机「先有电，才有机械运动」正好相反。发电机输出的电能来自它消耗的机械能，其中还有一部分因为摩擦、发热而损耗，能量的总量仍然守恒。"},{"type":"figure","figure":{"id":"fig-magnet-generator-energy-1","title":"发电机工作时的能量转化","caption":"机械能输入发电机，发电机输出电能，能量转化的方向与电动机相反","view":"wide","alt":"方框图中机械能输入发电机，发电机输出电能，再由电能驱动用电器工作","prims":[{"t":"text","x":50,"y":8,"text":"发电机把机械能转化为电能（与电动机相反）","size":3.4,"tone":"muted"},{"t":"rect","x":4,"y":24,"w":22,"h":12,"tone":"ok","fill":true,"label":"机械能"},{"t":"arrow","x1":26,"y1":30,"x2":42,"y2":30,"tone":"accent","label":"输入"},{"t":"rect","x":42,"y":24,"w":22,"h":12,"tone":"accent","label":"发电机"},{"t":"arrow","x1":64,"y1":30,"x2":80,"y2":30,"tone":"main","label":"输出"},{"t":"rect","x":80,"y":24,"w":18,"h":12,"tone":"main","fill":true,"label":"电能"},{"t":"arrow","x1":89,"y1":36,"x2":89,"y2":44,"tone":"main"},{"t":"rect","x":78,"y":44,"w":21,"h":11,"tone":"muted","label":"用电器"},{"t":"text","x":40,"y":52,"text":"水轮机、汽轮机、风车提供机械能","size":3.2,"tone":"muted"},{"t":"text","x":40,"y":58,"text":"摩擦与发热会损耗一部分能量","size":3.2,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["感应电流产生的条件","闭合电路的一部分导体在磁场中做切割磁感线运动时，导体中就会产生感应电流","定性条件，没有单位 · 三个条件缺一不可：① 电路必须闭合；② 导体在磁场中；③ 导体做切割磁感线运动（运动方向与磁感线方向不平行）。静止不动、沿磁感线方向运动、沿导体自身长度方向运动、电路断开，都不能产生感应电流。导体不动而让磁体运动也算相对运动，同样能产生感应电流。"],["感应电流方向与大小的规律","方向：与导体运动方向和磁场方向都有关（只改变其中一个，方向相反；两个同时改变，方向不变）；大小：导体运动越快、磁场越强、线圈匝数越多，感应电流越大","定性规律，没有单位 · 用来判断「换一个方向运动，电流往哪流」这类问题。注意把「方向」和「大小」分开回答，并把它与电动机的原理（通电导体受力）区分开：那条规律讲的是受力方向，这条讲的是电流方向。"],["频率与周期的关系","f = (1)/(T)","f：赫兹（Hz）；T：秒（s） · 用于描述交流电。我国家庭电路的交流电 f = 50 Hz，T = 0.02 s。变形用法：T = 1/f。一个周期内线圈转过一周、电流方向改变两次，所以 1 s 内电流方向改变的次数是 2f（50 Hz 时为 100 次）。"]]},{"type":"h","text":"应用 · 手摇发电机为什么能让小灯泡亮起来"},{"type":"note","title":"情境","text":"一台手摇发电机，线圈两端接在小灯泡上。慢慢摇动手柄，小灯泡发出微弱的光；加快摇动，小灯泡变亮；停止摇动，小灯泡立即熄灭。"},{"type":"note","title":"模型与思路","text":"线圈在磁场中转动时，它的两条边不断做切割磁感线运动，闭合回路中产生感应电流；摇得越快，切割磁感线的速度越大，感应电流越大，灯泡越亮。"},{"type":"list","title":"解答步骤","items":["手摇使线圈在磁场中转动，线圈的两条边做切割磁感线运动，回路中产生感应电流。","电流通过小灯泡，灯泡发光——这一过程把机械能转化为电能，电能又转化为光能和内能。","加快摇动，导体切割磁感线的速度变大，感应电流变大，灯泡变亮。","停止摇动，线圈不再切割磁感线，感应电流消失，灯泡立即熄灭。"]},{"type":"figure","figure":{"id":"fig-magnet-app-5","title":"手摇发电机给小灯泡供电","caption":"线圈在磁场中转动产生感应电流，小灯泡发光","view":"wide","alt":"磁体的 N 极在左、S 极在右，中间是一个可以转动的线圈；线圈两端用导线接在小灯泡上，线圈转动时回路中产生感应电流，小灯泡发光","prims":[{"t":"rect","x":2,"y":20,"w":11,"h":14,"tone":"danger","fill":true},{"t":"text","x":7.5,"y":27,"text":"N"},{"t":"rect","x":87,"y":20,"w":11,"h":14,"tone":"accent","fill":true},{"t":"text","x":92.5,"y":27,"text":"S"},{"t":"arrow","x1":14,"y1":27,"x2":28,"y2":27,"tone":"muted","label":"B"},{"t":"arrow","x1":72,"y1":27,"x2":86,"y2":27,"tone":"muted"},{"t":"rect","x":32,"y":14,"w":36,"h":26},{"t":"text","x":50,"y":27,"text":"线圈转动","size":3.4,"tone":"muted"},{"t":"line","x1":32,"y1":34,"x2":20,"y2":34},{"t":"line","x1":20,"y1":34,"x2":20,"y2":54},{"t":"line","x1":68,"y1":34,"x2":80,"y2":34},{"t":"line","x1":80,"y1":34,"x2":80,"y2":54},{"t":"line","x1":20,"y1":54,"x2":50,"y2":54},{"t":"line","x1":80,"y1":54,"x2":50,"y2":54},{"t":"bulb","x":50,"y":54,"label":"小灯泡"},{"t":"text","x":50,"y":9,"text":"线圈切割磁感线，回路中产生感应电流","size":3.2,"tone":"muted"}]}},{"type":"note","title":"结论","text":"手摇发电机靠线圈切割磁感线产生感应电流，把机械能转化为电能；摇得越快，感应电流越大。"},{"type":"h","text":"应用 · 计算交流电的周期与方向改变次数"},{"type":"note","title":"情境","text":"某交流发电机产生的电流，其频率是 50 Hz。"},{"type":"note","title":"模型与思路","text":"用频率与周期的关系式 f = 1/T 求周期；一个周期内电流方向改变两次，可以据此求 1 s 内方向改变的次数。"},{"type":"list","title":"解答步骤","items":["已知 f = 50 Hz，由 T = 1/f 得 T = 1 ÷ 50 Hz = 0.02 s。","一个周期内，线圈转过一周，电流方向改变两次。","1 s 内的周期数就是频率 50，所以 1 s 内电流方向改变的次数是 50 × 2 = 100 次。"]},{"type":"note","title":"结论","text":"这个交流电的周期是 0.02 s，1 s 内电流的方向改变 100 次——这正是我国家庭电路交流电的情况。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["把发电机的原理写成「磁场对通电导线有力的作用」，或者把电动机的原理写成「电磁感应」。","发电机的工作原理是电磁感应（磁生电，机械能转化为电能）；电动机的工作原理是通电导体在磁场中受力（电生力，电能转化为机械能）。","两者的条件、结果、能量转化方向全都相反：发电机靠「动」产生电，电动机靠「电」产生动。答题时先想清楚题目问的是哪一台机器，再写原理。"],["认为只要导体在磁场中运动，电路中就一定会产生感应电流。","必须是闭合电路的一部分导体做切割磁感线运动，才会产生感应电流。","电路断开、导体静止、导体沿磁感线方向运动、导体沿自身长度方向运动，这几种情况下电流计指针都不偏转。答题时要把「闭合」「切割磁感线」这两个限定条件写出来。"],["认为交流电只是电流的大小在变化，方向不变。","交流电的电流大小和方向都随时间做周期性变化。","把电流计接在发电机上，指针会左右来回摆动，说明电流方向在不断改变；方向不变的电流叫直流电，例如干电池供电时的电流。"]]},{"type":"table","title":"发电机与电动机（同样是「电与磁」，但因果关系和能量转化方向正好相反）","head":["比较项","发电机","电动机"],"rows":[["原理","电磁感应：闭合电路的一部分导体做切割磁感线运动产生感应电流","磁场对通电导线有力的作用：通电线圈在磁场中受力转动"],["能量转化","机械能 → 电能","电能 → 机械能"],["外部条件","必须有机械动力使线圈（导体）运动，电路要闭合","必须接通电源，线圈中有电流"],["输出的电流","交流电（线圈转动），也有直流发电机","靠外部电源供电，自身不产生电流"],["典型应用","水电站、风力发电、手摇发电机","电风扇、电动车、电梯、洗衣机"]]},{"type":"table","title":"导体在磁场中的几种运动（有没有切割磁感线，决定电路中有没有感应电流）","head":["比较项","产生感应电流","不产生感应电流"],"rows":[["运动方式","做切割磁感线运动（运动方向与磁感线方向不平行）","静止不动；沿磁感线方向运动；沿导体自身长度方向运动"],["电路状态","电路闭合，导体是电路的一部分","电路断开（开关断开、导线断开）"],["电流计的现象","指针偏转；运动越快偏转越大","指针不偏转"],["能量转化","机械能转化为电能","没有能量转化为电能"]]},{"type":"table","title":"交流电与直流电（电流方向是否随时间改变）","head":["比较项","交流电","直流电"],"rows":[["方向","大小和方向都随时间做周期性变化","方向不随时间改变"],["来源","由发电机（线圈在磁场中转动）产生","由干电池、蓄电池提供，或由直流发电机产生"],["图像特点","电流—时间图像是周期性起伏的曲线","电流—时间图像是一条与时间轴平行的直线"],["实例","我国家庭电路中的电流（频率 50 Hz，周期 0.02 s）","干电池给小灯泡供电时的电流"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["实验探究：产生感应电流的条件","给出「导体静止、沿磁感线方向运动、切割磁感线运动、断开电路」四组操作与电流计的现象，要求归纳条件。标准答法是：闭合电路的一部分导体在磁场中做切割磁感线运动时产生感应电流，三个条件缺一不可，答题时不能漏掉「闭合」和「切割磁感线」。"],["感应电流方向的判断","给出导体运动方向、磁场方向和其中一次的电流方向，要求判断改变其中一个因素后的电流方向。口诀与受力方向一样：只改一个，电流方向相反；两个同时改，电流方向不变。作图时要标明 A、B 两端和箭头方向。"],["发电机、电动机的原理与能量转化辨析","常以「判断这台机器是电动机还是发电机、能量怎样转化、原理是什么」的方式命题，也可能给出电流—时间图像判断是交流还是直流。答题的关键是把「电生力」与「磁生电」这两条线彻底分开。"],["交流电的频率与周期","考查 f = 1/T 的计算与「一个周期电流方向改变两次」的结论，我国交流电 50 Hz、周期 0.02 s、1 s 内方向改变 100 次是常考的数字，不要与「转速」「频率的单位」混淆。"]]},{"type":"quote","text":"【探究】小明把一段导体 AB 用导线和一个灵敏电流计连成闭合回路，把导体放在磁场中（磁场垂直于纸面向里），依次做了下列操作，并把观察到的现象记录下来。\n① 让导体 AB 静止不动，电流计指针不偏转。\n② 让导体 AB 沿垂直于磁感线的方向上下运动，电流计指针偏转。\n③ 让导体 AB 沿着它自身的长度方向左右运动，电流计指针不偏转。\n④ 断开回路中一根导线的接头，再让导体 AB 上下运动，电流计指针不偏转。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）比较操作①和②，说明产生感应电流需要什么条件？（2 分）","【设问】（2）比较操作②和③，说明导体应该怎样运动才能产生感应电流？（3 分）","【设问】（3）操作④说明了什么？请完整写出产生感应电流的条件。（3 分）"]}],"questions":[{"id":"phy-magnet-5-q1","type":"choice","stem":"电磁感应现象是","answer":"B","explain":"B 正确：英国物理学家法拉第最早发现了电磁感应现象，人们据此制成了发电机。A 错：奥斯特发现的是电流的磁效应（电生磁），与电磁感应是两件事。C 错：磁场对通电导线的作用是「通电导体在磁场中受力」，与电磁感应（磁生电）因果相反。D 错：产生感应电流的条件之一是电路必须闭合，电路断开时反而不可能产生感应电流。","options":["丹麦物理学家奥斯特最早发现的","英国物理学家法拉第最早发现的","由磁场对通电导线的作用产生的","只有在电路断开时才会出现的现象"],"difficulty":1,"tags":["电磁感应","物理学史"]},{"id":"phy-magnet-5-q2","type":"choice","stem":"产生感应电流的条件是","answer":"C","explain":"C 正确：三个条件缺一不可——电路闭合、导体是电路的一部分、做切割磁感线运动。A 错：导体沿磁感线方向运动或沿自身长度方向运动时，都不产生感应电流。B 错：漏掉了「闭合电路」这个条件，电路断开时照样没有电流。D 错：磁场本身不会凭空产生电流，还必须有闭合电路和切割磁感线的运动。","options":["导体在磁场中运动","导体在磁场中做切割磁感线运动","闭合电路的一部分导体在磁场中做切割磁感线运动","只要电路中有磁场，就一定有感应电流"],"difficulty":2,"tags":["感应电流条件"]},{"id":"phy-magnet-5-q3","type":"choice","stem":"如图，导体 AB 与灵敏电流计连成闭合回路，磁场垂直于纸面向里。让导体 AB 竖直向上运动时，导体中的电流由 B 流向 A。若只把磁场方向反过来（磁场垂直于纸面向外），其他条件不变，则导体中感应电流的方向是","answer":"D","explain":"D 正确：感应电流的方向与导体运动方向、磁场方向都有关。只改变其中一个（这里是磁场方向），感应电流的方向就相反，所以改为由 A 流向 B。A 错：只改变磁场方向不可能使电流方向不变。B 错：导体仍做切割磁感线运动、电路仍闭合，一定有感应电流，只是方向变了。C 错：本题的两个因素都是清楚的，可以判断。","options":["仍然由 B 流向 A","没有感应电流","无法判断","由 A 流向 B"],"difficulty":2,"tags":["感应电流方向"],"figure":{"id":"fig-magnet-q3-5","title":"导体在磁场中运动","caption":"磁场垂直于纸面向里，导体 AB 竖直向上运动，导体中的电流由 B 流向 A","view":"wide","alt":"导体 AB 用导线与灵敏电流计连成闭合回路，磁场垂直于纸面向里（⊗）；导体 AB 上有由 B 指向 A 的电流箭头，导体旁有竖直向上的运动箭头","prims":[{"t":"circle","cx":20,"cy":13,"r":3},{"t":"line","x1":17.9,"y1":10.9,"x2":22.1,"y2":15.1},{"t":"line","x1":17.9,"y1":15.1,"x2":22.1,"y2":10.9},{"t":"circle","cx":70,"cy":13,"r":3},{"t":"line","x1":67.9,"y1":10.9,"x2":72.1,"y2":15.1},{"t":"line","x1":67.9,"y1":15.1,"x2":72.1,"y2":10.9},{"t":"circle","cx":20,"cy":40,"r":3},{"t":"line","x1":17.9,"y1":37.9,"x2":22.1,"y2":42.1},{"t":"line","x1":17.9,"y1":42.1,"x2":22.1,"y2":37.9},{"t":"circle","cx":70,"cy":40,"r":3},{"t":"line","x1":67.9,"y1":37.9,"x2":72.1,"y2":42.1},{"t":"line","x1":67.9,"y1":42.1,"x2":72.1,"y2":37.9},{"t":"line","x1":30,"y1":27,"x2":70,"y2":27,"width":0.9},{"t":"text","x":27,"y":24,"text":"A","size":3.6,"tone":"muted"},{"t":"text","x":73,"y":24,"text":"B","size":3.6,"tone":"muted"},{"t":"arrow","x1":66,"y1":27,"x2":34,"y2":27,"tone":"accent","label":"I"},{"t":"arrow","x1":78,"y1":38,"x2":78,"y2":20,"tone":"ok","label":"v","labelDx":5},{"t":"line","x1":30,"y1":27,"x2":14,"y2":27},{"t":"line","x1":14,"y1":27,"x2":14,"y2":49},{"t":"line","x1":70,"y1":27,"x2":86,"y2":27},{"t":"line","x1":86,"y1":27,"x2":86,"y2":49},{"t":"line","x1":14,"y1":49,"x2":86,"y2":49},{"t":"meter","x":50,"y":49,"kind":"A","label":"灵敏电流计"},{"t":"text","x":50,"y":59,"text":"⊗ 表示磁场垂直于纸面向里","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-5-q4","type":"choice","stem":"关于发电机，下列说法正确的是","answer":"C","explain":"C 正确：发电机利用电磁感应现象，靠线圈（导体）在磁场中做切割磁感线运动产生感应电流，把机械能转化为电能。A 错：把电能转化为机械能的是电动机。B 错：那是电动机的原理；发电机的原理是电磁感应。D 错：常见的发电机（线圈在磁场中转动）产生的是交流电，电流方向周期性改变；只有直流发电机通过换向器把交流变成直流输出。","options":["发电机是把电能转化为机械能的装置","发电机的工作原理是磁场对通电导线有力的作用","发电机是根据电磁感应现象制成的，把机械能转化为电能","发电机产生的电流方向永远不改变"],"difficulty":2,"tags":["发电机","能量转化"]},{"id":"phy-magnet-5-q5","type":"choice","stem":"关于我国家庭电路中的交流电，下列说法正确的是","answer":"A","explain":"A 正确：我国家庭电路交流电的频率为 50 Hz，由 T = 1/f 得周期 T = 0.02 s；每个周期电流方向改变两次，所以 1 s 内方向改变 100 次。B、D 错：把频率与周期弄混了，它们互为倒数，50 Hz 对应的周期是 0.02 s 而不是 50 s。C 错：交流电的大小和方向都随时间做周期性变化，方向不变的是直流电。","options":["频率是 50 Hz，周期是 0.02 s，1 s 内电流方向改变 100 次","频率是 50 Hz，周期是 50 s","电流的方向始终不变，只是大小在变化","频率是 0.02 Hz，周期是 50 s"],"difficulty":2,"tags":["交流电","频率与周期"]},{"id":"phy-magnet-5-q6","type":"fill","stem":"闭合电路的一部分导体在磁场中做____运动时，导体中就会产生感应电流，这种现象叫电磁感应现象。","answer":"切割磁感线","explain":"注意条件的完整性：电路要闭合、导体要在磁场中、运动要切割磁感线。导体静止、沿磁感线方向运动、沿导体自身长度方向运动，都不会产生感应电流。","difficulty":1,"tags":["感应电流条件"]},{"id":"phy-magnet-5-q7","type":"fill","stem":"我国家庭电路使用的交流电频率是 50 Hz，它的周期是____s。","answer":"0.02","explain":"由 T = 1/f 得 T = 1 ÷ 50 Hz = 0.02 s。每个周期内电流方向改变两次，所以 1 s 内电流方向改变 100 次。","difficulty":1,"tags":["交流电"]},{"id":"phy-magnet-5-q8","type":"short","stem":"如图，导体 AB 与灵敏电流计连成闭合回路，磁场垂直于纸面向里。让导体 AB 竖直向上运动时，导体中的电流由 B 流向 A（B 在右端、A 在左端）。请完成：① 在图中标出导体中感应电流的方向；② 若改让导体 AB 竖直向下运动，导体中感应电流的方向会怎样？请在答案图中画出，并说明理由。","answer":"① 导体中电流由 B 流向 A，在导体 AB 上画一个由 B 指向 A 的箭头（即指向左端 A）。② 导体向下运动时，感应电流的方向由 A 流向 B（在导体上画一个由 A 指向 B 的箭头）。理由：感应电流的方向与导体运动的方向有关，在磁场方向等其他条件不变时，只改变导体运动的方向，感应电流的方向就相反。","explain":"感应电流的方向由导体运动方向和磁场方向共同决定。本题中磁场方向始终垂直于纸面向里不变，所以只需按「只改变一个因素，电流方向相反」来判断：向上运动时电流由 B 流向 A，向下运动时电流就由 A 流向 B。常见错误有两个：一是把箭头画反（把「相反」当成「相同」）；二是把「感应电流」与「磁场对通电导线的作用力」混在一起，去讨论受力方向——本题的回路里没有电源，不存在通电导体受力的问题。","difficulty":3,"tags":["作图题","感应电流方向"],"rubric":["① 在导体上画出由 B 指向 A 的箭头","② 判断出电流方向相反，画出由 A 指向 B 的箭头","理由中说明感应电流方向与导体运动方向有关","说明本题中磁场方向没有改变，只改变了运动方向"],"steps":["第一步：确认已知——磁场垂直于纸面向里，导体向上运动时电流由 B 流向 A。","第二步：①在导体 AB 上画出由 B 指向 A 的箭头，标明电流方向。","第三步：②运动方向改为竖直向下，磁场方向不变，感应电流方向与原来相反，应画出由 A 指向 B 的箭头。","第四步：写清理由——感应电流的方向与导体运动方向有关，只改变运动方向，电流方向相反。"],"figure":{"id":"fig-magnet-q8-5","title":"待完成的图：标出导体中的感应电流方向","caption":"磁场垂直于纸面向里，导体 AB 竖直向上运动，导体中的电流由 B 流向 A","view":"wide","alt":"导体 AB 与灵敏电流计连成闭合回路，磁场垂直于纸面向里（⊗），导体旁有竖直向上的运动箭头；导体上还没有画出电流方向的箭头","prims":[{"t":"circle","cx":20,"cy":13,"r":3},{"t":"line","x1":17.9,"y1":10.9,"x2":22.1,"y2":15.1},{"t":"line","x1":17.9,"y1":15.1,"x2":22.1,"y2":10.9},{"t":"circle","cx":70,"cy":13,"r":3},{"t":"line","x1":67.9,"y1":10.9,"x2":72.1,"y2":15.1},{"t":"line","x1":67.9,"y1":15.1,"x2":72.1,"y2":10.9},{"t":"circle","cx":20,"cy":40,"r":3},{"t":"line","x1":17.9,"y1":37.9,"x2":22.1,"y2":42.1},{"t":"line","x1":17.9,"y1":42.1,"x2":22.1,"y2":37.9},{"t":"circle","cx":70,"cy":40,"r":3},{"t":"line","x1":67.9,"y1":37.9,"x2":72.1,"y2":42.1},{"t":"line","x1":67.9,"y1":42.1,"x2":72.1,"y2":37.9},{"t":"line","x1":30,"y1":27,"x2":70,"y2":27,"width":0.9},{"t":"text","x":27,"y":24,"text":"A","size":3.6,"tone":"muted"},{"t":"text","x":73,"y":24,"text":"B","size":3.6,"tone":"muted"},{"t":"arrow","x1":78,"y1":38,"x2":78,"y2":20,"tone":"ok","label":"v","labelDx":5},{"t":"line","x1":30,"y1":27,"x2":14,"y2":27},{"t":"line","x1":14,"y1":27,"x2":14,"y2":49},{"t":"line","x1":70,"y1":27,"x2":86,"y2":27},{"t":"line","x1":86,"y1":27,"x2":86,"y2":49},{"t":"line","x1":14,"y1":49,"x2":86,"y2":49},{"t":"meter","x":50,"y":49,"kind":"A","label":"灵敏电流计"},{"t":"text","x":50,"y":59,"text":"在导体 AB 上画出感应电流的方向","size":3.2,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q8-6","title":"答案图：向上运动时电流由 B 流向 A，向下运动时由 A 流向 B","caption":"磁场方向都没变，只改变了运动方向，所以两次的电流方向相反","view":"wide","alt":"左图：导体 AB 竖直向上运动，导体中电流由 B 指向 A；右图：导体 AB 竖直向下运动，导体中电流由 A 指向 B；两图磁场都垂直于纸面向里","prims":[{"t":"text","x":26,"y":6,"text":"向上运动","size":3.2,"tone":"muted"},{"t":"line","x1":8,"y1":22,"x2":38,"y2":22,"width":0.9},{"t":"text","x":5,"y":19,"text":"A","size":3.4,"tone":"muted"},{"t":"text","x":41,"y":19,"text":"B","size":3.4,"tone":"muted"},{"t":"arrow","x1":34,"y1":22,"x2":14,"y2":22,"tone":"accent","label":"I"},{"t":"arrow","x1":24,"y1":32,"x2":24,"y2":16,"tone":"ok","label":"v","labelDx":5},{"t":"circle","cx":14,"cy":34,"r":2.4},{"t":"text","x":26,"y":42,"text":"电流 B→A","size":3.2,"tone":"muted"},{"t":"text","x":76,"y":6,"text":"向下运动","size":3.2,"tone":"muted"},{"t":"line","x1":58,"y1":22,"x2":88,"y2":22,"width":0.9},{"t":"text","x":55,"y":19,"text":"A","size":3.4,"tone":"muted"},{"t":"text","x":91,"y":19,"text":"B","size":3.4,"tone":"muted"},{"t":"arrow","x1":64,"y1":22,"x2":84,"y2":22,"tone":"accent","label":"I"},{"t":"arrow","x1":74,"y1":16,"x2":74,"y2":32,"tone":"ok","label":"v","labelDx":5},{"t":"circle","cx":86,"cy":34,"r":2.4},{"t":"text","x":76,"y":42,"text":"电流 A→B","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"两图磁场方向相同（⊗，垂直于纸面向里）","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"只改变运动方向，感应电流方向相反","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-5-q9","type":"short","stem":"某小组探究「感应电流的方向与哪些因素有关」，器材有导体 AB、灵敏电流计、磁体和导线（连成闭合回路）。请回答：① 要探究感应电流的方向与导体运动方向是否有关，应该怎样操作、观察什么？② 要探究感应电流的方向与磁场方向是否有关，又该怎样操作？③ 如果同时改变导体运动的方向和磁场的方向，感应电流的方向会怎样变化？为什么？","answer":"① 保持磁场方向等其他条件不变，先让导体沿某一方向做切割磁感线运动（如竖直向上），记下电流计指针偏转的方向；再让导体沿相反的方向运动（竖直向下），比较两次指针偏转方向是否相反——若相反，说明感应电流的方向与导体运动方向有关。② 保持导体的运动方向不变（如始终竖直向上），把磁体的两极对调以改变磁场方向，再让导体向上运动，比较两次指针偏转方向是否相反。③ 感应电流的方向不变。因为只改变其中一个因素时电流方向都会相反，两个因素同时改变，两次「反向」正好互相抵消。","explain":"探究「与哪些因素有关」的题目，套路是：要研究谁，就让谁成为唯一的变量，其他条件都保持不变。①中要研究运动方向，就必须固定磁场方向；②中要研究磁场方向，就必须固定运动方向。观察的对象是电流计指针偏转的方向，它直接反映导体中感应电流的方向。③是这类题的高频追问：两个因素同时改变时，两次反向互相抵消，电流方向与原来相同——这与探究「磁场对通电导线的作用力方向」时的结论完全一致。","difficulty":3,"tags":["实验探究","控制变量法"],"rubric":["① 答出保持磁场方向不变，只改变导体的运动方向，观察并比较电流计指针偏转方向","② 答出保持导体运动方向不变，只改变磁场方向（对调磁体两极）","③ 答出感应电流方向不变，并说明两次反向互相抵消","三次表述中都能体现控制变量的思想（只改变一个因素）"],"steps":["① 写清操作：磁场不变 → 导体正向运动记录指针方向 → 导体反向运动再记录 → 比较两次。","② 写清操作：运动方向不变 → 对调磁体两极改变磁场方向 → 再让导体按原方向运动 → 比较两次。","③ 先说明两个因素同时改变，再说两次反向互相抵消，结论是电流方向不变。"]},{"id":"phy-magnet-5-q10","type":"short","stem":"某交流发电机产生的电流频率是 50 Hz。求：① 这个交流电的周期；② 线圈每转过一周，电流的方向改变几次？③ 1 s 内电流的方向改变多少次？","answer":"① 由 T = 1/f 得 T = 1 ÷ 50 Hz = 0.02 s。② 线圈每转过一周（即经过一个周期），电流的方向改变两次。③ 1 s 内包含 50 个周期，每个周期方向改变两次，所以 1 s 内电流的方向改变 50 × 2 = 100 次。","explain":"本题把频率、周期和「方向改变次数」三个量串在一起。①频率与周期互为倒数。②线圈在磁场中转动时，每经过一次与磁场方向垂直的位置，电流方向就改变一次，一个周期内经过两次，所以方向改变两次。③频率 50 Hz 表示 1 s 内有 50 个周期，因此方向改变 100 次。常见的错误是把「方向改变次数」直接当成周期数（答 50 次），或者把周期算成 50 s。","difficulty":2,"tags":["交流电","频率与周期"],"rubric":["① 写出 T = 1/f 并算出 0.02 s（带单位）","② 答出每转一周（每个周期）电流方向改变两次","③ 算出 1 s 内改变 100 次"],"steps":["① 已知 f = 50 Hz；由 T = 1/f 得 T = 1 ÷ 50 Hz = 0.02 s。","② 一个周期内线圈转过一周，电流方向改变 2 次。","③ 1 s 内周期数 = f = 50；方向改变次数 = 50 × 2 = 100 次。"]},{"id":"phy-magnet-5-m1-q1","type":"short","stem":"（1）比较操作①和②，说明产生感应电流需要什么条件？（2 分）","answer":"比较①和②可知：导体必须在磁场中运动（与磁场发生相对运动）才能产生感应电流；导体静止不动时，即使处在磁场中也没有感应电流。","explain":"","tags":["电磁感应","实验探究"],"rubric":["答出「导体要运动」或「要与磁场发生相对运动」","答出静止时没有感应电流"]},{"id":"phy-magnet-5-m1-q2","type":"short","stem":"（2）比较操作②和③，说明导体应该怎样运动才能产生感应电流？（3 分）","answer":"导体必须做切割磁感线运动。②中导体沿垂直于磁感线的方向上下运动，运动方向与磁感线方向不平行，切割了磁感线，产生了感应电流；③中导体沿着自身的长度方向左右运动，没有切割磁感线，所以没有感应电流。","explain":"","tags":["切割磁感线","实验探究"],"rubric":["答出「切割磁感线」（或运动方向与磁感线方向不平行）","说明②中导体上下运动切割了磁感线","说明③中导体沿自身长度方向运动没有切割磁感线"]},{"id":"phy-magnet-5-m1-q3","type":"short","stem":"（3）操作④说明了什么？请完整写出产生感应电流的条件。（3 分）","answer":"操作④说明产生感应电流还要求电路是闭合的：电路断开时，即使导体做切割磁感线运动也没有感应电流。产生感应电流的条件是：闭合电路的一部分导体在磁场中做切割磁感线运动。","explain":"","tags":["感应电流条件"],"rubric":["答出④说明电路必须是闭合的","写出完整条件：闭合电路的「一部分导体」","写出完整条件：在磁场中做「切割磁感线」运动"]}]},{"id":"phy-magnet-6","title":"信息的传递·电磁波","subtitle":"人教版九年级 · 第 21 章 信息的传递 · 9b","grade":"9b","tags":["人教版九年级 · 第 21 章 信息的传递"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 21 章 信息的传递 · 9b"},{"type":"note","title":"问题切入","text":"打电话、看电视、用手机上网，声音和图像是怎样从千里之外传到我们面前的？为什么飞船和地面之间能通信，而两个人隔着真空却喊不应？"},{"type":"note","title":"一句话抓住关键","text":"电磁波可以传递信息，它不需要介质，在真空中也能传播，真空中的传播速度 c = 3×10⁸ m/s（与光速相同）；波速、波长、频率的关系是 c = λf，波速一定时波长与频率成反比；广播、电视、移动通信都靠电磁波，光也是一种电磁波，光纤通信就靠光在纤维中传播。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"手机没有线也能通话，是因为信息搭上了「电磁波」这趟不需要轨道的列车。","walk":["电磁波不需要介质，真空中也能传播，速度 c = 3×10⁸ m/s。","c = λf：波速一定时，波长与频率成反比。","电磁波谱包括无线电波、红外线、可见光、紫外线、X 射线、γ 射线。"],"try":"把手机放进金属盒或铁柜再拨打，观察信号变弱——金属能屏蔽电磁波。","use":["算波长：λ = c/f，频率单位要用 Hz。","广播、电视、手机、卫星通信都靠电磁波传信息。"]},{"type":"h","text":"先看现象：信息是怎样「飞」过去的"},{"type":"p","text":"最早的固定电话把声音变成电流，电流沿着导线传到对方，再把电流还原成声音——这离不开导线。可是海上航行的船、太空中的飞船没有导线相连，信息又怎么传过去？答案是用电磁波。英国物理学家麦克斯韦最早从理论上预言了电磁波的存在，德国物理学家赫兹用实验证实了它。今天，无线电广播、电视、手机、卫星通信都靠电磁波传递信息。"},{"type":"figure","figure":{"id":"fig-magnet-emwave-1","title":"电磁波与波长","caption":"相邻两个波峰之间的距离叫一个波长；电磁波沿传播方向前进，可以携带信息","view":"wide","alt":"一条沿水平方向传播的正弦形状的电磁波，相邻两个波峰之间用双向箭头标出一个波长 λ；下方有一个指向右方的箭头表示波的传播方向","prims":[{"t":"text","x":50,"y":8,"text":"电磁波的波长 λ：相邻两个波峰之间的距离","size":3.4,"tone":"muted"},{"t":"curve","points":[[6,30],[17,20],[28,30],[39,40],[50,30],[61,20],[72,30],[83,40],[94,30]],"tone":"accent","width":0.8},{"t":"arrow","x1":17,"y1":16,"x2":61,"y2":16,"both":true,"tone":"muted","label":"波长 λ"},{"t":"arrow","x1":8,"y1":50,"x2":92,"y2":50,"tone":"ok","label":"传播方向"},{"t":"text","x":50,"y":59,"text":"电磁波不需要介质，在真空中也能传播","size":3.2,"tone":"muted"}]}},{"type":"h","text":"抓住物理量：波长、频率与波速"},{"type":"p","text":"描述电磁波要用三个物理量：波长 λ 是相邻两个波峰（或相邻两个波谷）之间的距离，单位是米；频率 f 是 1 s 内波变化的次数，单位是赫兹（Hz）；波速 c 是波传播的快慢，单位是米每秒。电磁波在真空中的传播速度是 3×10⁸ m/s，与光的传播速度相同——因为光本身就是一种电磁波。要特别注意：所有电磁波在真空中的传播速度都相同，跟它们的频率、波长都没有关系。"},{"type":"figure","figure":{"id":"fig-magnet-wavelength-1","title":"波速相同时，波长与频率成反比","caption":"上面一列波波长较长（频率较低），下面一列波波长较短（频率较高），但两者在真空中的波速相同","view":"wide","alt":"两列波速相同的电磁波：上面一列起伏平缓、波长较大，用双向箭头标出一个波长；下面一列起伏密集、波长较小，同样标出一个波长","prims":[{"t":"curve","points":[[6,16],[17,8],[28,16],[39,24],[50,16],[61,8],[72,16],[83,24],[94,16]],"tone":"accent","width":0.8},{"t":"arrow","x1":17,"y1":4,"x2":61,"y2":4,"both":true,"tone":"muted","label":"λ 较大"},{"t":"text","x":50,"y":31,"text":"在真空中波速都是 c = 3×10⁸ m/s","size":3.2,"tone":"muted"},{"t":"curve","points":[[6,46],[11.5,38],[17,46],[22.5,54],[28,46],[33.5,38],[39,46],[44.5,54],[50,46],[55.5,38],[61,46],[66.5,54],[72,46],[77.5,38],[83,46],[88.5,54],[94,46]],"tone":"accent","width":0.8},{"t":"arrow","x1":11.5,"y1":60,"x2":33.5,"y2":60,"both":true,"tone":"muted","label":"λ 较小"}]}},{"type":"note","title":"","text":"波长和频率是「一对」：波速一定时，一个变大，另一个必然变小。"},{"type":"h","text":"建立关系：c = λf 怎么用"},{"type":"p","text":"波速、波长、频率之间的关系是：波速 = 波长 × 频率，公式写成 v = λ f；对电磁波，真空中的波速是一个定值，所以常写成 c = λ f。由这条关系可以推出两个变形用法：λ = c/f 用来求波长，f = c/λ 用来求频率。因为 c 是定值，波长与频率成反比：频率高的电磁波波长一定短。"},{"type":"figure","figure":{"id":"fig-magnet-lambda-f-1","title":"真空中波长与频率的关系图像","caption":"横轴是频率、纵轴是波长，曲线是双曲线的一支：频率越高，波长越短，两者的乘积始终等于 3×10⁸ m/s","view":"square","alt":"一个坐标图像，横轴表示频率（单位 10⁸ Hz）、纵轴表示波长（单位 m）；曲线从左上向右下弯曲下降，表示频率增大时波长减小","prims":[{"t":"text","x":50,"y":8,"text":"在真空中 c = 3×10⁸ m/s 是定值，所以 λ 与 f 成反比","size":3.2,"tone":"muted"},{"t":"axis","x":16,"y":84,"w":70,"h":64,"xLabel":"f/(10⁸ Hz)","yLabel":"λ/m","origin":true,"xTicks":[{"at":0.25,"label":"1"},{"at":0.5,"label":"2"},{"at":0.75,"label":"3"}],"yTicks":[{"at":0.25,"label":"3"},{"at":0.5,"label":"6"},{"at":0.75,"label":"9"}]},{"t":"curve","points":[[23,44],[26.5,57.3],[30,64],[33.5,68],[42.25,73.3],[51,76],[68.5,78.7],[86,80]],"tone":"accent","width":0.8},{"t":"text","x":62,"y":30,"text":"λ = c/f","size":3.8,"tone":"muted"}]}},{"type":"h","text":"学会应用：广播、电视与移动通信"},{"type":"p","text":"电磁波的频率范围很宽，人们用不同的频段传递不同的信息：无线电广播用中波、短波，电视和调频广播使用频率较高的微波频段，手机通信也使用微波。手机既是无线电发射台，又是无线电接收台：它把声音变成电信号，再变成电磁波发射出去，通过基站转发，对方的手机接收到电磁波后再还原成声音。微波大致沿直线传播，不容易绕过障碍物，所以远距离微波通信要靠中继站一站一站转发，或者用同步通信卫星转发。"},{"type":"figure","figure":{"id":"fig-magnet-mobile-1","title":"手机通信靠电磁波","caption":"手机把声音变成电磁波发射出去，基站接收后再转发给对方","view":"wide","alt":"方框图：手机向基站发射电磁波，基站再向另一部手机发射电磁波，从而实现通话；电磁波不需要介质，在真空中也能传播","prims":[{"t":"rect","x":4,"y":24,"w":20,"h":13,"tone":"main","fill":true,"label":"手机"},{"t":"arrow","x1":24,"y1":30.5,"x2":40,"y2":30.5,"tone":"accent","label":"电磁波"},{"t":"rect","x":40,"y":24,"w":20,"h":13,"tone":"accent","label":"基站"},{"t":"arrow","x1":60,"y1":30.5,"x2":76,"y2":30.5,"tone":"accent","label":"电磁波"},{"t":"rect","x":76,"y":24,"w":20,"h":13,"tone":"main","fill":true,"label":"对方手机"},{"t":"text","x":50,"y":12,"text":"手机既能发射电磁波，也能接收电磁波","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"电磁波不需要介质，在真空中也能传播","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"所以飞船、卫星与地面之间也靠电磁波通信","size":3.2,"tone":"muted"}]}},{"type":"h","text":"换个角度：光也是一种电磁波"},{"type":"p","text":"光（可见光、激光、红外线、紫外线）都是电磁波，只是频率（波长）不同。把激光送进光导纤维，光会在纤维的内壁不断反射，沿着纤维传到远方，这就是光纤通信：它的容量大、损耗小，是现代通信网的重要基础。除此之外，微波炉用微波使食物中的水分子剧烈运动而发热，电视遥控器用红外线传递控制信号，雷达用电磁波探测目标——它们用的都是同一个「家族」的电磁波。"},{"type":"figure","figure":{"id":"fig-magnet-fiber-1","title":"光纤通信","caption":"激光在光导纤维的内壁不断反射，沿着纤维传到远方","view":"wide","alt":"两根平行线表示光导纤维的管壁，管内有折线形的光线在上下管壁之间不断反射着向右前方传播，末端有表示传播方向的箭头","prims":[{"t":"line","x1":6,"y1":20,"x2":94,"y2":20,"width":0.7},{"t":"line","x1":6,"y1":40,"x2":94,"y2":40,"width":0.7},{"t":"curve","points":[[6,30],[16,21],[30,39],[44,21],[58,39],[72,21],[86,39],[94,30]],"tone":"accent","arrow":true},{"t":"text","x":50,"y":12,"text":"激光在光导纤维中不断反射前进","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":50,"text":"光也是一种电磁波，光纤通信容量大、损耗小","size":3.2,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["波速、波长与频率的关系","c = λ f","c：波速（m/s）；λ：波长（m）；f：频率（Hz） · 适用于一切波。对电磁波，c 取真空中的速度 3×10⁸ m/s（空气中可近似取这个值）。变形用法：λ = c/f 求波长，f = c/λ 求频率。因为 c 一定，波长与频率成反比。计算前必须统一单位：1 MHz = 10⁶ Hz，1 kHz = 10³ Hz。声波也用这条关系，但声波的波速通常用 v 表示，且要按当时的介质与温度取值（15 ℃ 的空气中约 340 m/s）。"],["电磁波在真空中的传播速度","c = 3×10⁸ m/s","所有电磁波在真空中的传播速度都相同，与频率、波长无关；光也是一种电磁波，所以光速就是这个数值。它常被用来估算距离（如雷达测距：距离 = 速度 × 时间 ÷ 2），也是「电磁波可以在真空中传播」这一结论的量化依据。"]]},{"type":"h","text":"应用 · 由频率求波长：调频广播的电磁波有多长"},{"type":"note","title":"情境","text":"某调频广播电台发射的电磁波频率是 100 MHz（1 MHz = 10⁶ Hz）。求这列电磁波在空气中的波长。"},{"type":"note","title":"模型与思路","text":"电磁波在空气中的传播速度与真空中接近，取 c = 3×10⁸ m/s；由 c = λf 得 λ = c/f。计算前先统一单位，把频率换成赫兹。"},{"type":"list","title":"解答步骤","items":["单位换算：f = 100 MHz = 100 × 10⁶ Hz = 1×10⁸ Hz。","取电磁波在空气中的传播速度 c = 3×10⁸ m/s。","由 c = λf 变形得 λ = c/f = 3×10⁸ m/s ÷ 1×10⁸ Hz = 3 m。"]},{"type":"note","title":"结论","text":"这列电磁波的波长是 3 m。调频广播的频率在 10⁸ Hz 这个量级，波长在几米左右，正好可以用尺寸相当的发射天线有效地发射和接收。"},{"type":"h","text":"应用 · 手机通话时，声音是怎样传到对方的"},{"type":"note","title":"情境","text":"甲、乙两人相距很远，用手机通话。甲对着手机说话，乙很快就听到了。"},{"type":"note","title":"模型与思路","text":"手机把声信号转成电信号，再把电信号加载到电磁波上发射出去；基站接收后转发，对方手机接收电磁波，再把它还原成声音。整个过程传递信息的是电磁波，不是声波。"},{"type":"list","title":"解答步骤","items":["甲的声带振动产生声波，声波使手机的送话器振动，把声信号转换成电信号。","手机把电信号加载到高频电磁波上发射出去。","基站接收这列电磁波，再把它转发出去（远距离时还要靠中继站或通信卫星）。","乙的手机接收到电磁波，把电信号还原成声信号，通过扬声器发出声音。"]},{"type":"figure","figure":{"id":"fig-magnet-app-6","title":"手机通话中信息的传递路径","caption":"声信号 → 电信号 → 电磁波 → 电信号 → 声信号","view":"wide","alt":"方框图：甲说话产生声波，手机把声信号转换为电信号并发射电磁波，基站接收转发，乙的手机接收电磁波并还原成声音","prims":[{"t":"rect","x":2,"y":24,"w":16,"h":13,"tone":"muted","label":"声波"},{"t":"arrow","x1":18,"y1":30.5,"x2":28,"y2":30.5,"tone":"muted"},{"t":"rect","x":28,"y":24,"w":18,"h":13,"tone":"main","fill":true,"label":"甲的手机"},{"t":"arrow","x1":46,"y1":30.5,"x2":58,"y2":30.5,"tone":"accent","label":"电磁波"},{"t":"rect","x":58,"y":24,"w":16,"h":13,"tone":"accent","label":"基站"},{"t":"arrow","x1":74,"y1":30.5,"x2":82,"y2":30.5,"tone":"accent"},{"t":"rect","x":82,"y":24,"w":16,"h":13,"tone":"main","fill":true,"label":"乙的手机"},{"t":"text","x":50,"y":12,"text":"远距离传递信息的是电磁波，不是声波","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"声信号 → 电信号 → 电磁波 → 电信号 → 声信号","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"微波沿直线传播，远距离要靠中继站或通信卫星转发","size":3,"tone":"muted"}]}},{"type":"note","title":"结论","text":"声音只负责「手机到手」这一段，远距离传递信息靠的是电磁波；声波不能在真空中传播，而电磁波可以。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为电磁波在真空中的传播速度与频率有关，频率越高传播得越快。","所有电磁波在真空中的传播速度都相同，都是 3×10⁸ m/s，与频率、波长无关。","正因为波速是一个定值，由 c = λf 才能推出「波长与频率成反比」：频率高的电磁波波长必然短，但速度一样。"],["认为声音也是电磁波，或者认为手机通话是声波直接传到对方耳朵里。","声音是声波（机械波），不是电磁波，也不能在真空中传播；手机把声信号转换成电信号、再转换成电磁波发射出去。","电磁波与声波最本质的区别是「需不需要介质」：电磁波不需要介质，声波必须靠介质传播。所以飞船之间、飞船与地面之间只能用电磁波通信。"],["认为波长越长，频率越高。","波速一定时，波长与频率成反比：波长越长，频率越低。","由 c = λf 可知，两者的乘积始终等于波速这个定值，一个变大另一个必然变小。判断这类问题只要盯住「乘积不变」。"]]},{"type":"table","title":"电磁波与声波（能不能在真空中传播，是两者最本质的区别）","head":["比较项","电磁波","声波"],"rows":[["是否需要介质","不需要，在真空中也能传播","需要介质，真空不能传声"],["传播速度","真空中 3×10⁸ m/s（与光速相同）","15 ℃ 的空气中约 340 m/s"],["本质","电磁波，包括无线电波、微波、红外线、可见光、紫外线等","机械波，由声源振动引起、靠介质传播"],["传递信息","广播、电视、手机、卫星通信都靠它","两人交谈、回声定位靠它"],["速度与波长的关系式","c = λf","v = λf（v 取声速）"]]},{"type":"table","title":"不同频段的电磁波（同属电磁波，频段不同则用途不同）","head":["比较项","频率较低、波长较长的电磁波","频率较高、波长较短的电磁波"],"rows":[["典型代表","无线电波、微波","红外线、可见光、紫外线"],["典型应用","无线电广播、电视、移动通信、卫星通信、微波炉","遥控器（红外线）、光纤通信（激光）、杀菌消毒（紫外线）"],["波长量级","从几毫米到几千米","可见光的波长大约在 400 nm 到 760 nm 之间"],["共同点","都是电磁波，真空中传播速度相同，都能传递信息或能量","都是电磁波，真空中传播速度相同，都能传递信息或能量"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["用 c = λf 做计算","已知频率求波长或已知波长求频率，是这一章最常见的计算。两个易错点：一是单位换算（1 MHz = 10⁶ Hz）；二是公式变形写错（求波长要用 λ = c/f，不能写成 c×f）。"],["电磁波与声波的辨析","常以「为什么航天员在太空要靠无线电通话」「为什么真空不能传声却能传电磁波」为情境，考查两者是否需要介质、速度量级、本质差别。答题时要把「电磁波不需要介质」这一关键句写出来。"],["现代通信方式的理解","以手机、广播、电视、光纤、卫星为材料，考查「信息是怎样传过去的」：谁发射、谁接收、用什么传递（电磁波）。答「靠声波传给对方」或「靠导线传到很远的地方」都是错的。"],["波形图读数与估算","给出电磁波的波形图，要求读出一个波长，再结合 c = 3×10⁸ m/s 求频率或周期。读数时要看清横轴表示的是距离还是时间：横轴是距离时读出的相邻波峰间距离是波长，横轴是时间时读出的是周期。"]]},{"type":"quote","text":"【材料】电磁波是一个大家族，不同频段的电磁波用途不同。无线电广播使用的电磁波频率较低、波长较长；微波的频率较高、波长较短，可以用来传递电视信号和手机信号。微波大致沿直线传播，不容易绕过障碍物，而地球表面是弯曲的，所以远距离微波通信要靠中继站一站一站地转发，或者用同步通信卫星转发。\n光也是一种电磁波。把激光送进光导纤维，光就在纤维内壁不断反射着前进，能把信息送到很远的地方，而且损耗小、容量大，是现代通信网的重要基础。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）某调频广播电台发射的电磁波频率是 100 MHz，求它在空气中的波长（取电磁波在空气中的速度等于真空中的速度 3×10⁸ m/s）。（3 分）","【设问】（2）结合材料说明，微波通信为什么要建中继站或者使用同步通信卫星？（3 分）","【设问】（3）光纤通信中的「光」是不是电磁波？说明它在光导纤维中是怎样传播的。（3 分）"]}],"questions":[{"id":"phy-magnet-6-q1","type":"choice","stem":"关于电磁波，下列说法正确的是","answer":"B","explain":"B 正确：电磁波不需要介质，在真空中也能传播，真空中的速度是 3×10⁸ m/s；光本身就是一种电磁波，所以两者速度相同。A 错：不需要介质正是电磁波的重要特点，飞船与地面通信就靠它。C 错：所有电磁波在真空中的速度都相同，与频率无关。D 错：光是电磁波，但声音是声波（机械波），需要介质，真空不能传声。","options":["电磁波只能在介质中传播，在真空中不能传播","电磁波在真空中的传播速度是 3×10⁸ m/s，与光的传播速度相同","电磁波在真空中的传播速度与频率有关，频率越高速度越大","声音和光都是电磁波"],"difficulty":1,"tags":["电磁波","传播速度"]},{"id":"phy-magnet-6-q2","type":"choice","stem":"由 c = λf 可知，对于在真空中传播的电磁波","answer":"B","explain":"B 正确：c = λf 中 c 是真空中的波速，是一个定值，所以波长与频率的乘积不变。A、C 错：波速一定时波长与频率成反比，波长越长频率越低，不是成正比。D 错：真空中所有电磁波的传播速度都相同，与频率无关。","options":["波长越长，频率越高","波长与频率的乘积是一个定值","波长与频率成正比","频率越高，传播速度越大"],"difficulty":2,"tags":["c=λf"]},{"id":"phy-magnet-6-q3","type":"choice","stem":"如图是某电磁波在真空中的波形图，从图中读出相邻两个波峰之间的距离（波长）为 2 m。已知电磁波在真空中的传播速度是 3×10⁸ m/s，这列电磁波的频率是","answer":"A","explain":"A 正确：由 c = λf 得 f = c/λ = 3×10⁸ m/s ÷ 2 m = 1.5×10⁸ Hz。B 错：这是把公式写成 f = cλ（相乘）得到的结果。C 错：这是把 3×10⁸ ÷ 2 算成了 1.5×10⁶，指数出错。D 错：3×10⁸ Hz 是把波速直接当成了频率。","options":["1.5×10⁸ Hz","6×10⁸ Hz","1.5×10⁶ Hz","3×10⁸ Hz"],"difficulty":2,"tags":["c=λf","波形图读数"],"figure":{"id":"fig-magnet-q3-6","title":"某电磁波的波形图","caption":"横轴表示位置，相邻两个波峰之间的距离就是波长，图中已标出为 2 m","view":"wide","alt":"一条沿水平方向传播的电磁波波形，横轴表示位置；相邻两个波峰之间用双向箭头标出，标注为 2 m","prims":[{"t":"axis","x":10,"y":30,"w":84,"h":22,"xLabel":"x/m","yLabel":"E","origin":true},{"t":"curve","points":[[10,30],[20.5,22],[31,30],[41.5,38],[52,30],[62.5,22],[73,30],[83.5,38],[94,30]],"tone":"accent","width":0.8},{"t":"arrow","x1":20.5,"y1":52,"x2":62.5,"y2":52,"both":true,"tone":"muted","label":"波长 2 m"},{"t":"text","x":50,"y":5,"text":"电磁波沿水平方向传播","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-6-q4","type":"choice","stem":"关于广播、电视和移动通信，下列说法正确的是","answer":"C","explain":"C 正确：手机既能发射电磁波（把声音转换成的电信号加载到电磁波上发出去），又能接收电磁波（把对方传来的电磁波还原成声音），它通过基站与通信网联系。A 错：如果只能接收，通话就无法进行，手机必须能双向收发。B 错：电视信号可以用电磁波（微波）传送，也可以通过有线网络传送，说「只能靠导线」是错的。D 错：广播电台发射的是电磁波，不是声波；收音机接收电磁波后把它还原成声音。","options":["手机只能接收电磁波，不能发射电磁波","电视信号只能靠导线送到各家各户，无法用电磁波传送","手机既是无线电发射台又是无线电接收台，它靠电磁波与基站联系","广播电台发射的是声波，收音机直接接收声波"],"difficulty":2,"tags":["移动通信"]},{"id":"phy-magnet-6-q5","type":"choice","stem":"把声波与电磁波相比较，下列说法正确的是","answer":"D","explain":"D 正确：这是两者最本质的区别——电磁波不需要介质，声波是机械波，必须依靠介质传播，真空不能传声。A 错：声波不能在真空中传播，所以航天员出舱要靠无线电通话。B 错：声波在空气中的速度约 340 m/s，电磁波是 3×10⁸ m/s，相差上百万倍。C 错：把两者的性质说反了。","options":["两者都能在真空中传播","两者在空气中的传播速度差不多","声波不需要介质，电磁波需要介质","电磁波不需要介质、在真空中也能传播；声波必须依靠介质，真空不能传声"],"difficulty":2,"tags":["电磁波与声波"]},{"id":"phy-magnet-6-q6","type":"fill","stem":"电磁波在真空中的传播速度是____m/s。","answer":"3×10⁸|3×10⁸|300000000","explain":"电磁波在真空中的传播速度 c = 3×10⁸ m/s，与光在真空中的传播速度相同——光也是一种电磁波。所有电磁波在真空中的速度都与频率无关。","difficulty":1,"tags":["传播速度"]},{"id":"phy-magnet-6-q7","type":"fill","stem":"某广播电台发射的电磁波频率是 1×10⁸ Hz，它在真空中的波长是____m。","answer":"3","explain":"由 c = λf 得 λ = c/f = 3×10⁸ m/s ÷ 1×10⁸ Hz = 3 m。这类计算先看单位是否统一（频率用 Hz、速度用 m/s，波长就是 m）。","difficulty":1,"tags":["c=λf"]},{"id":"phy-magnet-6-q8","type":"short","stem":"某中波广播电台发射的电磁波波长是 300 m，电磁波在空气中的传播速度取 3×10⁸ m/s。求：① 这列电磁波的频率；② 某电视台发射的电磁波频率是 1.5×10⁸ Hz，它的波长是多少？","answer":"① 由 c = λf 得 f = c/λ = 3×10⁸ m/s ÷ 300 m = 1×10⁶ Hz = 1000 kHz。② 由 c = λf 得 λ = c/f = 3×10⁸ m/s ÷ 1.5×10⁸ Hz = 2 m。","explain":"两道小题考的是同一条公式的两种变形：已知波长求频率用 f = c/λ，已知频率求波长用 λ = c/f。解题步骤都是「统一单位 → 选对变形 → 代入计算 → 写单位」。常见错误有：把变形写反（用 c×λ 求频率）；忘记把 MHz、kHz 换成 Hz；以及算完不写单位。","difficulty":2,"tags":["c=λf","计算题"],"rubric":["① 写出 f = c/λ 并算出 1×10⁶ Hz","① 结果注明单位（也可写成 1000 kHz）","② 写出 λ = c/f 并算出 2 m"],"steps":["① 已知 λ = 300 m、c = 3×10⁸ m/s；由 c = λf 变形得 f = c/λ = 3×10⁸ m/s ÷ 300 m = 1×10⁶ Hz（即 1000 kHz）。","② 已知 f = 1.5×10⁸ Hz；由 λ = c/f = 3×10⁸ m/s ÷ 1.5×10⁸ Hz = 2 m。"]},{"id":"phy-magnet-6-q9","type":"short","stem":"如图是某电磁波在真空中的波形图（横轴表示位置）。请完成：① 在图上用双向箭头标出一个波长；② 已知这列电磁波的频率是 1×10⁸ Hz，求它的波长；③ 如果把电磁波换成频率更高的，在同一段距离内它的波形会有什么变化？为什么？","answer":"① 在波形图上取相邻两个波峰（或相邻两个波谷），用双向箭头把它们之间的距离标出来，这段距离就是一个波长（见答案图）。② 由 c = λf 得 λ = c/f = 3×10⁸ m/s ÷ 1×10⁸ Hz = 3 m。③ 频率更高的电磁波在同一段距离内波形会更密，也就是波峰（波谷）的个数更多，波长更短。因为电磁波在真空中的波速是定值 3×10⁸ m/s，由 λ = c/f 可知波长与频率成反比，频率越高波长越短。","explain":"本题把「读图」与「计算」合在一起。①标波长必须取相邻的两个波峰（或两个波谷），取一个波峰到一个波谷是半个波长，这是最常见的错误。②用 λ = c/f 计算，注意频率的单位已经是 Hz，可以直接代入。③这是对 c = λf 的反向理解：波速不变时，频率越高波长越短，所以同样的距离内包含的完整波更多，波形看起来更「密」。","difficulty":3,"tags":["作图题","c=λf"],"rubric":["① 在相邻两个波峰（或相邻两个波谷）之间画出双向箭头","② 写出 λ = c/f 并算出 3 m（带单位）","③ 答出波形变密（相同距离内波峰个数增多），波长变短","③ 说明理由：真空中波速一定，波长与频率成反比"],"steps":["① 找到相邻的两个波峰，在它们之间画双向箭头，标注 λ。","② 由 c = λf 得 λ = c/f = 3×10⁸ m/s ÷ 1×10⁸ Hz = 3 m。","③ 判断波形变化：频率升高 → 波长变短 → 相同距离内波峰更多、波形更密。","④ 说明依据：真空中电磁波的波速是定值，由 λ = c/f 可知波长与频率成反比。"],"figure":{"id":"fig-magnet-q9-7","title":"待完成的图：标出一个波长","caption":"横轴表示位置，电磁波在真空中传播，频率是 1×10⁸ Hz","view":"wide","alt":"一个坐标图，横轴表示位置、纵轴表示电场强度，图中画有一条正弦形状的电磁波波形；图上还没有标出波长","prims":[{"t":"axis","x":10,"y":30,"w":84,"h":22,"xLabel":"x/m","yLabel":"E","origin":true},{"t":"curve","points":[[10,30],[20.5,22],[31,30],[41.5,38],[52,30],[62.5,22],[73,30],[83.5,38],[94,30]],"tone":"accent","width":0.8},{"t":"text","x":50,"y":5,"text":"请在图上标出一个波长","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"横轴表示位置，波峰到相邻波峰的距离才是波长","size":3,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q9-8","title":"答案图：标出波长，并与频率更高的电磁波比较","caption":"上面是原来的电磁波（λ = 3 m），下面是频率更高的电磁波：波长更短、波形更密","view":"wide","alt":"上图是原来的电磁波，相邻两个波峰之间用双向箭头标出波长；下图是频率更高的电磁波，波形更密、波长更短，也用双向箭头标出了它更小的波长","prims":[{"t":"arrow","x1":20.5,"y1":4,"x2":62.5,"y2":4,"both":true,"tone":"muted","label":"λ = 3 m"},{"t":"curve","points":[[10,18],[20.5,11],[31,18],[41.5,25],[52,18],[62.5,11],[73,18],[83.5,25],[94,18]],"tone":"accent","width":0.8},{"t":"text","x":52,"y":32,"text":"频率更高的电磁波：波长更短、波形更密","size":3.2,"tone":"muted"},{"t":"curve","points":[[10,44],[15.25,38],[20.5,44],[25.75,50],[31,44],[36.25,38],[41.5,44],[46.75,50],[52,44],[57.25,38],[62.5,44],[67.75,50],[73,44],[78.25,38],[83.5,44],[88.75,50],[94,44]],"tone":"accent","width":0.8},{"t":"arrow","x1":15.25,"y1":58,"x2":36.25,"y2":58,"both":true,"tone":"muted","label":"波长更短"}]}},{"id":"phy-magnet-6-q10","type":"short","stem":"某小组想探究「电磁波能不能在真空中传播」。他们把一个玻璃罩罩住一部手机，用抽气机把罩内的空气逐渐抽出，然后用另一部手机拨打罩内手机的号码，观察到罩内手机的屏幕亮起、能够接通。请回答：① 这个现象说明了什么？② 实验中为什么要抽去罩内的空气？③ 如果把手机换成一只正在响铃的闹钟，把罩内空气抽走后，我们还能听到铃声吗？为什么？","answer":"① 说明电磁波可以在真空中传播：罩内空气被抽走后，手机仍然能接收和发射电磁波，所以屏幕亮起、电话能够接通。② 抽去空气是为了排除空气（介质）的影响，造成近似真空的环境，从而检验电磁波在没有介质的情况下能不能传播。③ 听不到铃声（铃声越来越弱直到听不见）。因为铃声是声波，声波是机械波，必须依靠介质（如空气）传播，真空不能传声。","explain":"本实验用「抽气」造出真空，再用同一部手机检验它能不能接收电磁波，把「电磁波是否需要介质」这个看不见的问题变成了看得见的现象。①罩内空气被抽走后手机照样能接通，说明电磁波不需要空气这样的介质也能传播。②如果不抽气，罩内仍有空气，就无法判断电磁波是「靠空气传的」还是「不需要介质」。③把手机换成闹钟，铃声是声波：声波是机械波，必须靠介质传播，所以抽走空气后铃声越来越弱直到听不见——同一个真空环境，对电磁波没有影响，对声波却是致命的，这正是两者最本质的差别。","difficulty":3,"tags":["实验探究","电磁波与声波"],"rubric":["① 答出电磁波可以在真空中传播","② 答出抽气的目的是形成真空环境、排除空气（介质）的影响","③ 答出听不到铃声（或铃声变弱直到听不见）","③ 答出声波需要介质，真空不能传声"],"steps":["① 描述现象并得出结论：抽气后仍能接通 → 电磁波可以在真空中传播。","② 说明抽气的目的：造成真空，排除空气介质的影响，使实验具有说服力。","③ 判断并解释：铃声是声波，需要介质，真空不能传声，所以听不到铃声。"],"figure":{"id":"fig-magnet-q10-9","title":"探究电磁波能否在真空中传播","caption":"把手机放在玻璃罩内，抽去罩内空气后用另一部手机拨打它的号码","view":"wide","alt":"一个玻璃罩内放着一部手机，罩子侧面接出一根管子连到抽气机上，表示把罩内空气抽出；罩外还有一部手机用于拨打罩内手机的号码","prims":[{"t":"beaker","x":20,"y":14,"w":34,"h":34},{"t":"rect","x":30,"y":36,"w":14,"h":8,"tone":"main","fill":true,"label":"手机"},{"t":"text","x":37,"y":9,"text":"玻璃罩","size":3.2,"tone":"muted"},{"t":"line","x1":54,"y1":20,"x2":72,"y2":20},{"t":"rect","x":72,"y":14,"w":22,"h":12,"tone":"muted","label":"抽气机"},{"t":"text","x":62,"y":40,"text":"用另一部手机拨打它的号码","size":3,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"抽去空气后仍能接通：说明电磁波可以在真空中传播","size":3,"tone":"muted"}]}},{"id":"phy-magnet-6-m1-q1","type":"short","stem":"（1）某调频广播电台发射的电磁波频率是 100 MHz，求它在空气中的波长（取电磁波在空气中的速度等于真空中的速度 3×10⁸ m/s）。（3 分）","answer":"f = 100 MHz = 100 × 10⁶ Hz = 1×10⁸ Hz；由 c = λf 得 λ = c/f = 3×10⁸ m/s ÷ 1×10⁸ Hz = 3 m。","explain":"","tags":["c=λf","单位换算"],"rubric":["把 100 MHz 正确换算成 1×10⁸ Hz","写出公式 λ = c/f（或 c = λf 并正确变形）","算出 λ = 3 m（带单位）"]},{"id":"phy-magnet-6-m1-q2","type":"short","stem":"（2）结合材料说明，微波通信为什么要建中继站或者使用同步通信卫星？（3 分）","answer":"微波大致沿直线传播，不容易绕过障碍物，而地球表面是弯曲的，所以微波不能沿地球表面一直传播到很远的地方。为了让信号传得更远，必须每隔一定距离建一个中继站，把信号接收后再转发出去；或者用同步通信卫星在太空中转发信号，实现远距离甚至跨洲的通信。","explain":"","tags":["微波通信","阅读与理解"],"rubric":["答出微波大致沿直线传播（不容易绕过障碍物）","答出地球表面是弯曲的，微波无法沿地面传播到远方","答出用中继站或同步通信卫星转发信号"]},{"id":"phy-magnet-6-m1-q3","type":"short","stem":"（3）光纤通信中的「光」是不是电磁波？说明它在光导纤维中是怎样传播的。（3 分）","answer":"光是电磁波：可见光、激光都属于电磁波，只是频率（波长）与无线电波不同。激光进入光导纤维后，在纤维的内壁不断发生反射，沿着纤维的方向曲折前进，从而把信息送到远方；光纤通信的损耗小、容量大。","explain":"","tags":["光纤通信","电磁波"],"rubric":["答出光是电磁波（激光属于电磁波）","答出光在纤维内壁不断反射（反射着前进）","答出光纤通信容量大、损耗小（或能远距离传递信息）"]}]},{"id":"phy-magnet-7","title":"能源与可持续发展","subtitle":"人教版九年级 · 第 22 章 能源与可持续发展 · 9b","grade":"9b","tags":["人教版九年级 · 第 22 章 能源与可持续发展"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第 22 章 能源与可持续发展 · 9b"},{"type":"note","title":"问题切入","text":"我们每天用的电是从哪里来的？煤和石油会不会用完？既然能量守恒，为什么还要提倡节约能源？"},{"type":"note","title":"一句话抓住关键","text":"能源按能不能从自然界直接获得分为一次能源和二次能源，按能不能在短期内得到补充分为可再生能源和不可再生能源；能量的转化和转移具有方向性，能量的总量守恒；核能与太阳能是重要的能源，节约能源与开发新能源并重，才能实现可持续发展。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"煤、石油其实是「存了几亿年的太阳能」，用完就没有；风能、太阳能天天有，但能不能稳定使用还要看技术。","walk":["一次能源直接取自自然界；二次能源由一次能源转化而来，电能就是典型的二次能源。","可再生能源短期内能得到补充；不可再生能源用完就没有。","能量的转化和转移有方向性，所以能源问题不只是「还有多少」的问题。"],"try":"记录家里一天的用电量，想一想这些电是从哪种能源转化来的。","use":["分类题：先看是否直接取自自然，再看能否短期补充。","节能的两条路：提高转化效率、减少浪费。"]},{"type":"h","text":"先看现象：我们使用的能源从哪里来"},{"type":"p","text":"做饭用的天然气、汽车烧的汽油、冬天取暖的煤、家里用的电，都来自能源。煤、石油、天然气是埋在地下的化石能源；水能、风能、太阳能、地热能、潮汐能来自自然界的运动与变化；核能则来自原子核的变化。这些能源并不是都能直接拿来用：我们最常用的电能，就是由煤、水能、风能、核能等经过发电厂转化而来的。"},{"type":"figure","figure":{"id":"fig-magnet-energy-source-1","title":"电能是从哪里来的","caption":"电能由各种一次能源转化而来，所以它本身属于二次能源","view":"wide","alt":"方框图：煤、石油、水能、风能、核能等能源都通过箭头汇入发电厂或发电机，再由发电机输出电能","prims":[{"t":"text","x":50,"y":6,"text":"我们使用的电能，来自各种能源的转化","size":3.4,"tone":"muted"},{"t":"rect","x":2,"y":14,"w":16,"h":9,"tone":"main","fill":true,"label":"煤"},{"t":"rect","x":20,"y":14,"w":16,"h":9,"tone":"main","fill":true,"label":"石油"},{"t":"rect","x":38,"y":14,"w":16,"h":9,"tone":"main","fill":true,"label":"水能"},{"t":"rect","x":56,"y":14,"w":16,"h":9,"tone":"main","fill":true,"label":"风能"},{"t":"rect","x":74,"y":14,"w":16,"h":9,"tone":"main","fill":true,"label":"核能"},{"t":"arrow","x1":10,"y1":23,"x2":34,"y2":32,"tone":"muted"},{"t":"arrow","x1":28,"y1":23,"x2":42,"y2":32,"tone":"muted"},{"t":"arrow","x1":46,"y1":23,"x2":50,"y2":32,"tone":"muted"},{"t":"arrow","x1":64,"y1":23,"x2":58,"y2":32,"tone":"muted"},{"t":"arrow","x1":82,"y1":23,"x2":66,"y2":32,"tone":"muted"},{"t":"rect","x":30,"y":32,"w":40,"h":10,"tone":"accent","label":"发电厂（发电机）"},{"t":"arrow","x1":50,"y1":42,"x2":50,"y2":48,"tone":"accent"},{"t":"rect","x":38,"y":48,"w":24,"h":10,"tone":"ok","fill":true,"label":"电能"},{"t":"text","x":50,"y":61,"text":"电能必须由其他能源转化而来，属于二次能源","size":3,"tone":"muted"}]}},{"type":"h","text":"第一个分类标准：一次能源与二次能源"},{"type":"p","text":"按「能不能从自然界直接获得」，能源分为一次能源和二次能源。煤、石油、天然气、水能、风能、太阳能、核能、地热能等可以从自然界直接取得，是一次能源；电能、汽油、柴油、焦炭、氢气等不能从自然界直接取得，必须由一次能源转化而来，是二次能源。同一个分类里，一次能源既可能是可再生的（水能、风能），也可能是不可再生的（煤、石油），两者不要混在一起说。"},{"type":"figure","figure":{"id":"fig-magnet-energy-class-1","title":"一次能源与二次能源","caption":"判断依据只有一条：能不能从自然界直接获得","view":"wide","alt":"左右两栏对比：左栏是一次能源，说明可以直接从自然界获得，列举煤、石油、天然气、水能、风能、太阳能、核能；右栏是二次能源，说明必须由一次能源转化而来，列举电能、汽油、柴油、焦炭","prims":[{"t":"rect","x":3,"y":10,"w":44,"h":10,"tone":"main","fill":true,"label":"一次能源"},{"t":"text","x":25,"y":27,"text":"能从自然界直接获得","size":3.2,"tone":"muted"},{"t":"text","x":25,"y":35,"text":"煤、石油、天然气","size":3.2,"tone":"muted"},{"t":"text","x":25,"y":42,"text":"水能、风能、太阳能、核能","size":3.2,"tone":"muted"},{"t":"rect","x":53,"y":10,"w":44,"h":10,"tone":"accent","fill":true,"label":"二次能源"},{"t":"text","x":75,"y":27,"text":"必须由一次能源转化而来","size":3.2,"tone":"muted"},{"t":"text","x":75,"y":35,"text":"电能、汽油、柴油","size":3.2,"tone":"muted"},{"t":"text","x":75,"y":42,"text":"焦炭、氢气","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"分类标准一：能不能从自然界直接获得","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"电能是最常考的二次能源：自然界里没有现成的电能，它总是转化来的。"},{"type":"h","text":"第二个分类标准：可再生能源与不可再生能源"},{"type":"p","text":"按「能不能在短期内从自然界得到补充」，能源分为可再生能源和不可再生能源。水能、风能、太阳能、生物质能、地热能、潮汐能可以在自然界里不断得到补充，属于可再生能源；煤、石油、天然气、核燃料（如铀）的形成需要漫长的地质年代，用一点少一点，属于不可再生能源。两个分类标准是彼此独立的：同一种能源在一次能源与二次能源里分类，又在可再生与不可再生里分类，答题时要看清问的是哪一个标准。"},{"type":"figure","figure":{"id":"fig-magnet-energy-class-2","title":"可再生能源与不可再生能源","caption":"判断依据：能不能在短期内从自然界得到补充","view":"wide","alt":"左右两栏对比：左栏是可再生能源，包括水能、风能、太阳能、生物质能、地热能、潮汐能；右栏是不可再生能源，包括煤、石油、天然气和核燃料","prims":[{"t":"rect","x":3,"y":10,"w":44,"h":10,"tone":"ok","fill":true,"label":"可再生能源"},{"t":"text","x":25,"y":27,"text":"能在自然界不断得到补充","size":3.2,"tone":"muted"},{"t":"text","x":25,"y":35,"text":"水能、风能、太阳能","size":3.2,"tone":"muted"},{"t":"text","x":25,"y":42,"text":"生物质能、地热能、潮汐能","size":3.2,"tone":"muted"},{"t":"rect","x":53,"y":10,"w":44,"h":10,"tone":"danger","fill":true,"label":"不可再生能源"},{"t":"text","x":75,"y":27,"text":"形成需要漫长的时间","size":3.2,"tone":"muted"},{"t":"text","x":75,"y":35,"text":"煤、石油、天然气","size":3.2,"tone":"muted"},{"t":"text","x":75,"y":42,"text":"核燃料（如铀）","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"分类标准二：能不能在短期内得到补充","size":3.2,"tone":"muted"}]}},{"type":"h","text":"建立关系：能量的转化守恒与方向性"},{"type":"p","text":"能源被利用的过程就是能量转化的过程。以汽车为例：燃料的化学能通过燃烧转化为内能，内能再通过热机做功转化为机械能，机械能推动汽车前进；同时有相当一部分内能以废气、冷却水的形式散失到空气中。第 14 章学过的能量守恒定律在这里同样成立：能量既不会凭空产生，也不会凭空消失，它只会从一种形式转化为其他形式，或者从一个物体转移到其他物体，能量的总量保持不变。但要特别注意：能量的转化和转移是有方向性的——热量总是自发地从高温物体传给低温物体，散失到空气中的内能不可能自动聚集起来重新驱动汽车。所以「能量守恒」不等于「能源用之不竭」：我们真正缺少的是可以方便利用的高品质能量。"},{"type":"figure","figure":{"id":"fig-magnet-energy-flow-1","title":"汽车中能量的转化与散失","caption":"化学能转化为内能、再转化为机械能，同时有相当一部分内能散失到空气中，无法自动重新利用","view":"wide","alt":"方框图：燃料的化学能经燃烧转化为内能，内能通过做功转化为机械能使汽车前进；同时有一部分内能以散失的形式离开，散失到空气中的内能不能自动收集起来重新利用","prims":[{"t":"text","x":50,"y":9,"text":"能量的转化和转移具有方向性：总量守恒，可利用的品质在降低","size":3,"tone":"muted"},{"t":"rect","x":2,"y":22,"w":24,"h":12,"tone":"main","fill":true,"label":"燃料的化学能"},{"t":"arrow","x1":26,"y1":28,"x2":38,"y2":28,"tone":"accent","label":"燃烧"},{"t":"rect","x":38,"y":22,"w":20,"h":12,"tone":"danger","fill":true,"label":"内能"},{"t":"arrow","x1":58,"y1":28,"x2":70,"y2":28,"tone":"accent","label":"做功"},{"t":"rect","x":70,"y":22,"w":24,"h":12,"tone":"ok","fill":true,"label":"机械能"},{"t":"text","x":82,"y":40,"text":"推动汽车前进","size":3,"tone":"muted"},{"t":"arrow","x1":46,"y1":34,"x2":46,"y2":44,"tone":"muted","label":"散失","labelDx":8},{"t":"text","x":50,"y":54,"text":"散失到空气中的内能不能自动聚集起来重新做功","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"所以必须不断消耗燃料——能量守恒不等于能源用不完","size":3,"tone":"muted"}]}},{"type":"note","title":"","text":"答题时要分清两句话：「能量守恒」说的是总量，「能源危机」说的是可利用的高品质能量。"},{"type":"h","text":"再想一层：核能与太阳能"},{"type":"p","text":"核能是原子核发生变化时释放出的能量，获得核能有两条途径。一是核裂变：用中子轰击较重的原子核（如铀核），使它分裂成两个较小的原子核，同时释放出大量的能量，核电站就是利用可控的核裂变来发电的。二是核聚变：使较轻的原子核结合成较重的原子核，同时释放能量，太阳内部发生的就是核聚变，氢弹也利用核聚变。太阳能就是太阳内部核聚变释放的能量，它以电磁波的形式向外辐射；太阳能清洁、分布广，但受天气和昼夜影响，需要用太阳能电池把光能转化为电能，或用集热器把光能转化为内能。"},{"type":"figure","figure":{"id":"fig-magnet-nuclear-1","title":"获得核能的两条途径","caption":"重核分裂是核裂变（核电站），轻核结合是核聚变（太阳内部）","view":"wide","alt":"左图：一个重核被中子轰击后分裂成两个较小的原子核，并放出中子；右图：两个轻核结合成一个较重的原子核，两者都释放能量","prims":[{"t":"text","x":50,"y":4,"text":"获得核能的两条途径","size":3.4,"tone":"muted"},{"t":"circle","cx":22,"cy":14,"r":6,"tone":"main","fill":true},{"t":"text","x":22,"y":14,"text":"重核","size":3},{"t":"arrow","x1":17,"y1":18,"x2":11,"y2":27,"tone":"accent"},{"t":"arrow","x1":27,"y1":18,"x2":33,"y2":27,"tone":"accent"},{"t":"circle","cx":9,"cy":31,"r":4.5,"tone":"accent","fill":true},{"t":"circle","cx":35,"cy":31,"r":4.5,"tone":"accent","fill":true},{"t":"circle","cx":20,"cy":25,"r":1.6,"tone":"muted"},{"t":"circle","cx":26,"cy":28,"r":1.6,"tone":"muted"},{"t":"text","x":22,"y":42,"text":"核裂变：重核分裂成两个较小的核","size":3,"tone":"muted"},{"t":"text","x":22,"y":48,"text":"核电站利用可控核裂变发电","size":3,"tone":"muted"},{"t":"circle","cx":62,"cy":14,"r":4,"tone":"accent","fill":true},{"t":"circle","cx":74,"cy":14,"r":4,"tone":"accent","fill":true},{"t":"arrow","x1":64,"y1":18,"x2":70,"y2":25,"tone":"accent"},{"t":"arrow","x1":72,"y1":18,"x2":66,"y2":25,"tone":"accent"},{"t":"circle","cx":68,"cy":31,"r":6,"tone":"main","fill":true},{"t":"text","x":68,"y":31,"text":"新核","size":3},{"t":"text","x":68,"y":42,"text":"核聚变：轻核结合成较重的核","size":3,"tone":"muted"},{"t":"text","x":68,"y":48,"text":"太阳内部发生的就是核聚变","size":3,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"核能属于不可再生能源，利用时必须严格控制、确保安全","size":3,"tone":"muted"}]}},{"type":"h","text":"换个情境：节能与开发新能源"},{"type":"p","text":"煤、石油、天然气这些不可再生能源用一点少一点，大量燃烧还会造成环境污染；核能虽然能量巨大，但存在安全和核废料处理的问题。因此，解决能源问题必须两条腿走路：一方面节约能源、提高能源的利用率，例如改进技术减少损耗、随手关灯、绿色出行；另一方面积极开发新能源，如太阳能、风能、水能、地热能、潮汐能、生物质能。能源的可持续发展，就是既满足当代人的需要，又不损害子孙后代满足其需要的能力。"},{"type":"figure","figure":{"id":"fig-magnet-sustainable-1","title":"能源与可持续发展","caption":"节约能源与开发新能源并重，才能实现可持续发展","view":"wide","alt":"方框图：节约能源与开发新能源两条途径并列，节约能源的做法是提高利用率、减少损耗，开发新能源的例子是太阳能、风能、水能、核能；下方说明可持续发展既满足当代人的需要，又不损害子孙后代满足其需要的能力","prims":[{"t":"text","x":50,"y":8,"text":"能源与可持续发展","size":3.8,"tone":"muted"},{"t":"rect","x":4,"y":20,"w":38,"h":14,"tone":"ok","fill":true,"label":"节约能源"},{"t":"text","x":23,"y":42,"text":"提高利用率、减少损耗","size":3.2,"tone":"muted"},{"t":"arrow","x1":42,"y1":27,"x2":58,"y2":27,"tone":"main","both":true},{"t":"rect","x":58,"y":20,"w":38,"h":14,"tone":"accent","fill":true,"label":"开发新能源"},{"t":"text","x":77,"y":42,"text":"太阳能、风能、水能等","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"既满足当代人的需要，又不损害子孙后代满足其需要的能力","size":3,"tone":"muted"},{"t":"text","x":50,"y":59,"text":"能量守恒不等于能源用之不竭：既要节能，也要开发新能源","size":3,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["燃料完全燃烧放出的热量","Q = qm","Q：热量（J）；q：燃料的热值（J/kg）；m：燃料的质量（kg） · 用于固体和液体燃料。气体燃料要用 Q = qV，其中 V 是气体体积（m³），q 的单位是 J/m³。注意两点：一是公式算的是「完全燃烧」放出的热量，实际燃烧往往不完全；二是 q 必须取这种燃料本身的热值，不能张冠李戴。变形用法：m = Q/q 求燃料质量，q = Q/m 求热值。"],["热机（燃料利用）的效率","η = Q_(有用)Q_(总) × 100%","η 用百分数表示；Q有用 是被有效利用的能量，Q总 是燃料完全燃烧放出的热量 · 燃料燃烧放出的热量不会全部变成有用功，一部分随废气、冷却水散失，所以效率一定小于 100%。由它可求有用功 W = ηQ总，也可求所需燃料的质量 m = Q总/q = W/(ηq)。答题时不要把「效率」与「功率」混为一谈。"],["能量守恒定律（表述与边界）","能量既不会凭空产生，也不会凭空消失，它只会从一种形式转化为其他形式，或者从一个物体转移到其他物体，而能量的总量保持不变","它说明「能量不会消失」，但不能据此认为「能源取之不尽」：能量的转化和转移具有方向性，散失到环境中的内能不能自动聚集起来重新利用，所以我们真正缺少的是可以方便利用的高品质能量。答题时要分清「能量守恒」与「能源危机」这两句话，这正是本知识点最爱考的地方。"],["电能的单位换算","1 kW·h = 3.6×10⁶ J","把家庭用电的「度」换算成国际单位焦耳时用。1 kW·h 表示功率为 1 kW（1000 W）的用电器工作 1 h 消耗的电能，由 W = Pt 得 1000 W × 3600 s = 3.6×10⁶ J。结合「电能是二次能源」可以估算背后消耗的一次能源。"]]},{"type":"h","text":"应用 · 计算机动车燃料放出的热量与输出的机械功"},{"type":"note","title":"情境","text":"某汽车行驶 100 km，消耗汽油 8 kg。已知汽油的热值 q = 4.6×10⁷ J/kg，发动机的效率是 30%。"},{"type":"note","title":"模型与思路","text":"燃料完全燃烧放出的热量用 Q = qm 计算；热机的效率 η 是有用功与燃料完全燃烧放出热量之比，所以有用功 W = ηQ。"},{"type":"list","title":"解答步骤","items":["燃料完全燃烧放出的热量：Q = qm = 4.6×10⁷ J/kg × 8 kg = 3.68×10⁸ J。","发动机的效率 η = 30%，输出的机械功 W = ηQ = 30% × 3.68×10⁸ J = 1.104×10⁸ J ≈ 1.1×10⁸ J。","其余约 70% 的热量主要通过废气、冷却水散失到空气中，成为内能。"]},{"type":"note","title":"结论","text":"8 kg 汽油完全燃烧放出约 3.68×10⁸ J 的热量，其中约 1.1×10⁸ J 转化为有用的机械功，其余大部分以内能的形式散失。"},{"type":"h","text":"应用 · 电能为什么是二次能源"},{"type":"note","title":"情境","text":"小明家一个月用了 100 kW·h 的电，电表上显示的就是这些电能（1 kW·h = 3.6×10⁶ J）。"},{"type":"note","title":"模型与思路","text":"电能是二次能源：它由一次能源转化而来。把「度」换算成焦耳，可以看出这背后要消耗多少一次能源。"},{"type":"list","title":"解答步骤","items":["电能不能在自然界直接获得，它由煤、水能、风能、核能等一次能源转化而来，所以电能属于二次能源。","换算单位：100 kW·h = 100 × 3.6×10⁶ J = 3.6×10⁸ J。","这些电能如果由火力发电厂提供，就要消耗相当数量的燃料，而燃料燃烧还会带来污染，所以节约用电就是节约一次能源、减少污染。"]},{"type":"note","title":"结论","text":"100 kW·h 的电能相当于 3.6×10⁸ J；电能是二次能源，节约用电对节约一次能源和保护环境都有意义。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为电能是一次能源，或者认为汽油、柴油是一次能源。","电能、汽油、柴油都是由一次能源加工转化而来的，属于二次能源。","分类标准是「能不能从自然界直接获得」：自然界里没有现成的电能和汽油，它们都经过人工转化。煤、石油、天然气可以直接开采出来，才是一次能源。"],["认为既然能量守恒，就不会发生能源危机。","能量总量守恒，但能量的转化和转移具有方向性，散失到环境中的内能不能自动聚集起来重新利用，可以方便利用的高品质能源会越来越少。","汽车散失到空气中的内能总量并没有减少，但它已经分散、降温，不能再自动用来做功。所以「守恒」说的是总量，「危机」说的是可利用性，两句话都对，不能互相否定。"],["认为核电站利用的是核聚变，或者认为核能是可再生能源。","核电站利用的是可控的核裂变；核燃料（如铀）储量有限、属于不可再生能源。","核聚变发生在太阳内部和氢弹中，目前人类还不能实现可控核聚变发电。核燃料形成需要漫长的时间、用一点少一点，因此是不可再生能源。"]]},{"type":"table","title":"一次能源与二次能源（能不能从自然界直接获得）","head":["比较项","一次能源","二次能源"],"rows":[["定义","可以从自然界直接获得的能源","不能从自然界直接获得，必须由一次能源转化而来的能源"],["举例","煤、石油、天然气、水能、风能、太阳能、核能、地热能","电能、汽油、柴油、焦炭、氢气"],["与另一个分类的关系","既可能是可再生的（水能、风能），也可能是不可再生的（煤、石油）","都由一次能源转化而来，本身不再用可再生、不可再生来划分"]]},{"type":"table","title":"可再生能源与不可再生能源（能不能在短期内从自然界得到补充）","head":["比较项","可再生能源","不可再生能源"],"rows":[["能否补充","可以在自然界里不断得到补充，短期内能够再生","形成需要漫长的地质年代，用一点少一点"],["举例","水能、风能、太阳能、生物质能、地热能、潮汐能","煤、石油、天然气、核燃料"],["利用时要注意","清洁、污染小，但受自然条件影响（风力、日照不稳定）","燃烧会污染环境，应当节约使用、提高利用率"]]},{"type":"table","title":"核裂变与核聚变（获得核能的两条途径）","head":["比较项","核裂变","核聚变"],"rows":[["过程","用中子轰击较重的原子核，使它分裂成两个较小的原子核","使较轻的原子核结合成较重的原子核"],["实例","核电站发电、原子弹","太阳内部释放能量、氢弹"],["能否可控利用","已经能够可控利用（核电站的核反应堆）","目前还不能实现可控核聚变发电，仍在研究之中"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["能源分类的判断","给出若干种能源，要求按「一次能源与二次能源」或「可再生能源与不可再生能源」分类，也可能要求同时按两个标准作答。易错点：把电能当成一次能源；把核能当成可再生能源；把两个分类标准混在一句话里说。"],["热值与效率的计算","用 Q = qm（固体、液体燃料）或 Q = qV（气体燃料）算燃料完全燃烧放出的热量，再用 η = Q有用/Q总 求效率，或反过来求燃料质量。要注意区分「放出的总热量」与「有用的机械功」，并注意热值单位与质量、体积的对应关系。"],["能量的转化与守恒、能量的方向性","常以汽车、发电、烧水为情境，要求写出能量转化过程，并追问「为什么散失的内能不能自动重新利用」。答题必须点出「能量的转化和转移具有方向性」，只说「能量守恒」得不了分。"],["能源与可持续发展（开放题）","以能源结构、节能措施、新能源开发为背景，要求提出建议或作出评价。作答要具体、可操作，如「提高能源利用率」「开发太阳能、风能等新能源」「绿色出行」，不要空喊口号，也不要引用记不准的统计数字。"]]},{"type":"quote","text":"【材料】能源可以按不同的标准分类。按照能不能从自然界直接获得，能源分为一次能源和二次能源；按照能不能在短期内从自然界得到补充，能源分为可再生能源和不可再生能源。煤、石油、天然气是埋在地下的化石能源，它们的形成需要漫长的地质年代，用一点少一点；水能、风能、太阳能可以在自然界里不断得到补充。\n【情景】某同学用酒精炉加热水，实验中酒精完全燃烧，用去酒精 0.02 kg。已知酒精的热值是 3.0×10⁷ J/kg。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）按照两个分类标准，分别说明煤、石油、天然气属于哪一类能源。（4 分）","【设问】（2）水能和风能属于哪类能源？请写出利用它们的两个优点。（4 分）","【设问】（3）这次实验中酒精完全燃烧放出的热量是多少？（3 分）"]}],"questions":[{"id":"phy-magnet-7-q1","type":"choice","stem":"下列能源中，全部属于可再生能源的一组是","answer":"B","explain":"B 正确：水能、风能、太阳能都能在自然界里不断得到补充，属于可再生能源。A 错：煤、石油、天然气都是化石能源，形成需要漫长的时间，属于不可再生能源。C 错：核燃料和煤都不可再生。D 错：天然气和核燃料都不可再生，只有风能是可再生的。","options":["煤、石油、天然气","水能、风能、太阳能","核能、煤、水能","天然气、风能、核能"],"difficulty":1,"tags":["可再生能源"]},{"id":"phy-magnet-7-q2","type":"choice","stem":"关于能量的转化和守恒，下列说法正确的是","answer":"A","explain":"A 正确：能量守恒定律告诉我们总量不变；同时，能量的转化和转移是有方向性的，热量总是自发地从高温物体传给低温物体。B 错：能量总量守恒，但可方便利用的高品质能量会越来越少，仍会有能源问题。C 错：散失到空气中的内能已经分散、降温，不能自动聚集起来重新做功，这正体现了方向性。D 错：能量不会消失，只会转化为其他形式。","options":["能量在转化和转移的过程中总量保持不变，但转化和转移具有方向性","因为能量守恒，所以能源永远不会用完","汽车散失到空气中的内能可以自动聚集起来重新驱动汽车","能量在转化的过程中会不断减少，最后消失"],"difficulty":2,"tags":["能量守恒","方向性"]},{"id":"phy-magnet-7-q3","type":"choice","stem":"如图是汽车行驶时能量转化的方框图，方框 A 中应填的能量形式是","answer":"D","explain":"D 正确：燃料在气缸中燃烧，把化学能转化为燃气的内能，内能再通过做功转化为机械能，所以 A 处应填「内能」。A 错：燃烧过程中没有明显的光能输出（不是主要形式）。B 错：汽车不是靠电能驱动的（本题没有涉及电动机）。C 错：化学能是方框前面已经写出的输入形式，不是 A 处的答案。","options":["光能","电能","化学能","内能"],"difficulty":2,"tags":["能量转化"],"figure":{"id":"fig-magnet-q3-7","title":"汽车行驶时能量转化的方框图","caption":"燃料的化学能经过方框 A 转化为机械能","view":"wide","alt":"方框图：燃料的化学能经过箭头「燃烧」指向方框 A，方框 A 再经过箭头「做功」指向机械能；方框 A 中还没有填写能量形式","prims":[{"t":"rect","x":2,"y":22,"w":26,"h":13,"tone":"main","fill":true,"label":"燃料的化学能"},{"t":"arrow","x1":28,"y1":28.5,"x2":40,"y2":28.5,"tone":"accent","label":"燃烧"},{"t":"rect","x":40,"y":22,"w":20,"h":13,"tone":"danger","label":"A"},{"t":"arrow","x1":60,"y1":28.5,"x2":72,"y2":28.5,"tone":"accent","label":"做功"},{"t":"rect","x":72,"y":22,"w":26,"h":13,"tone":"ok","fill":true,"label":"机械能"},{"t":"text","x":50,"y":12,"text":"汽车行驶时的能量转化","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":50,"text":"还有一部分能量随废气、冷却水散失到空气中","size":3.2,"tone":"muted"}]}},{"id":"phy-magnet-7-q4","type":"choice","stem":"关于核能与太阳能，下列说法正确的是","answer":"C","explain":"C 正确：太阳内部持续进行核聚变，释放出巨大的能量；核电站的核反应堆利用的是可控核裂变。A 错：核电站利用的是核裂变，核聚变目前还不能实现可控发电。B 错：太阳能可以在自然界不断得到补充，是可再生能源。D 错：核燃料（如铀）可以直接从自然界开采，核能属于一次能源。","options":["核电站是利用核聚变释放的能量来发电的","太阳能属于不可再生能源","太阳内部发生的是核聚变，核电站利用的是可控的核裂变","核能是由其他能源转化而来的二次能源"],"difficulty":2,"tags":["核能","太阳能"]},{"id":"phy-magnet-7-q5","type":"choice","stem":"关于能源与可持续发展，下列说法正确的是","answer":"B","explain":"B 正确：解决能源问题要两条腿走路——节约能源与提高利用率、开发新能源并重。A 错：煤、石油、天然气是不可再生能源，用一点少一点，还带来环境污染。C 错：即使开发了新能源，节约能源、减少浪费仍然是必要的，两者并不互相替代。D 错：随手关灯、绿色出行等个人行为同样能节约能源、减少排放。","options":["煤、石油、天然气属于可再生能源，可以放心使用","既要节约能源、提高能源的利用率，又要积极开发太阳能、风能等新能源","只要开发出足够多的新能源，就不必再节约能源了","能源问题只与发电厂有关，与个人的日常生活无关"],"difficulty":1,"tags":["可持续发展"]},{"id":"phy-magnet-7-q6","type":"fill","stem":"电能属于____能源（选填「一次」或「二次」）。","answer":"二次","explain":"判断依据是「能不能从自然界直接获得」：自然界里没有现成的电能，我们用的电都由煤、水能、风能、核能等一次能源转化而来，所以电能是二次能源。汽油、柴油、焦炭也属于二次能源。","difficulty":1,"tags":["能源分类"]},{"id":"phy-magnet-7-q7","type":"short","stem":"如图是汽车行驶时能量转化的方框图。请完成：① 在方框 A、B 中填出对应的能量形式；② 汽车行驶时有一部分能量散失到空气中，请说明这部分能量为什么不能自动收集起来重新驱动汽车。","answer":"① 方框 A 填「内能」，方框 B 填「机械能」：燃料的化学能通过燃烧转化为内能，内能通过做功转化为机械能。② 因为能量的转化和转移具有方向性：内能总是自发地从高温物体传给低温物体，散失到空气中的内能温度已经很低，而且分散在很大的空间里，不能再自动聚集起来重新用来做功。所以汽车要持续前进，就必须不断消耗燃料。","explain":"①要按「燃烧—做功」的顺序想：燃烧把化学能变成燃气的内能，内能对外做功才变成机械能，顺序不能颠倒。②的关键词是「方向性」：热量只能自发地从高温物体传给低温物体，内能一旦分散到空气中就无法自动「回收」。常见错误是答成「能量消失了」或「能量减少了」——能量并没有消失，只是变得难以利用，这正是「能量守恒」与「能源危机」并不矛盾的原因。","difficulty":3,"tags":["能量转化","方向性"],"rubric":["① A 处填「内能」","① B 处填「机械能」（并说明化学能→内能→机械能的转化顺序）","② 答出能量的转化和转移具有方向性","② 说明散失的内能分散、降温，不能自动聚集起来重新做功"],"steps":["① 方框 A：化学能经燃烧转化为内能；方框 B：内能经做功转化为机械能。","② 先点明规律：能量的转化和转移具有方向性。","② 再解释现象：散失到空气中的内能分散且温度低，不能自动聚集起来重新做功。"],"figure":{"id":"fig-magnet-q7-9","title":"待完成的图：填出能量形式","caption":"方框 A、B 中还没有填写能量形式","view":"wide","alt":"方框图：燃料的化学能经过箭头「燃烧」指向方框 A，方框 A 经过箭头「做功」指向方框 B，两个方框中都还没有填写能量形式","prims":[{"t":"rect","x":2,"y":20,"w":26,"h":13,"tone":"main","fill":true,"label":"燃料的化学能"},{"t":"arrow","x1":28,"y1":26.5,"x2":40,"y2":26.5,"tone":"accent","label":"燃烧"},{"t":"rect","x":40,"y":20,"w":20,"h":13,"tone":"danger","label":"A"},{"t":"arrow","x1":60,"y1":26.5,"x2":72,"y2":26.5,"tone":"accent","label":"做功"},{"t":"rect","x":72,"y":20,"w":26,"h":13,"tone":"ok","label":"B"},{"t":"text","x":50,"y":10,"text":"汽车行驶时的能量转化","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"在方框 A、B 中填出能量形式，并说明散失的能量为什么不能重新利用","size":3,"tone":"muted"}]},"answerFigure":{"id":"fig-magnet-q7-10","title":"答案图：化学能→内能→机械能，同时有能量散失","caption":"燃料的化学能经燃烧变为内能，内能经做功变为机械能；散失的内能不能自动重新利用","view":"wide","alt":"方框图：燃料的化学能经燃烧转化为内能，内能经做功转化为机械能；另有一个向下的箭头表示一部分内能散失到空气中，散失的内能不能自动聚集起来重新做功","prims":[{"t":"rect","x":2,"y":22,"w":26,"h":13,"tone":"main","fill":true,"label":"燃料的化学能"},{"t":"arrow","x1":28,"y1":28.5,"x2":38,"y2":28.5,"tone":"accent","label":"燃烧"},{"t":"rect","x":38,"y":22,"w":20,"h":13,"tone":"danger","fill":true,"label":"内能"},{"t":"arrow","x1":58,"y1":28.5,"x2":68,"y2":28.5,"tone":"accent","label":"做功"},{"t":"rect","x":68,"y":22,"w":30,"h":13,"tone":"ok","fill":true,"label":"机械能"},{"t":"arrow","x1":48,"y1":35,"x2":48,"y2":46,"tone":"muted","label":"散失","labelDx":8},{"t":"text","x":50,"y":55,"text":"散失到空气中的内能分散、降温，不能自动重新做功","size":3,"tone":"muted"},{"t":"text","x":50,"y":59.5,"text":"这体现了能量转化和转移的方向性","size":3,"tone":"muted"}]}},{"id":"phy-magnet-7-q8","type":"short","stem":"某小组想比较酒精和碎纸片两种燃料的热值大小。他们取两个相同的烧杯，装入质量和初温都相同的水，再分别用质量相同的酒精和碎纸片给水加热（燃料都完全燃烧），记录水升高的温度。请回答：① 实验中需要控制哪些量相同？② 怎样比较两种燃料热值的大小？③ 若用酒精加热的那杯水温度升高得较多，说明了什么？","answer":"① 需要控制：两个烧杯相同，水的质量和初温相同，两种燃料的质量相同，燃料都要完全燃烧，并且两次实验的装置与散热情况尽量相同。② 比较水升高的温度：水升高的温度越多，说明该燃料完全燃烧放出的热量越多；在燃料质量相同时，放出的热量越多，热值就越大。③ 说明质量相同的酒精完全燃烧放出的热量比碎纸片多，即酒精的热值比碎纸片的热值大。","explain":"这是一个「转换法 + 控制变量法」的经典实验：燃料放热的多少看不见，就用水升高的温度来反映（转换）；要比较两种燃料，就必须让水、烧杯、燃料质量等条件相同，只让燃料的种类不同（控制变量）。判断结论时抓住「质量相同比放热，放热多的热值大」。常见错误是只写「加热时间长」「火焰大」这类现象，而没有落到「水升高的温度」这个可比的数据上。","difficulty":3,"tags":["实验探究","热值"],"rubric":["① 答出水的质量和初温相同","① 答出两种燃料的质量相同、都要完全燃烧","② 答出通过比较水升高的温度来比较放热的多少（转换法）","③ 答出酒精的热值比碎纸片大"],"steps":["① 列出需要控制相同的量：烧杯、水的质量、水的初温、燃料的质量、完全燃烧。","② 写出比较方法：用水升高的温度反映燃料完全燃烧放出的热量。","③ 由「温度升高得多 → 放热多 → 热值大」得出结论。"],"figure":{"id":"fig-magnet-q8-7","title":"比较酒精与碎纸片的热值","caption":"两个相同的烧杯装质量、初温相同的水，用质量相同的两种燃料加热","view":"wide","alt":"两个相同的烧杯里装着质量相同的水，各插一支温度计；左边的烧杯用酒精加热，右边的烧杯用碎纸片加热","prims":[{"t":"text","x":50,"y":5,"text":"比较酒精与碎纸片的热值","size":3.4,"tone":"muted"},{"t":"beaker","x":6,"y":20,"w":20,"h":20,"fill":0.55},{"t":"text","x":16,"y":33,"text":"水","size":3.4,"tone":"muted"},{"t":"thermometer","x":14,"y":12,"h":24,"value":0.6,"label":"温度计"},{"t":"rect","x":8,"y":42,"w":16,"h":6,"tone":"accent","fill":true,"label":"酒精"},{"t":"beaker","x":54,"y":20,"w":20,"h":20,"fill":0.55},{"t":"text","x":64,"y":33,"text":"水","size":3.4,"tone":"muted"},{"t":"thermometer","x":62,"y":12,"h":24,"value":0.5,"label":"温度计"},{"t":"rect","x":56,"y":42,"w":18,"h":6,"tone":"accent","fill":true,"label":"碎纸片"},{"t":"text","x":50,"y":55,"text":"水升高的温度越多，说明燃料完全燃烧放出的热量越多","size":3,"tone":"muted"}]}},{"id":"phy-magnet-7-q9","type":"short","stem":"某汽车行驶 100 km 消耗汽油 6 kg。已知汽油的热值 q = 4.6×10⁷ J/kg，发动机的效率是 30%。求：① 6 kg 汽油完全燃烧放出的热量；② 发动机输出的机械功。","answer":"① Q = qm = 4.6×10⁷ J/kg × 6 kg = 2.76×10⁸ J。② W = ηQ = 30% × 2.76×10⁸ J = 8.28×10⁷ J。","explain":"本题两步走的思路要清楚：先用 Q = qm 算出燃料完全燃烧放出的总热量，再乘效率得到有用的机械功，因为效率 η = W/Q 表示「放出的热量中有多少变成了有用的机械功」。常见错误有两个：把 2.76×10⁸ J 直接当成机械功（漏乘效率）；或者把效率乘错方向（用 Q÷η，算出比总热量还大的机械功——这显然违背能量守恒）。","difficulty":2,"tags":["热值","效率计算"],"rubric":["① 写出公式 Q = qm 并算出 2.76×10⁸ J（带单位）","② 写出效率关系式 W = ηQ","② 算出 8.28×10⁷ J（带单位）"],"steps":["① 已知 q = 4.6×10⁷ J/kg、m = 6 kg；Q = qm = 4.6×10⁷ J/kg × 6 kg = 2.76×10⁸ J。","② 已知 η = 30%；由 η = W/Q 得 W = ηQ = 0.3 × 2.76×10⁸ J = 8.28×10⁷ J。","③ 说明其余热量主要通过废气和冷却水散失，成为内能。"]},{"id":"phy-magnet-7-m1-q1","type":"short","stem":"（1）按照两个分类标准，分别说明煤、石油、天然气属于哪一类能源。（4 分）","answer":"按能不能从自然界直接获得分类：煤、石油、天然气都可以直接从自然界开采出来，属于一次能源。按能不能在短期内得到补充分类：它们的形成需要漫长的地质年代，短期内无法再生，用一点少一点，属于不可再生能源。","explain":"","tags":["能源分类"],"rubric":["答出煤、石油、天然气属于一次能源","说明理由：可以从自然界直接获得（直接开采）","答出它们属于不可再生能源","说明理由：形成需要漫长的时间，短期内无法补充"]},{"id":"phy-magnet-7-m1-q2","type":"short","stem":"（2）水能和风能属于哪类能源？请写出利用它们的两个优点。（4 分）","answer":"按能不能从自然界直接获得分类，水能和风能可以从自然界直接获得，属于一次能源；按能不能在短期内得到补充分类，它们可以在自然界里不断得到补充，属于可再生能源。优点：① 清洁，利用时几乎不排放污染物，对环境的影响小；② 可以在自然界不断得到补充，合理开发就不必担心用完。","explain":"","tags":["可再生能源"],"rubric":["答出属于一次能源（或属于可再生能源）","答出属于可再生能源（或一次能源），两个标准都说清","优点一：清洁、污染小","优点二：可再生、能不断得到补充"]},{"id":"phy-magnet-7-m1-q3","type":"short","stem":"（3）这次实验中酒精完全燃烧放出的热量是多少？（3 分）","answer":"Q = qm = 3.0×10⁷ J/kg × 0.02 kg = 6×10⁵ J。","explain":"","tags":["热值","计算"],"rubric":["写出公式 Q = qm","代入 3.0×10⁷ J/kg 与 0.02 kg","算出 6×10⁵ J 并写出单位"]}]}];
